-- SRS review-card backfill — BATCH 8 of 10 (781 rows).
-- Run each batch on its own in the Supabase SQL Editor; order does not matter and
-- each is idempotent. Together the 10 batches equal backfill_srs_payload.sql.
-- Covers Top 2 preboards/mocks/reviewer + main-app banks + Top 2 banks.
WITH d(qid, patch) AS (
  VALUES
  ('97cab99b-2o','{"options": ["DOH Safety Seal", "FDA Product Registration (CPR)", "FDA Medical Device Notification (CMDN)", "POA Certificate"], "correct": 1, "explanation": "Before sale in the Philippines, a new contact lens cleaning SOLUTION must obtain FDA PRODUCT REGISTRATION — a Certificate of Product Registration (CPR). (CMDN is for medical-device notification; lens solutions are registered products.) New solution = FDA CPR."}'),
  ('0f4c4f44-29','{"options": ["Only the store owner", "Qualified Person", "Any allied health professional", "No specific mandate"], "correct": 1, "explanation": "Per FDA guidelines, the QUALIFIED PERSON must be present in the optical shop during operating hours (the responsible competent person, Q71) — not just the owner or any allied professional. Operating hours = QP present."}'),
  ('59a854da-1f','{"options": ["To register medical devices that being distributed by a supplier", "Dispense imported contact lenses only and report adverse effects", "Compliance with FDA storage, safety, and reporting guidelines", "Optical designs are trendy and stored based on the given FDA guidelines"], "correct": 0, "explanation": "The Qualified Person must ensure REGISTRATION of the medical DEVICES being distributed (and overall FDA compliance — storage, safety, reporting). Among the options the QP''s core duty is ensuring distributed devices are registered/compliant. QP = FDA compliance for products distributed."}'),
  ('12733191-1n','{"options": ["Protect brand name and ensure unique identity", "Approve location of clinic and its sanitation", "Certify product quality and ensure efficiency", "Replace mayor’s permit and barangay clearance"], "correct": 0, "explanation": "DTI BUSINESS NAME registration''s primary purpose is to PROTECT the brand/trade name and ensure a UNIQUE business identity (sole right to use it) — not to approve location/sanitation, certify product quality, or replace permits. BN registration = name protection/identity."}'),
  ('45fc870f-2n','{"options": ["Meal allowance", "Overtime pay", "Night differential only", "Holiday pay only"], "correct": 1, "explanation": "Optometrists working mall hours EXCEEDING 8 hours/day are entitled to OVERTIME PAY (Labor Code — work beyond 8 hours = overtime premium). Not merely meal allowance/night-diff/holiday pay. >8 hrs/day = overtime pay."}'),
  ('735a1a4f-1b','{"options": ["Only indigent Filipinos are covered by PhilHealth", "Only employed Filipinos get PhilHealth benefits", "All Filipinos are automatically enrolled in the National Health Insurance Program", "Only those with private HMO get full coverage"], "correct": 2, "explanation": "RA 11223 (UHC Act) ensures ALL Filipinos are AUTOMATICALLY ENROLLED in the National Health Insurance Program (PhilHealth) — universal, not limited to indigents, the employed, or private-HMO holders. UHC = automatic universal PhilHealth (cf. Q85)."}'),
  ('d1c7a245-1c','{"options": ["The patient signs a waiver before consultation agreeing to for the eye examination procedures", "The patient seeks the optometrist’s professional advice and the optometrist agrees to provide care", "The patient pays for optical products recommended by the optometrist based on the result of the eye examination", "The optometrist advertises their services"], "correct": 1, "explanation": "The optometrist-patient relationship BEGINS when the patient SEEKS the optometrist''s professional advice and the optometrist AGREES to provide care (mutual undertaking) — not at waiver-signing, payment, or advertising. Relationship = patient seeks + practitioner accepts."}'),
  ('99ae09e3-1z','{"options": ["Acceptable for product recommendations", "Required for warranty claims on the supplier", "A violation of patient confidentiality", "Encouraged for business relationships"], "correct": 2, "explanation": "Sharing patient information with an EYEWEAR SUPPLIER WITHOUT consent is a VIOLATION OF CONFIDENTIALITY (third-party disclosure of identifiable data) — not justified for recommendations, warranties, or business ties. No-consent third-party sharing = confidentiality breach."}'),
  ('bda4b98f-19','{"options": ["Issue business permits and medical device notification", "Set optical product pricing, standards, and guidelines for CPD units Register new graduates for licensure exams and host their oathtaking program Accredit CPD providers and programs, and evaluate CPD compliance"], "correct": -1, "explanation": "[Source-flagged: options merged.] The CPD COUNCIL''s primary function is to ACCREDIT CPD PROVIDERS and PROGRAMS and EVALUATE CPD COMPLIANCE (under RA 10912) — not pricing, permits, or hosting oath-taking. CPD Council = accredit providers/programs + monitor compliance."}'),
  ('4c854808-5y','{"options": ["Submit the certificate directly to PRC and can be counted for her PRC ID renewal", "Post the certificate on her clinic’s Facebook page with her selfie and tag the PRC page", "Apply for individual accreditation with the CPD Council using supporting documents", "Nothing, as foreign seminars are automatically recognized"], "correct": 2, "explanation": "For CPD from a NON-PRC-accredited foreign conference, Dr. Reyes should APPLY for INDIVIDUAL accreditation with the CPD Council using supporting documents (so the hours can be credited) — foreign seminars aren''t automatically recognized, and posting/selfies don''t count. Non-accredited CPD → apply for individual credit."}'),
  ('56203145-23','{"options": ["₱570 per day", "₱580 per day", "₱460 per day", "₱540 per day"], "correct": 0, "explanation": "EXCLUDED FROM SCORING. No option is correct. The NCR non-agricultural minimum wage was P570/day in mid-2022, P610 from July 2023 and P645 from July 2024, so ''as of 2024'' the answer is P645, which is not listed. The keyed P570 is two wage orders out of date. Fix: change option A to the figure current at your sitting, and update the year in the stem to match. Note this item decays every wage order, so it needs a date check each cycle rather than a one-time repair."}'),
  ('0aa632f9-2v','{"options": ["Overall socioeconomic development", "Concerted public health action", "Increased availability of eye care services", "Priority given to the health budget"], "correct": 3, "explanation": "The three classic drivers of reduced blindness are overall socioeconomic development, concerted public health action, and increased availability of eye-care services. VERIFY: the item treats ''priority given to the health budget'' as the non-factor, though budget priority arguably also helps; confirm the key."}'),
  ('0c1d6bbd-8i','{"options": ["primary", "secondary", "tertiary"], "correct": 1, "explanation": "Detecting longstanding poor vision on screening and correcting it to 20/70 is SECONDARY prevention (early detection plus prompt treatment of an established problem). Primary prevents onset; tertiary rehabilitates."}'),
  ('120cbe2d-2v','{"options": ["Best VA of 20/70 to 20/200", "Best VA of 20/200 to 20/400", "No light perception", "Best VA of 20/50 to 20/70"], "correct": 0, "explanation": "Category I (low vision) corresponds to a best acuity in the 20/70 to 20/200 range. VERIFY: confirm the exact PhilHealth Z-benefit category cutoffs, as these vary by reference and revision."}'),
  ('dd47985b-28','{"options": ["Not less than 2.0 mm", "Not less than 3.0 mm", "Not less than 4.0 mm", "Not less than 8.0 mm"], "correct": 1, "explanation": "Industrial/safety lenses must meet a minimum center thickness of about 3.0 mm (impact standard), so ''not less than 3.0 mm'' is the safety figure. VERIFY: this item was garbled in the source (the option values wrapped across lines), so the choices were reconstructed; confirm against the standard cited."}'),
  ('e953d1c9-4h','{"options": ["C-13", "C-14", "D-14", "D-13"], "correct": 0, "explanation": "VERIFY (obscure ruling): BIR Ruling 105.2 (1949) exempted optometrists from a specific occupation/percentage tax provided they do not sell eyeglasses without an eye examination. The exact letter-number code is uncertain from memory; confirm the classification in the source."}'),
  ('e195bf39-1m','{"options": ["May 1-7", "June 1-7", "August 1-7", "July 1-7"], "correct": 2, "explanation": "VERIFY (date/proclamation specific): Philippine Optometry Week is commonly cited in the first week of August. Confirm the exact dates against the governing proclamation, since options like the first week of other months are easily confused."}'),
  ('8a79614a-3a','{"options": ["all members", "2 members", "5 members", "3 members"], "correct": 3, "explanation": "A majority of the Board (3 of its members) is generally needed to render a decision in an administrative case. VERIFY: confirm the Board''s composition and the exact quorum/decision number under RA 8050 and PRC rules."}'),
  ('e9f57fe0-23','{"options": ["Benoxinate 0.4%", "Cyclopentolate HCL 0.5 %", "Oxybuprocaine 4%", "Pilocarpine 1%"], "correct": 1, "explanation": "The 2008 Board resolution expanded the DPA list, and among these options Cyclopentolate HCl 0.5% is the additional diagnostic agent (pilocarpine is therapeutic, not diagnostic). VERIFY: confirm the precise agent and concentration added by Board of Optometry Resolution 01 s. 2008."}'),
  ('bf26462e-25','{"options": ["Dr. Bernardita Garcia", "Dr. Maria Isabelle Valconcha", "Dr. Charlie Ho", "Dr. Bong Juarezo"], "correct": 0, "explanation": "VERIFY (time-sensitive official): the chairman of the accredited optometry organization changes with each term, so this answer cannot be fixed reliably. Confirm the current chairman of the Optometric Association of the Philippines (OAP) for the exam year."}'),
  ('487780ab-1w','{"options": ["Hon. Antonio Filando Jr.", "Hon. Teofilo Filando Jr.", "Hon. Charito A. Zamora", "Hon. Emerlita Flores"], "correct": 2, "explanation": "VERIFY (time-sensitive official): the PRC chairperson changes by appointment, so this cannot be reliably fixed from memory. Confirm the current PRC chairperson for the exam year."}'),
  ('8552c26a-1r','{"options": ["GT Hermann", "William G. Moore", "Justo Gonzales", "RM Clark"], "correct": 2, "explanation": "VERIFY (historical roster): the members of the first Junta Examinadora (early Philippine optometry board) are a specific historical list; the non-member exception cannot be reliably recalled. Confirm the roster in the source."}'),
  ('f44feefd-1m','{"options": ["Benoxinate HCL 0.5%", "Benoxinate 0.4%", "Cyclopentolate 1.0%", "Phenylephrine 2.5%"], "correct": 0, "explanation": "Benoxinate''s diagnostic concentration is 0.4%, so ''Benoxinate HCl 0.5%'' is the off-list (incorrect-concentration) option. Phenylephrine 2.5% and cyclopentolate are valid DPAs."}'),
  ('e4888069-24','{"options": ["D-15", "D-13", "D-14", "C-13"], "correct": 1, "explanation": "VERIFY (obscure code): this asks for the LGU privilege/occupation tax classification the optometrist pays annually (linked to the BIR occupation-tax codes). The exact letter-number is uncertain; confirm against the source''s coding."}'),
  ('ca2f4889-3q','{"options": ["Pres. Corazon Aquino", "Pres. Ferdinand Marcos", "Pres. Manuel Roxas", "Pres. Fidel V. Ramos"], "correct": 2, "explanation": "VERIFY (history): a Philippine president first proposed a congressional social-security bill for wage earners; the most-cited figure is President Manuel Roxas (late 1940s). Confirm the intended president, as accounts differ."}'),
  ('77b19e55-26','{"options": ["Dr. Elizabeth Valconcha", "Dr. Maria Isabelle Valconcha", "Dr. Charlie L. Ho", "Dr. Charlie R . Ho"], "correct": 2, "explanation": "VERIFY (time-sensitive official): the president of the accredited optometry organization (OAP) changes by term and cannot be reliably fixed. Confirm the current OAP president for the exam year."}'),
  ('16d9b764-1p','{"options": ["Internship Plan", "Corporation", "Employment", "Partnership"], "correct": 1, "explanation": "A ''turnkey'' practice is a ready-to-operate setup that the buyer simply takes over. VERIFY: among these options the best fit is debatable; confirm whether the key maps ''turnkey'' to the corporate/ready-made entry mode or another practice type."}'),
  ('8ef17454-50','{"options": ["Contractual", "Consent", "Consensual", "Fiduciary"], "correct": 2, "explanation": "A relationship built on the mutual consent (offer and acceptance) of both parties is consensual. VERIFY: it is also broadly termed contractual, and it carries fiduciary duties; the definition given (mutual consent to render/accept) specifically describes the consensual character. Mutual agreement to serve/accept = consensual."}'),
  ('16200fc5-2s','{"options": ["Treatment of occupational disease", "Diagnosis of visual deficiency", "Visual examination", "Advice on wearing eye protection"], "correct": 0, "explanation": "Optometrists diagnose visual deficiency, perform visual examinations, and advise on protective eyewear, but TREATING occupational disease is a physician''s role, not the optometrist''s, so it is the EXCEPT. Optometrist screens/advises; the doctor treats disease."}'),
  ('87a647a2-1l','{"options": ["Moderate risk", "Caution", "Danger", "Safety"], "correct": 1, "explanation": "Yellow signals CAUTION (watch for hazards). Red is danger, and green means safety. Yellow = caution."}'),
  ('e0d0d61f-2j','{"options": ["ANOVA", "percentage distribution", "frequency distribution", "mean"], "correct": 0, "explanation": "ANOVA (analysis of variance) is an INFERENTIAL statistic (it tests hypotheses about differences), not a descriptive one. Frequency distribution, percentage distribution, and the mean simply describe data. ANOVA = inferential, not descriptive."}'),
  ('c3420e13-26','{"options": ["Medical Technologist", "Civil Engineer", "Pharmacist", "Pest control worker"], "correct": 1, "explanation": "Medical technologists, pharmacists, and pest-control workers handle chemicals/reagents/pesticides needing eye protection from chemical splash. A civil engineer faces mainly physical (construction) hazards, so is the EXCEPT for CHEMICAL exposure. Civil engineer = physical hazards, not chemical."}'),
  ('6d168176-41','{"options": ["Sole proprietorship", "Corporation", "Partnership", "Group practice"], "correct": 2, "explanation": "In a partnership, partners share joint (and often unlimited) liability, so one partner''s financial misstep can bind and endanger all of them. A corporation limits shareholder liability, and a sole proprietor bears only their own risk. Shared/joint liability = partnership."}'),
  ('f8a67f29-1n','{"options": ["under Section 32 of RA 8050", "for insubordination", "for unprofessional conduct", "for unethical conduct"], "correct": 3, "explanation": "The optometric oath is an ethical pledge, so breaking it is unethical conduct. VERIFY: PH law also lists ''unprofessional conduct'' as a ground for disciplinary action, so the key can be debatable; the oath is specifically an ethical undertaking. Violating the oath = unethical conduct."}'),
  ('2985cf12-1m','{"options": ["does not guarantee the results of professional service", "any advertising or conduct tending to deceive or mislead the public", "the employment of lay persons to perform visual examination", "displaying certificates, diplomas or similar documents unless the same have been earned by the optometrist"], "correct": 0, "explanation": "Deceptive advertising, employing unlicensed lay persons to examine, and displaying unearned credentials are all malpractices. NOT guaranteeing results is actually PROPER (an optometrist should not promise outcomes), so it is the EXCEPT. Not guaranteeing results is ethical, not malpractice."}'),
  ('73d91cad-1z','{"options": ["When a patient calls and makes an appointment for consultation", "The patient has the right to demand that the optometrist attends to him at the appointed time", "When a patient makes a visit at the optometrist''s place of practice", "When a patient chooses another optometrist to manage her visual condition"], "correct": 3, "explanation": "The relationship ends when the patient transfers care by choosing another optometrist. The other options (making an appointment, visiting, demanding attendance) all establish or continue the relationship. Patient leaves for another provider = relationship terminated."}'),
  ('9c4cdb68-6n','{"options": ["Duties of Optometrists to other Optometrists", "Duties of Optometrist to Members of other Professions", "Relations between Optometrist and his Patient", "Duties of Optometrists to the General Public"], "correct": 2, "explanation": "Charging for materials at laboratory cost within the fee arrangement concerns the Relations between the optometrist and his patient (fees/materials). VERIFY: fee-and-materials ethics can also be framed as a public duty, so the section is arguable. Materials/fees toward the patient = optometrist-patient relations."}'),
  ('8c717f08-2q','{"options": ["Flame", "Chemical burns", "Acid burns", "Alkali burns"], "correct": 3, "explanation": "Alkali burns cause LIQUEFACTIVE necrosis, dissolving cell membranes and penetrating deep into the cornea and anterior chamber, so they are more damaging than acids. Acids cause coagulative necrosis that forms a barrier limiting penetration. Alkali penetrates deep = worse burn."}'),
  ('047c8ebb-2x','{"options": ["Duction and version", "Near visual acuity", "Alternate cover", "Distance visual acuity"], "correct": 2, "explanation": "The alternate cover test objectively detects strabismus across the whole 6-month to 6-year range without needing the child to read a chart. VERIFY: duction/version testing is also usable in young children, so the choice is debatable; acuity charts require verbal cooperation older children have. Objective, no-chart alignment test = alternate cover."}'),
  ('54c7205d-2g','{"options": ["Mechanical", "Radiation", "Chemical", "Biological"], "correct": 0, "explanation": "Flying chips and fragments striking the eye are a MECHANICAL (impact) hazard. Radiation, chemical, and biological are different hazard classes. Flying particles = mechanical hazard."}'),
  ('c3cc535b-5h','{"options": ["Department of Justice", "DOLE", "DFA", "Public Attorney''s Office"], "correct": 1, "explanation": "The Department of Labor and Employment (DOLE) governs workers'' rights, working conditions, benefits, and labor relations. The DOJ handles justice, the DFA foreign affairs, and the PAO free legal aid. Labor and employment = DOLE."}'),
  ('d03f7394-26','{"options": ["Rights of Patients", "Rights inherent in the privilege to Practice Optometry", "Rights Enjoyed by Every Citizen", "Rights Incidental in the Privilege to Practice Optometry"], "correct": 0, "explanation": "Informed consent before a procedure is part of the Rights of Patients (to be informed and to consent). Informed consent = a patient right."}'),
  ('b2e85ab7-1y','{"options": ["A", "C", "D", "B"], "correct": 0, "explanation": "Vitamin A deficiency causes xerophthalmia (dry eye, Bitot''s spots, night blindness, keratomalacia), a leading cause of childhood blindness. Xerophthalmia = vitamin A deficiency."}'),
  ('027bba95-4f','{"options": ["Physical", "Chemical", "Biological", "Environmental"], "correct": 0, "explanation": "Noise and vibration are PHYSICAL agents, so the hazard is physical. Physical agents (noise, vibration, heat, radiation) = physical hazard."}'),
  ('a87169e7-1d','{"options": ["Eye and vision protection", "Designing occupational eye and vision health care programs", "Provide vision screening", "Treatment of ocular diseases"], "correct": 3, "explanation": "Occupational optometry covers protection, program design, and screening, but TREATING ocular diseases is a medical (ophthalmologic) function outside the optometrist''s scope. Optometry screens/protects; it does not treat ocular disease."}'),
  ('823d0625-1i','{"options": ["Optical laboratory", "Staff lounge", "Contact lens room", "Reception area"], "correct": 3, "explanation": "Patients wait in the reception area. The optical lab processes lenses, the staff lounge is for staff, and the contact lens room is for CL fitting. Waiting area = reception."}'),
  ('0069f302-3j','{"options": ["Actual", "Exemplary", "Nominal", "Moral"], "correct": 1, "explanation": "Exemplary (punitive) damages are imposed by way of example or correction for the public good. Actual damages compensate real loss, nominal damages vindicate a right, and moral damages address mental suffering. By way of example = exemplary damages."}'),
  ('6e83ab10-2j','{"options": ["Optometrist", "Practitioner", "Doctor of Optometry", "Specialist"], "correct": 2, "explanation": "A graduate holding the degree is a Doctor of Optometry (OD). VERIFY: ''Optometrist'' usually implies a licensed practitioner (post board exam), so if the item means a licensed professional the answer shifts; strictly the degree earned is Doctor of Optometry. Degree earned = Doctor of Optometry."}'),
  ('4397b6b9-2r','{"options": ["Right enjoyed by every citizen", "Right Incidental in the Privilege to Practice Optometry", "Right Inherent in the Privilege to Practice Optometry", "Right of patients"], "correct": 0, "explanation": "Free access to courts and adequate legal assistance is a constitutional Right enjoyed by every citizen (not tied to any profession). Access to courts = a universal citizen''s right."}'),
  ('b01b4463-2c','{"options": ["Bigger investment is needed", "SEC registration", "Division of Labor", "Incorporation is needed to organize"], "correct": 2, "explanation": "In a partnership the owner-partners themselves directly divide the labor and management, whereas a corporation delegates management to a board and officers (owners are shareholders). VERIFY: this item is loosely worded (SEC registration is shared; incorporation is corporate-only), so the intended contrast is debatable. Partners directly divide the work = partnership feature."}'),
  ('a3474d33-1t','{"options": ["Group practice", "Sole proprietorship", "Corporation", "Partnership"], "correct": 2, "explanation": "A corporation is governed by a board of directors elected by shareholders. Sole proprietors and partners manage directly. Board of directors = corporation."}'),
  ('ff186144-1v','{"options": ["Environmental emission monitoring", "Production should be done in an open space", "Emission of dust into the atmosphere", "Wearing of goggles and facemasks"], "correct": 3, "explanation": "Personal protective equipment (goggles and facemasks) directly shields workers from inhaling/contacting coal dust. Emission monitoring and open-space production do not protect the individual worker, and emitting dust is the hazard itself. Protect the worker = PPE (goggles, facemasks)."}'),
  ('c57e1c37-2k','{"options": ["Cyclopentolate HCL", "Atropine", "Tropicamide", "Phenylephrine"], "correct": 0, "explanation": "Cyclopentolate is the cycloplegic agent optometrists use for cycloplegic refraction under the DPA provisions. VERIFY: exact allowed agents/concentrations follow the RA 8050 implementing rules; tropicamide is a weak cycloplegic, atropine is stronger but restricted, and phenylephrine is a mydriatic (not cycloplegic). Cycloplegic refraction = cyclopentolate."}'),
  ('32d8398f-1p','{"options": ["Occupational Safety and Health", "American National Standards Incorporated", "Standard New Zealand", "Standard Australia"], "correct": 1, "explanation": "The American National Standards Institute (ANSI) sets widely used international safety-eyewear standards (for example Z87). VERIFY: ANSI is US-based (adopted internationally), and other bodies (AS/NZS) also set standards, so ''international certifying body'' is loosely used. Safety-eyewear standards = ANSI."}'),
  ('e3a3b26d-1z','{"options": ["Net worth", "Fixed expense", "Current asset", "Fixed asset"], "correct": 3, "explanation": "A fixed asset (equipment, building) is a long-term asset used for more than one year. Current assets are short-term (under a year), and net worth/fixed expense are not asset-lifetime categories. Long-lived asset = fixed asset."}'),
  ('18324d34-2t','{"options": ["Pediatric optometry", "Industrial vision", "Vision training", "Sports vision"], "correct": 1, "explanation": "Industrial (occupational) vision addresses the visual demands and problems of workers/occupational groups. Occupational groups = industrial vision."}'),
  ('ddc51fd9-1w','{"options": ["industrial safety", "occupational hygiene", "occupational health hazards", "occupational risk"], "correct": 2, "explanation": "Occupational health hazards are the workplace conditions that cause the compensable occupational diseases/illnesses. VERIFY: ''occupational risk'' overlaps this meaning, so the item is loose. Conditions causing work-related compensable illness = occupational health hazards."}'),
  ('19f975ce-2w','{"options": ["Fiduciary", "Consent", "Consensual", "Contractual"], "correct": 2, "explanation": "As with the earlier item, a relationship formed by the mutual consent of both parties is consensual. Mutual consent = consensual relationship."}'),
  ('7bba6422-76','{"options": ["Cohort", "Cross sectional", "Clinical trial", "Case control"], "correct": 3, "explanation": "Starting from those WITH the disease (cases) and matched controls, then looking BACK to compare exposure (UV), is a case-control study. A cohort follows exposure forward, a cross-sectional is a snapshot, and a clinical trial assigns an intervention. Cases vs matched controls, exposure compared = case-control."}'),
  ('63962084-g','{"options": ["Philippine Qualifications Framework", "Regulating the Practice of Optometry", "PRC Modernization Act", "Continuing Professional Development"], "correct": 0, "explanation": "RA 10968 is the Philippine Qualifications Framework (PQF) Act (2018). (RA 8050 regulates optometry, RA 8981 is the PRC Modernization Act, and RA 10912 is the CPD Act.) RA 10968 = PQF Act."}'),
  ('b78956ce-1r','{"options": ["potential losses", "availability of resources", "ability to expand", "easier to setup and register"], "correct": 3, "explanation": "Being easier to set up and register is an ADVANTAGE of a sole proprietorship, so it is the EXCEPT. Its disadvantages include bearing potential losses alone, limited resources, and limited ability to expand. Easy setup = advantage, not disadvantage."}'),
  ('bdb94da3-3i','{"options": ["Chair cost", "Balance Sheet", "Income Statement", "Cash Flow Statement"], "correct": 2, "explanation": "The income statement (profit-and-loss statement) summarizes revenues minus expenses to show profit or loss. The balance sheet shows assets/liabilities at a point in time, and the cash flow statement tracks cash movement. Revenues - expenses = profit/loss = income statement."}'),
  ('9375e616-2h','{"options": ["Professional Regulation Commission", "Accredited professional organization pursuant to Sec. 37 of RA 8050", "Board of Optometry", "President of the Philippines"], "correct": 1, "explanation": "Under Sec. 37 of RA 8050, the accredited professional organization adopts the code/standards of professional conduct for its members. VERIFY: the Board of Optometry (with PRC) also promulgates the Code of Ethics, so the two can be conflated; the item cites Sec. 37 pointing to the accredited organization. Professional conduct standard = the accredited professional organization (Sec. 37)."}'),
  ('fd34e038-5b','{"options": ["10,000", "30,000", "20,000", "15,000"], "correct": 0, "explanation": "RA 8050 sets the fine at not less than 10,000 nor more than 40,000 pesos (with possible imprisonment). VERIFY: confirm the exact figure against the current statute/amendments. Lower bound of the RA 8050 fine = 10,000 pesos."}'),
  ('3f7f58cb-2s','{"options": ["BIR only", "Securities and Exchange Commission", "DTI only", "BIR and DTI"], "correct": 3, "explanation": "A sole proprietorship registers its business NAME with the DTI and registers for TAX with the BIR (SEC is only for partnerships/corporations). Sole proprietor = DTI (name) + BIR (tax)."}'),
  ('0e365c65-2u','{"options": ["Tertiary", "General", "Primary", "Secondary"], "correct": 2, "explanation": "Primary care/prevention aims to prevent the ONSET of a disorder. Secondary prevention detects early disease, and tertiary limits disability from established disease. Prevent onset = primary."}'),
  ('f291322b-2s','{"options": ["Department of Health", "Philippine Health Insurance Corporation", "Social security system", "Home Development Mutual Fund"], "correct": 0, "explanation": "Employers register employees with PhilHealth, SSS, and Pag-IBIG (HDMF). The Department of Health is not an employee-registration agency, so it is the EXCEPT. Employee registration = PhilHealth, SSS, Pag-IBIG (not DOH)."}'),
  ('646de5f1-1z','{"options": ["Ship captain", "Beer bottler", "Sugar planter", "Chemical engineer"], "correct": 2, "explanation": "A sugar planter''s agricultural work has the lowest precision/visual demand of the group, needing the least visual task analysis. VERIFY: visual-demand rankings are judgment calls; a ship captain (navigation), beer bottler (inspection), and chemical engineer (precision/color) have clearly higher visual demands. Low-precision manual labor = least visual task analysis."}'),
  ('c55012db-3k','{"options": ["Optometry Code of Ethics", "No violation", "RA 8981", "RA 8050"], "correct": 3, "explanation": "Conviction of a crime involving moral turpitude (like estafa) is a ground for revocation of the license under the optometry law, RA 8050. VERIFY: RA 8981 (PRC law) also addresses disciplinary grounds, so the specific citation can be argued; the optometry-specific statute is RA 8050. Moral-turpitude conviction = RA 8050 revocation ground."}'),
  ('d35e9ed4-5g','{"options": ["Food and drug certificate", "Professional license", "School diploma", "Certificate of registration"], "correct": 3, "explanation": "The Certificate of Registration is signed by the PRC Commissioner and the Board members, certifying the registrant is qualified to practice. (The professional ID/license card is a separate item.) Board+PRC-signed proof of qualification = certificate of registration."}'),
  ('6036980a-41','{"options": ["Licensure Law", "Criminal Law", "Public Opinion", "Civil Law"], "correct": 3, "explanation": "The duty to indemnify another for damage willfully or negligently caused is a Civil Law principle (quasi-delict, Article 20/2176 of the Civil Code). Criminal law punishes offenses against the state. Indemnify for damage caused = civil law."}'),
  ('af684541-2f','{"options": ["Arthritis", "Rheumatism", "Osteoarthritis", "Carpal tunnel syndrome"], "correct": 3, "explanation": "Poor keyboard/wrist positioning compresses the median nerve, causing carpal tunnel syndrome (numbness/tingling in the fingers). Improper computer posture + finger symptoms = carpal tunnel syndrome."}'),
  ('d273e34a-62','{"options": ["Optometrists to other Optometrists", "Optometrists to members of other Professions", "Optometrists to the General Public", "Optometrist to Patients"], "correct": 0, "explanation": "Returning the referred patient to the original optometrist is a courtesy among colleagues, so it falls under Duties of Optometrists to other Optometrists. Consultant returns patient to referring OD = duty to other optometrists."}'),
  ('44858d5f-34','{"options": ["Professional Regulation Commission", "Department of Trade and Industry", "Department of Education", "Commission on Higher Education"], "correct": 1, "explanation": "The PQF is coordinated by DepEd, CHED, TESDA, PRC, and DOLE. The Department of Trade and Industry is NOT part of that framework, so it is the EXCEPT. PQF agencies = DepEd, CHED, TESDA, PRC, DOLE (not DTI)."}'),
  ('68e67e70-1n','{"options": ["Office of the President", "Senate of the Philippines", "Commission on Higher Education", "PRC Board of Optometry"], "correct": 3, "explanation": "The PRC Board of Optometry exercises delegated (quasi-legislative) power to promulgate rules and regulations, delegated to it by Congress. VERIFY: CHED also exercises delegated rule-making, so more than one option fits; among these the Board of Optometry is the profession-specific rule-maker. The Senate holds original (not delegated) legislative power. Rule-making authority = delegated legislative power (Board of Optometry)."}'),
  ('598f12bc-1s','{"options": ["Chair, PRC", "Chair, Board of Optometry", "Chair, PAPRB", "President of the Philippines"], "correct": 3, "explanation": "Board members are appointed by, and may be suspended/removed for cause by, the President of the Philippines. Appoint and remove Board members = the President."}'),
  ('a2f43764-5q','{"options": ["Duties of Optometrist to members of other Professions", "Duties of Optometrist to other Optometrist", "Duties of Optometrist to patients", "Duties of Optometrist to General Public"], "correct": 0, "explanation": "Cooperating with another professional whose services the patient''s condition demands falls under Duties to members of other Professions. VERIFY: if ''another'' means another optometrist, it would be duties to other optometrists; the phrasing points to interprofessional cooperation. Cooperate with other professionals for the patient = duty to members of other professions."}'),
  ('eb576ae1-25','{"options": ["Phoropter", "Slit-lamp biomicroscope", "Goldmann tonometer", "Contrast sensitivity chart"], "correct": 1, "explanation": "The slit-lamp biomicroscope is fundamentally a light-based instrument (its focused illumination system is essential to its function). VERIFY: several instruments need ambient light, so ''dependent on light'' is loosely worded; the slit lamp is defined by its own light source. Illumination-based instrument = slit lamp."}'),
  ('bbfbe1e0-34','{"options": ["statement of the problem", "scope and limitations", "conclusion", "purpose of the study"], "correct": 0, "explanation": "The statement of the problem lays out the research questions to be answered and shapes the methodology. The scope/limitations bound the study, and the conclusion comes at the end. Research questions that drive method = statement of the problem."}'),
  ('4b181f39-27','{"options": ["traumatic optic neuropathy", "diabetic retinopathy", "vitreous hemorrhage", "hyphema"], "correct": 1, "explanation": "Traumatic optic neuropathy, vitreous hemorrhage, and hyphema are internal eye INJURIES (trauma). Diabetic retinopathy is a systemic DISEASE, not a work injury, so it is the EXCEPT. Diabetic retinopathy is a disease, not an occupational injury."}'),
  ('c0c4d8a4-70','{"options": ["School of Optometry", "Accredited Organization", "Commission on Higher Education", "Technical Skills and Development Authority"], "correct": 2, "explanation": "Academic standards for higher education (including optometry programs) are set by the Commission on Higher Education (CHED). Academic standards = CHED."}'),
  ('902dc691-14','{"options": ["Money", "Land", "Labor", "Capital"], "correct": 0, "explanation": "The economic resources (factors of production) are land, labor, capital, and entrepreneurship. MONEY is a medium of exchange, not a factor of production, so it is not a resource. Money is a medium, not a factor of production."}'),
  ('dc72236c-1x','{"options": ["flash burn", "snow blindness", "photokeratitis", "uveitis"], "correct": 3, "explanation": "UVB/UVC exposure causes photokeratitis (also called flash burn / snow blindness / welder''s keratitis). Uveitis (intraocular inflammation) is not a direct UVB/UVC effect, so it is the EXCEPT. Surface UV burn = photokeratitis; uveitis is unrelated."}'),
  ('fb8296ce-4y','{"options": ["Optometrist to other Optometrist", "Optometrist to members of other Profession", "Optometrist to Patients", "Optometrist to General Public"], "correct": 3, "explanation": "Assisting the courts/justice system serves society, so it is a Duty to the General Public. VERIFY: cooperating with judicial (legal) authorities could be read as a duty to members of other professions; serving the administration of justice is a societal/public duty. Serve the justice system for society = duty to the general public."}'),
  ('0752596f-2u','{"options": ["register your practice at the Department of Health", "register your clinic/optical in the Bureau of Internal Revenue", "register the clinic/optical name at the Department of Trade and Industry", "secure a barangay clearance certificate and mayor''s permit"], "correct": 0, "explanation": "A sole proprietorship registers with the BIR (tax), DTI (business name), and the LGU (barangay clearance, mayor''s permit). Registering at the DOH is not part of this process, so it is the EXCEPT. Sole-proprietor steps = BIR, DTI, LGU permits (not DOH)."}'),
  ('528a2512-1w','{"options": ["Executive committee", "Board of Directors", "Managing officer responsible for its commission", "President and CEO of the corporation"], "correct": 2, "explanation": "When a corporation violates the law, liability attaches to the managing officer/person actually responsible for committing the violation. Corporate violation = the responsible managing officer is liable."}'),
  ('11b980dd-7k','{"options": ["Implied contract", "Fiduciary", "Contractual", "Expressed contract"], "correct": 0, "explanation": "A contract inferred from conduct/circumstances rather than stated in words is an implied contract. An expressed contract is stated explicitly (spoken or written). Inferred from conduct = implied contract."}'),
  ('6c5cda4f-2n','{"options": ["quasi-legislative", "quasi-judicial", "determinative", "executive"], "correct": 3, "explanation": "Administrative bodies characteristically wield quasi-legislative (rule-making), quasi-judicial (adjudicatory), and determinative (investigatory/licensing) powers. ''Executive'' as a standalone branch power is not one of these delegated administrative powers, so it is the EXCEPT. VERIFY: agencies do carry out executive/implementing functions, so this classification is debatable. Administrative powers = quasi-legislative, quasi-judicial, determinative."}'),
  ('e3d7949d-1o','{"options": ["Level of the computer screen", "UV from the computer monitor", "Computer monitor glare", "Height of the computer chair"], "correct": 2, "explanation": "Screen GLARE is a direct visual cause of computer-related eyestrain (asthenopia). VERIFY: screen level/ergonomics also contribute, so more than one factor is valid; glare is the classic visual trigger. Reflected/screen glare = eyestrain."}'),
  ('f3ea18d1-32','{"options": ["Yellow", "Green", "Gray", "Amber"], "correct": 2, "explanation": "A gray (neutral) tint dims light evenly across the spectrum, cutting brightness without distorting color perception. Yellow/amber enhance contrast but alter color. Neutral dimming, true color = gray tint."}'),
  ('22503534-3r','{"options": ["VSI (Vision Science Institute)", "OEL (Optometry Educators League)", "PAO (Philippine Academy of Optometry)", "IPAO (Integrated Philippine Association of Optometrists)"], "correct": 3, "explanation": "The accredited integrated national professional organization for optometrists under RA 8050 is the IPAO (Integrated Philippine Association of Optometrists). Accredited integrated organization = IPAO."}'),
  ('b714367e-27','{"options": ["electrician", "professional athlete", "mechanic", "sales clerk"], "correct": 0, "explanation": "An electrician must reliably distinguish color-coded wires, so color discrimination is safety-critical for them. Colored wire codes = electrician needs good color vision."}'),
  ('fb067ecb-1e','{"options": ["Placement of the registered name/title in a public directory that is substantially dissimilar in size, shape or color to that used for other practitioners", "To include on the signboard illustrations of an eye, eyeglasses, or other signs that tend to remove the aura of professionalism", "Displaying the license, diploma or certificate in a manner visible from the street", "Displaying his name and title in letters not larger than 6 inches in height at street level"], "correct": 3, "explanation": "Modest signage, name and title in letters not larger than 6 inches at street level, is the ethical option. Oversized/dissimilar directory listings, gimmicky eye illustrations, and street-visible certificates are all considered unprofessional. Restrained, standard-size signage = ethical."}'),
  ('8b34543b-6h','{"options": ["Epidemic", "Pandemic", "Sporadic", "Endemic"], "correct": 3, "explanation": "A condition constantly present within and confined to a particular population/region (here, Region III) is endemic. An epidemic is a sudden excess, a pandemic spans continents, and sporadic cases are scattered/irregular. Confined and constant in one region = endemic."}'),
  ('947c9bc1-5i','{"options": ["Duties of Optometrist to members of other Professions", "Duties of Optometrist to patients", "Duties of Optometrist to General Public", "Duties of Optometrist to other Optometrist"], "correct": 3, "explanation": "Returning the referred patient to the original optometrist is professional courtesy, a Duty to other Optometrists. Consultant returns the patient = duty to other optometrists."}'),
  ('b4fb2516-1v','{"options": ["attract workers'' attention", "color is not necessarily bright", "easily recognized by workers", "act as stimuli to call for specific associations"], "correct": 1, "explanation": "Safety colors must be BRIGHT and conspicuous, so ''color is not necessarily bright'' contradicts the requirement and is the EXCEPT. They should attract attention, be easily recognized, and trigger specific associations. Safety colors must be bright/attention-getting."}'),
  ('06c37efc-5m','{"options": ["RA 7722", "PD 8050", "RA 223", "RA 8981"], "correct": 3, "explanation": "RA 8981 (the PRC Modernization Act) requires professionals to indicate their license number, date of issuance, and validity on documents they sign. (RA 7722 created CHED.) PRC modernization/license-detail requirement = RA 8981."}'),
  ('7fe9e0a1-1s','{"options": ["Examination area", "Optical laboratory", "Contact lens room", "Reception area"], "correct": 1, "explanation": "Spectacles are edged and assembled in the optical laboratory. Lens processing = optical laboratory."}'),
  ('3542f178-43','{"options": ["Subpoena", "Subpoena duces tecum", "Prima facie", "Subpoena ad testificandum"], "correct": 1, "explanation": "A subpoena duces tecum compels a person to appear AND bring/produce specified documents. A subpoena ad testificandum only compels testimony; prima facie means ''on its face'' (sufficient evidence). Appear + produce documents = subpoena duces tecum."}'),
  ('fec4d9d9-5r','{"options": ["Duties of Optometrist to members of other Professions", "Duties of Optometrist to other Optometrist", "Duties of Optometrist to patients", "Duties of Optometrist to General Public"], "correct": 3, "explanation": "Participating in public-health measures to safeguard the welfare of SOCIETY is a Duty to the General Public. VERIFY: because it involves ''other professional groups'', it could be read as a duty to members of other professions; the stated goal (welfare of society) points to the general public. Public health for society = duty to the general public."}'),
  ('a07c5b66-1w','{"options": ["Senior practitioner", "Owner of an Optometry school", "Member of the academe", "Board of Optometry"], "correct": 1, "explanation": "A technical panel for education typically includes senior practitioners, academics, and Board representatives, but a school OWNER is excluded to avoid conflict of interest. VERIFY: exact panel composition follows CHED/PRC rules and may differ, so confirm the intended answer. School owner excluded (conflict of interest)."}'),
  ('1b9fcbe8-1f','{"options": ["The Board of Optometry", "The Professional Regulation Commission", "The Commission on Higher Education", "The Integrated Philippine Association of Optometrists"], "correct": 3, "explanation": "The accredited professional organization, the Integrated Philippine Association of Optometrists, is the source that adopts the Code of Ethics for the profession (consistent with the Sec. 37 professional-conduct provision). VERIFY: the Board of Optometry (with PRC) also promulgates/approves the Code, so the two can be conflated. Profession''s Code of Ethics = the accredited organization (IPAO)."}'),
  ('53fb6749-25','{"options": ["Malpractice", "Criminal liability", "Incompetence", "Malicious negligence"], "correct": 3, "explanation": "A wistful (deliberate-in-attitude) desire to harm through carelessness/indifference is malicious negligence (negligence coupled with ill intent/reckless disregard). Careless harm with ill intent = malicious negligence."}'),
  ('f5960b37-2y','{"options": ["20/20 minimum standard", "Vision standards for workers", "Safety standards for protective eye wear", "Prescription spectacles for special tasks"], "correct": 1, "explanation": "Vision standards for workers set the visual requirements that let workers perform their tasks safely and efficiently. VERIFY: the phrasing could also fit general occupational standards; ''vision standards for workers'' best matches task-based visual guidelines. Task-based visual requirements = vision standards for workers."}'),
  ('d44e3b18-4c','{"options": ["RA 9711", "RA 7722", "RA 8050", "RA 8981"], "correct": 3, "explanation": "The PRC''s governing (modernization) law is RA 8981. (RA 9711 is the FDA Act, RA 7722 created CHED, and RA 8050 is the optometry law.) PRC = RA 8981."}'),
  ('6594eea1-1g','{"options": ["Biological", "Physical", "Chemical", "Environmental"], "correct": 1, "explanation": "Noise is a PHYSICAL agent, so excessive noise is a physical health hazard. Noise = physical hazard."}'),
  ('5ee08d1e-1a','{"options": ["patterns of organization in healthcare", "the distribution and the determinants of the frequency of disease in humans", "the frequency of causes of death in humans", "the etiology of disease in humans"], "correct": 1, "explanation": "Epidemiology is the study of the distribution and determinants of disease frequency in human populations (and the application to control health problems). Distribution + determinants of disease frequency = epidemiology."}'),
  ('1fafc224-3r','{"options": ["date of license''s expiration", "place of issuance", "date of the document", "professional license number"], "correct": 1, "explanation": "Under the PRC rule, documents must show the professional license number, date of issuance, and validity/expiration; the ''place of issuance'' is not a required element, so it is the EXCEPT. VERIFY: exact required fields follow the PRC regulation. Required = license number, issuance date, expiration (not place of issuance)."}'),
  ('1edd3d51-1b','{"options": ["Staff lounge", "Reception area", "Contact lens room", "Optical Laboratory"], "correct": 3, "explanation": "The optical laboratory (lens edging/surfacing) uses water and generates waste, so it needs a good water supply and drainage. VERIFY: a contact-lens room also needs a handwashing/water supply, so it is a defensible answer; the lab''s processing/waste needs are greater. Water + waste drainage for processing = optical laboratory."}'),
  ('a8a97e01-5m','{"options": ["Contrast sensitivity chart", "Phoropter", "Goldmann tonometer", "Slit-lamp biomicroscope"], "correct": 0, "explanation": "The phoropter, tonometer, and slit lamp are core/mandatory for a comprehensive exam; a contrast sensitivity chart is a supplementary (not mandatory) instrument, so it is the EXCEPT. VERIFY: mandatory-equipment lists follow the specific regulation/standard. Contrast chart = supplementary, not mandatory."}'),
  ('e391fe67-4f','{"options": ["Face shield", "Sunglasses", "Sun visor", "Spectacles"], "correct": 3, "explanation": "Inspection work needing keen eyesight calls for corrective spectacles so the inspector sees the defects clearly. Sunglasses/visor reduce light (unhelpful indoors), and a face shield is for impact/splash. Sharp inspection vision = corrective spectacles."}'),
  ('b02eba41-28','{"options": ["Cataract", "Glaucoma", "Diabetic retinopathy", "Macular degeneration"], "correct": 0, "explanation": "Cataract is the leading cause of blindness worldwide (and it is reversible with surgery). Glaucoma is the leading cause of IRREVERSIBLE blindness, but overall the top cause is cataract. #1 blindness worldwide = cataract."}'),
  ('17ba7dc6-1h','{"options": ["reputation", "service to humanity", "financial gain", "status symbol"], "correct": 1, "explanation": "The primary professional concern is service to humanity (patient welfare above self-interest). Profession first serves people = service to humanity."}'),
  ('7a3a73be-27','{"options": ["Lack of physical activity", "Vitamin A deficiency", "Exposure to gadgets", "Homework"], "correct": 2, "explanation": "Heavy near work and screen/gadget exposure (with less outdoor time) is linked to the modern rise in childhood myopia. VERIFY: myopia is multifactorial (genetics, reduced outdoor time), so ''gadgets'' is the emphasized modern factor rather than the sole cause. Screen/near-work exposure = modern juvenile refractive error."}'),
  ('6dd8ce29-1d','{"options": ["Spectacles", "Hard hat", "Face shields", "Goggles"], "correct": 2, "explanation": "Welding requires a welding face shield/helmet with a filtered lens to protect the face and eyes from intense light, UV/IR, and sparks. Welding = face shield/helmet."}'),
  ('e81de1dc-3x','{"options": ["5", "10", "15", "20"], "correct": 1, "explanation": "RA 8050 requires a Board member to have been in active practice for at least 10 years. VERIFY: confirm against the current statute for any amended figure. Board member practice requirement = 10 years."}'),
  ('d191702e-47','{"options": ["Occupational Safety", "Universal Health Coverage Program", "Global Safety in the Workplace", "Occupational Safety and Health Law"], "correct": 3, "explanation": "The Occupational Safety and Health Law (RA 11058 and its standards) mandates a safe and healthful workplace protecting workers from hazards. Workplace safety mandate = OSH Law."}'),
  ('b648949c-26','{"options": ["crown glass", "CR-39", "polycarbonate lens", "dark tinted lens"], "correct": 2, "explanation": "Polycarbonate is impact-resistant, the safest choice against flying metal fragments in fabrication work. High-impact protection = polycarbonate."}'),
  ('e3b877ae-2p','{"options": ["Partnership", "Group practice", "Corporation", "Sole proprietorship"], "correct": 0, "explanation": "Two (or more) individuals co-owning, managing, and operating a business form a partnership. Two co-owners/managers = partnership."}'),
  ('c42329f6-2k','{"options": ["Suspension or revocation of license", "Fine of 40,000", "Imprisonment of at least 2 years", "Fine of 10,000 to 20,000"], "correct": 0, "explanation": "Unprofessional/unethical conduct is an administrative offense punished by suspension or revocation of the certificate/license by the Board. Unprofessional conduct = suspension or revocation of license."}'),
  ('b8d54e60-2i','{"options": ["Balance Sheet", "Cash Flow Statement", "Chair cost", "Income Statement"], "correct": 3, "explanation": "The income statement reports revenues minus expenses over a period to show the profit (or loss). Period profit/loss = income statement."}'),
  ('742b3122-2y','{"options": ["Management", "Economics", "Marketing strategy", "Feasibility"], "correct": 3, "explanation": "A feasibility study assesses market demand and competition (current and potential) before starting/expanding a practice. VERIFY: market/competitive analysis is also part of marketing strategy, so the two overlap; the pre-launch competitive assessment is a feasibility study. Market/competition assessment = feasibility study."}'),
  ('2db5958e-18','{"options": ["Includes the entire complex structure of medical and surgical care", "Give treatment in very simple cases", "Maintaining wellness of patient", "Located in hospitals without large facilities"], "correct": 2, "explanation": "Primary care emphasizes first-contact, prevention, and maintaining the patient''s wellness/health. VERIFY: ''treatment in very simple cases'' is also a primary-care feature, so the item is loose; health maintenance/wellness best captures the primary-care aim. First-contact wellness/prevention = primary care."}'),
  ('ab9fdc35-2b','{"options": ["When screening for a driver''s or pilot''s license", "When the court appoints an optometrist to examine a respondent or witness to determine the person''s visual condition", "When an optometrist is asked casual questions by another person in a place where consultation is not usually held", "During a pre-employment eye examination"], "correct": 2, "explanation": "In third-party exams (licensing, court-ordered, pre-employment) no doctor-patient relationship forms because the examinee is not seeking care. In an informal (curbside) consult, if the optometrist gives specific professional advice that is relied upon, a relationship MAY be established. VERIFY: the curbside-consult exception is debatable and jurisdiction-dependent. Informal advice relied upon = a relationship may arise; third-party exams do not create one."}'),
  ('f0097ed9-1j','{"options": ["Use of eye lubricants", "Take stand-up breaks", "Take Lutein supplements", "Wash your face when feeling sleepy"], "correct": 3, "explanation": "Lubricating drops, regular breaks, and lutein support eye comfort/health at the computer. Washing your face when sleepy is not a recognized eye-care best practice for computer use, so it is the EXCEPT. The face-washing tip is the odd one out."}'),
  ('73c75885-2i','{"options": ["Proparacaine", "Phenylephrine", "Lidocaine", "Tropicamide"], "correct": 2, "explanation": "Proparacaine (topical anesthetic), phenylephrine (mydriatic), and tropicamide (mydriatic/cycloplegic) are topical ocular DPAs. Lidocaine is an injectable local anesthetic, not a topical ocular DPA, so it is the EXCEPT. Injectable lidocaine is not an ocular DPA."}'),
  ('579e99ca-20','{"options": ["The Optometry Law of 1917", "Republic Act 1998", "Republic Act 8050", "Presidential Decree 223"], "correct": 0, "explanation": "The Optometry Law of 1917 was the first regulatory law (written in Spanish, amended 1919). It was later amended by RA 1998 (1957), which was in turn replaced by RA 8050 (1995)."}'),
  ('0699687e-1z','{"options": ["Board of Optometry", "Junta Examinadora (Board of Examiners)", "Professional Regulation Commission", "Council of Deans"], "correct": 1, "explanation": "The 1917 law created the ''Junta Examinadora'' (Board of Examiners). Under PD 223 (amended by PD 657) the ''Board of Examiners in Optometry'' was later renamed the ''Board of Optometry.''"}'),
  ('b534b77b-2q','{"options": ["Dr. Federico Sarabia Sr.", "Dr. Justo Gonzalez", "Dr. Manuel Sabater", "Dr. Claro M. Cinco"], "correct": 2, "explanation": "PRC records show Registration Certificate No. 1 was issued March 11, 1918 to Dr. Manuel Sabater. Federico Sarabia Sr. is often cited as the reputed first and was the first Filipino to study optometry in the US (1905)."}'),
  ('97920f32-2d','{"options": ["Manila Central University", "De Ocampo Memorial College", "Philippine College of Optometry", "Centro Escolar University (1928)"], "correct": 3, "explanation": "Centro Escolar University established the first university-affiliated optometry college in 1928, with Dr. Roy A. Thorson as its first dean."}'),
  ('324e6d51-28','{"options": ["IFAPAO", "APCO", "WCO", "IOOL"], "correct": 0, "explanation": "The 1st APOC in Manila (July 1978) founded IFAPAO (International Federation of Asian and Pacific Associations of Optometrists), which later became APCO. Its first president was Dr. Claro M. Cinco."}'),
  ('9e8a4f43-29','{"options": ["Optometric Association of the Philippines", "Samahan Ng Optometrist Sa Pilipinas (SOP)", "Philippine Association of Optometrists", "Philippine College of Optometrists"], "correct": 1, "explanation": "In 1979, to meet the PRC''s requirement of one national association, the OAP, PODA, and PROA merged into the Samahan Ng Optometrist Sa Pilipinas (SOP)."}'),
  ('e6e25d65-1h','{"options": ["The Optometry Law of 1917", "The PRC Modernization Act", "The Revised Optometry Law of 1995", "The Philippine Optometry Act"], "correct": 2, "explanation": "RA 8050 is cited as the ''Revised Optometry Law of 1995.'' It repealed RA 1998 and was approved June 7, 1995 by President Fidel V. Ramos."}'),
  ('0fc00976-1y','{"options": ["The tertiary health care system", "The social security system", "The public education system", "The primary health care system"], "correct": 3, "explanation": "Section 2 (Declaration of State Policy) promotes optometric services as a regular component of the primary health care system."}'),
  ('bbc37c6c-2z','{"options": ["Phenylephrine 2.5%, Tropicamide 0.5%, Proparacaine 0.5%, Oxybuprocaine 0.4%, Fluorescein strips", "Phenylephrine 10%, Tropicamide 1%, Atropine 1%", "Pilocarpine 2%, Timolol 0.5%, Proparacaine 0.5%", "Cyclopentolate 1%, Phenylephrine 2.5%, Tetracaine 0.5%"], "correct": 0, "explanation": "RA 8050 as written lists five DPAs: Phenylephrine 2.5%, Tropicamide 0.5%, Proparacaine 0.5%, Oxybuprocaine HCl 0.4%, and Fluorescein strips. The 2008 IRR later added Cyclopentolate, making the current list six."}'),
  ('7d07bc34-2s','{"options": ["The PRC, on the Board''s recommendation", "The DOH, on the recommendation of the BFAD", "The CHED, on the Board''s recommendation", "The President, on the DOH''s recommendation"], "correct": 1, "explanation": "The DPA list is set by the Board of Optometry but is approved by the Secretary of the Department of Health (DOH) on the recommendation of the Bureau of Food and Drugs (BFAD)."}'),
  ('fef4dd7a-2k','{"options": ["30 years old and 5 years of practice", "40 years old and 10 years of practice", "35 years old and 5 years of practice", "35 years old and 10 years of practice"], "correct": 3, "explanation": "Sec. 8 requires a Board member to be at least 35 years old at appointment and in active practice for at least 10 years prior."}'),
  ('8731c545-2x','{"options": ["2 for quorum, 3 to decide", "3 for quorum, 3 to decide", "3 for quorum, 4 to decide", "4 for quorum, 3 to decide"], "correct": 1, "explanation": "Sec. 13 sets the quorum at three members, and Sec. 14 requires the vote of three members to render a decision in an administrative case."}'),
  ('eb16ac4b-1w','{"options": ["A general average of 70% with none below 50%", "A general average of 80% with none below 60%", "A general average of at least 75% with no grade below 50%", "A general average of 75% with no grade below 60%"], "correct": 2, "explanation": "Sec. 20 requires a general average of at least 75% in all subjects, with no rating below 50% in any single subject."}'),
  ('5ced0fa4-2z','{"options": ["Wait one full year", "Re-enroll in the entire O.D. program", "Obtain a special permit from the President", "Submit proof of a refresher course from an accredited institution"], "correct": 3, "explanation": "Sec. 22 requires an applicant who fails a third time to submit proof of a refresher course from a duly accredited institution before the next examination."}'),
  ('f6f538f6-2s','{"options": ["15 days", "10 days", "30 days", "60 days"], "correct": 0, "explanation": "Sec. 27 provides that the Board''s revocation or suspension becomes final unless appealed to the PRC within 15 days from receipt of the decision."}'),
  ('0904379f-25','{"options": ["Every year", "Every 3 years", "Every 2 years", "Every 5 years"], "correct": 1, "explanation": "Sec. 29 makes the professional license renewable every three (3) years. Note that Sec. 29''s continuing-education-for-renewal requirement was repealed by Sec. 20 of RA 8981 (PRC Modernization Act of 2000)."}'),
  ('2d178b73-1r','{"options": ["6 months to 6 years, or a fine up to P5,000", "2 to 10 years and a fine of P50,000", "1 to 8 years, or a fine of P10,000 to P40,000, or both", "6 years and 1 day to 12 years"], "correct": 2, "explanation": "Sec. 33 imposes imprisonment of not less than 1 year and not more than 8 years, or a fine of P10,000 to P40,000, or both, at the court''s discretion, plus applicable administrative penalties."}'),
  ('0eea4f53-1u','{"options": ["Displaying your certificate of registration in the clinic", "Referring a patient to an ophthalmologist", "Collecting a professional fee for an eye examination", "Advertising that you charge lower fees or sell cheaper frames than other optometrists"], "correct": 3, "explanation": "Sec. 32 prohibits advertising that one optometrist is better than others or that he collects lower fees or sells cheaper frames or lenses. Comparative and price advertising is a classic prohibited act."}'),
  ('e0d52f42-38','{"options": ["Visual acuity testing and visual screening", "Contact lens fitting", "Refraction and prescription of lenses", "Use of diagnostic pharmaceutical agents"], "correct": 0, "explanation": "The Sec. 5 exemption limits trained public health workers to visual acuity testing and visual screening only; anything beyond that would be unauthorized practice."}'),
  ('831277fe-1j','{"options": ["The President and the DOH Secretary", "The PRC Commissioner and all members of the Board of Optometry", "The Board chairperson alone", "The CHED chairperson and the Board secretary"], "correct": 1, "explanation": "Sec. 3(e) defines the certificate of registration as a document signed by the PRC Commissioner and by all members of the Board of Optometry, bearing the official seal."}'),
  ('5564d4c1-2g','{"options": ["Maximizing professional income", "Advancing his own reputation", "The visual welfare of the public", "Expanding his clientele"], "correct": 2, "explanation": "The first duty in the Code is to consider as his primary responsibility the visual welfare of the public."}'),
  ('bd557054-2i','{"options": ["Referring a patient for medical attention when indicated", "Keeping patient information confidential", "Continuing professional education", "Employing lay persons to perform the visual examination"], "correct": 3, "explanation": "Employing lay persons to perform the visual examination is expressly listed as unethical. Others include advertising superiority, house-to-house canvassing, and using ''Doctor'' without qualifying it with ''optometry.''"}'),
  ('1c60250c-28','{"options": ["Qualify it with the word ''optometry'' or ''optometrist''", "Use it without any qualification", "Use it only in academic settings", "Avoid it entirely"], "correct": 0, "explanation": "It is unethical to use the title ''Doctor'' or ''Dr.'' without qualifying it with ''optometry'' or ''optometrist,'' to avoid misleading the public."}'),
  ('6be22e7f-2t','{"options": ["Take over the patient permanently", "Return the patient to the original optometrist for subsequent care", "Refer the patient to a physician", "Report the original optometrist to the Board"], "correct": 1, "explanation": "A consultant must ensure the patient is returned to the original (attending) optometrist for any subsequent care the patient needs."}'),
  ('2e6dd14b-2l','{"options": ["Ignore it to preserve collegiality", "Confront the colleague publicly", "Expose the matter to the Board of Optometry", "Report only to the patient"], "correct": 2, "explanation": "The Code obliges the optometrist to expose corrupt or dishonest members to the Board of Optometry, helping safeguard the profession against the unfit."}'),
  ('91d63883-2z','{"options": ["PD 996", "PD 3573", "PD 649", "PD 223 (as amended by PD 657)"], "correct": 3, "explanation": "PD 223 (as amended by PD 657) created the Professional Regulation Commission and renamed the ''Board of Examiners in Optometry'' to the ''Board of Optometry.'' PD 223 was later repealed by RA 8981."}'),
  ('294d588e-1f','{"options": ["One Chairperson and two Commissioners appointed for a 7-year term with no reappointment", "A single Commissioner appointed for life", "Three co-equal Commissioners for 5-year terms", "The Secretary of Health"], "correct": 0, "explanation": "Under RA 8981, the PRC is headed by one full-time Chairperson and two full-time Commissioners, appointed by the President for a seven-year term without reappointment."}'),
  ('7e3b5207-26','{"options": ["Power of taxation", "Police power", "Power of eminent domain", "Power of judicial review"], "correct": 1, "explanation": "The right to regulate professions rests on the police power of the State (People v. Pomar, 46 Phil. 440; US v. Gomez Jesus, 31 Phil. 218), the power to enact reasonable laws for public welfare, health, morality, and safety."}'),
  ('fb92f605-1x','{"options": ["Revised Optometry Law", "Higher Education Act", "PRC Modernization Act of 2000", "Generics Act"], "correct": 2, "explanation": "RA 8981 is the PRC Modernization Act of 2000. Its Sec. 20 also repealed the continuing-education-for-renewal requirement that RA 8050''s Sec. 29 had imposed."}'),
  ('fa2257f9-2e','{"options": ["People v. Pomar", "Schloendorff v. Society of NY Hospital", "Safian v. Aetna", "Picart v. Smith (37 Phil. 809)"], "correct": 3, "explanation": "Picart v. Smith (37 Phil. 809) states the reasonable/prudent-man test: if a prudent person in the actor''s position would foresee harm, the law imposes a duty to take precaution, and failing to do so is negligence."}'),
  ('95db511f-20','{"options": ["Slander", "Perjury", "Malice", "Contempt"], "correct": 0, "explanation": "Under the Revised Penal Code, written defamation is libel (Art. 355) and oral defamation is slander. Elements of defamation: an imputation causing dishonor, malice, and bad faith."}'),
  ('dd1e936d-3b','{"options": ["Breach of contract", "Quasi-delict (tort)", "Criminal felony", "Administrative offense"], "correct": 1, "explanation": "Art. 2176 defines quasi-delict: whoever by act or omission causes damage to another through fault or negligence, with no pre-existing contractual relation, is obliged to pay for the damage done."}'),
  ('50ee7a74-5d','{"options": ["Picart v. Smith", "People v. Wendel", "Schloendorff v. Society of New York Hospital", "Salpa v. Leland Stanford"], "correct": 2, "explanation": "Justice Cardozo articulated the right to self-determination in Schloendorff v. Society of New York Hospital (1914), a foundation of the informed-consent doctrine."}'),
  ('dcbe92df-21','{"options": ["Routine refraction of a competent adult", "Fitting contact lenses on a willing patient", "Any procedure the optometrist judges beneficial", "A genuine emergency where the patient is unconscious, or a procedure the law compels for public health such as immunization"], "correct": 3, "explanation": "Consent is not needed in a true emergency (patient unconscious, no representative available) or where the law compels the procedure for public health, such as compulsory immunization under RA 3573 and PD 996."}'),
  ('62fd440f-3q','{"options": ["Spouse, then descendant of nearest degree, then ascendant of nearest degree, then brothers and sisters", "Employer, then the government", "Brothers and sisters first, then the spouse", "Nearest optometric society"], "correct": 0, "explanation": "Following the Civil Code support rules (Arts. 290-291), the claim runs in order against the spouse, then the descendant of nearest degree, then the ascendant of nearest degree, then brothers and sisters."}'),
  ('14d10fde-31','{"options": ["Expert testimony is always required", "The optometrist is liable only if he specifically stipulated a cure or result and failed, and ''pain and suffering'' is not an element", "Pain and suffering is the main element", "The optometrist is automatically liable for any failure to cure"], "correct": 1, "explanation": "Liability for breach of contract requires that the optometrist specifically promised a cure or result and failed. Expert testimony is not required and pain and suffering is not an element. The prudent rule is never to guarantee results."}'),
  ('084c4bc6-2e','{"options": ["urinary system", "skeletal system", "cardiovascular system", "nervous system"], "correct": 2, "explanation": "Most of the body''s cells are red blood cells (roughly 70-80% of all cells), so the cardiovascular/blood system holds the greatest number of cells."}'),
  ('5467603f-z','{"options": ["sartorius", "Mueller’s muscle", "sternocleidomastoid", "tensor tympani"], "correct": 1, "explanation": "Mueller''s (superior tarsal) muscle is a small smooth muscle of the upper lid, a reasonable pick for shortest smooth muscle here. Sartorius, SCM, and tensor tympani are skeletal, not smooth, so they are eliminated by the word ''smooth''."}'),
  ('79dab451-12','{"options": ["sartorius", "rectus femoris", "sternocleidomastoid", "latissimus dorsi"], "correct": 1, "explanation": "Among these options the powerful quadriceps component rectus femoris is the best fit for ''strongest''. Sartorius is the longest (eliminate), SCM is a neck flexor, latissimus dorsi is the widest (Q31). VERIFY: some keys cite the masseter or gluteus maximus as strongest overall, but neither is listed here."}'),
  ('0efb97d5-2g','{"options": ["retina", "iris", "choroids", "ciliary body"], "correct": 3, "explanation": "The lamina fusca, the pigmented inner scleral layer, extends over the ciliary body region as well, so the ciliary body is the best answer here. The retina and iris do not have a lamina fusca. VERIFY against your lecture notes, since some texts tie the lamina fusca to the suprachoroid (choroid) transition."}'),
  ('9cdd2fd1-1a','{"options": ["Schirmer’s test", "TBUT", "fluorescein dye test", "none of the above"], "correct": 1, "explanation": "Tear break-up time (TBUT) reflects mucin (and lipid) quality, so a rapid break-up points to mucin deficiency. Schirmer''s measures aqueous quantity, and the fluorescein dye test checks drainage."}'),
  ('945a871e-2q','{"options": ["Tarsal plate", "Nasolacrimal duct", "Plica semilunaris", "Lacrimal puncta"], "correct": 2, "explanation": "The plica semilunaris is the crescent (half-moon) conjunctival fold at the inner canthus, lateral to and partly under the caruncle; it is the human vestige of the third eyelid. The tarsal plate stiffens the lid, the nasolacrimal duct drains tears to the nose, and the puncta are the drainage openings on the lid margins."}'),
  ('7e269593-1u','{"options": ["Bi-temporal hemianopsia", "Bi-nasal hemianopsia", "Scotoma", "Hemianopsia"], "correct": 1, "explanation": "Loss of both NASAL half-fields is binasal hemianopsia, classically from lesions pressing the uncrossed temporal retinal fibers on both sides. Bitemporal hemianopsia (the more famous chiasmal pattern) is loss of both TEMPORAL fields. A scotoma is an isolated island of loss, and plain ''hemianopsia'' just means half-field loss without specifying side. Field name = side that is BLIND."}'),
  ('aadda0aa-1g','{"options": ["devoid of pigment cells", "last layer of the sclera", "contains pigment cells", "first layer of the choroid"], "correct": 0, "explanation": "The lamina fusca is the innermost scleral layer and it is brown because it CONTAINS pigment (melanocytes), so ''devoid of pigment cells'' is the false statement. It is correctly the last (deepest) scleral layer and blends into the suprachoroid, so it can be described as bordering the first layer of the choroid. Fusca = dusky/brown = pigmented."}'),
  ('38e77f55-25','{"options": ["Enophthalmos", "Exophthalmos", "Buphthalmos", "Anophthalmos"], "correct": 0, "explanation": "Enophthalmos is the posterior sinking (recession) of the globe into the orbit, classically after an orbital blowout fracture drops the floor. Exophthalmos/proptosis is the eye bulging FORWARD, buphthalmos is an enlarged globe (congenital glaucoma), and anophthalmos is absence of the eye. En- = inward/sunken."}'),
  ('5cdda1cb-19','{"options": ["Choriocapillaris", "Haller''s", "Ruysch", "Brucke''s"], "correct": 0, "explanation": "The choroid is layered by vessel size: Haller''s layer (large vessels) outermost, Sattler''s (medium) next, and the choriocapillaris (the fine capillary bed) innermost against Bruch''s membrane. So the small vessels are the choriocapillaris. Haller''s is the large-vessel layer; the choriocapillaris nourishes the outer retina/RPE."}'),
  ('6a849b62-w','{"options": ["Epidermis", "Superficial fascia", "Dermis", "Deep fascia"], "correct": 2, "explanation": "The skin (integument) has two layers: the superficial epidermis and the deeper dermis, so the deep part of the SKIN is the dermis. The superficial and deep fascia lie beneath the skin (in the subcutaneous/deeper planes), not within it. Skin = epidermis (top) + dermis (deep)."}'),
  ('c33d4bcb-10','{"options": ["Ciliary Body", "Choroid", "Iris", "Crystalline Lens"], "correct": 3, "explanation": "The uveal tract (vascular middle coat) is the iris, ciliary body, and choroid. The crystalline lens is a separate transparent refractive structure suspended by zonules, not part of the uvea. Uvea = ICC: Iris, Ciliary body, Choroid."}'),
  ('1c43bc78-13','{"options": ["zygomatic", "parietal", "sphenoid", "lacrimal"], "correct": 2, "explanation": "The sphenoid is a single midline (unpaired) bone. The zygomatic, parietal, and lacrimal bones each come as a left-right pair. The unpaired cranial bones are the frontal, occipital, sphenoid, ethmoid, plus the midline facial vomer and mandible."}'),
  ('7a064946-1o','{"options": ["hematuria", "pyuria", "albuminuria", "oliguria"], "correct": 1, "explanation": "Pyuria is pus (leukocytes) in the urine, a sign of urinary tract infection. Hematuria is blood in urine, albuminuria/proteinuria is protein in urine, and oliguria is a low urine volume. Py- = pus."}'),
  ('2a458564-1l','{"options": ["are made up of 2 images produced by the cornea and 2 images by the crystalline lens", "are formed at the refracting interfaces of the eye", "are all virtual images", "are all erect images"], "correct": 0, "explanation": "Catoptric (Purkinje-Sanson) images are the FOUR reflections formed at the eye''s reflecting surfaces: two from the cornea (anterior and posterior) and two from the lens (anterior and posterior), so A is correct. They are formed at REFLECTING, not refracting, interfaces (ruling out B). They are not all virtual or all erect: image III (from the posterior lens surface, a concave mirror) is real and inverted, while I, II, and IV are virtual and erect. 4 images: 2 cornea + 2 lens."}'),
  ('3807671d-2e','{"options": ["coffee, tea, whole grains", "salty food", "sugary foods and energy drinks", "fried food, French fries"], "correct": 0, "explanation": "Coffee, tea, and whole grains are rich in antioxidants (polyphenols, vitamin E, selenium) that combat the oxidative lens damage behind cataract. Salty food, sugary foods/energy drinks, and fried food carry little antioxidant value and add metabolic/oxidative stress. Antioxidants come from plant-based, minimally processed foods."}'),
  ('d07b7680-1x','{"options": ["Bi-temporal hemianopsia", "Bi-nasal hemianopsia", "Hemianopsia", "Scotoma"], "correct": 0, "explanation": "Loss of both TEMPORAL half-fields is bitemporal hemianopsia, the classic sign of a chiasmal lesion (for example a pituitary tumor) that damages the crossing nasal-retinal fibers. Binasal hemianopsia is loss of both nasal fields; a scotoma is a focal island of loss. Chiasm compression = bitemporal (''tunnel to the sides'')."}'),
  ('3254fb16-1u','{"options": ["Pupil", "Posterior Chamber", "Conjunctiva", "Iris"], "correct": 3, "explanation": "The iris is the pigmented diaphragm sitting in front of the crystalline lens and behind the cornea, dividing the anterior and posterior chambers. The pupil is just its central hole (not a structure), the posterior chamber lies behind the iris, and the conjunctiva covers the sclera/lid. The iris is the curtain between cornea and lens."}'),
  ('9e8598eb-20','{"options": ["30 degrees from the point of fixation", "20 degrees from the point of fixation", "90 degrees from the point of fixation", "Entire visual field"], "correct": 0, "explanation": "Standard automated (static threshold) perimetry tests the central field, typically the central 30 degrees from fixation (as in a 30-2 or 24-2 program), where most clinically important defects appear. Full-field mapping to the far periphery (out to about 90 degrees temporally) is done with kinetic (Goldmann) perimetry. Automated = central 30."}'),
  ('16a8f267-2q','{"options": ["Pupil", "Conjunctiva", "Iris", "Sclera"], "correct": 2, "explanation": "The iris is the anterior part of the uvea and acts as the eye''s adjustable diaphragm, sitting between the cornea and the lens and controlling how much light enters. The pupil is only its aperture, the conjunctiva is a surface membrane, and the sclera is the outer coat. Iris = the aperture-controlling diaphragm."}'),
  ('17e9b719-1t','{"options": ["Paralysis", "Dilation", "Accommodation", "Constriction"], "correct": 3, "explanation": "The sphincter (constrictor) pupillae is a circular parasympathetic muscle, so its contraction constricts the pupil (miosis). Dilation is the job of the radial dilator pupillae (sympathetic). Accommodation is driven by the ciliary muscle, not the iris sphincter. Sphincter squeezes the pupil small."}'),
  ('4fb9a33a-1e','{"options": ["C1 - C8", "T1 - T8", "L4, L5, S1 - S3", "C5 - C8, T1"], "correct": 3, "explanation": "The brachial plexus (which supplies the upper limb) arises from the ventral rami of C5 through T1. C1-C8 and T1-T8 are wrong ranges, and L4-S3 forms the lumbosacral plexus for the lower limb. Brachial plexus = C5 to T1."}'),
  ('f1a04180-1a','{"options": ["Anterior pole", "Posterior pole", "Visual axis", "Geometric axis"], "correct": 0, "explanation": "The anterior pole of the eye is taken as the central point (apex) of the corneal curvature, the anterior end of the geometric axis. The posterior pole is the corresponding central point of the back of the globe, and the visual/geometric axes are LINES, not a single point. VERIFY: strictly the true center of curvature of the corneal surface is a point about 7.8 mm behind the cornea on the axis, which none of the options names exactly, so this item keys loosely on the anterior pole as the corneal center."}'),
  ('f970b61a-33','{"options": ["measuring ocular deviation", "measuring ocular thickness", "measuring accommodation", "corneal curvature"], "correct": 2, "explanation": "The first Purkinje image (bright reflex off the anterior cornea) is used for keratometry (corneal curvature) and for corneal-reflex tests of ocular deviation (Hirschberg), but it does NOT change with accommodation, so it cannot measure accommodation, which is tracked instead by the lens images (Purkinje III and IV). VERIFY: the item''s ''ocular thickness'' option is also arguable, but accommodation is the classic effect the corneal image cannot capture. Accommodation shows up in the LENS reflexes, not the corneal one."}'),
  ('7aeb058d-1x','{"options": ["Scleral layer", "Episclera", "Lamina fusca", "Lamina cribrosa"], "correct": 2, "explanation": "The lamina fusca is the innermost, pigmented scleral layer, and its loose lamellae blend with the suprachoroid (the outer choroidal lamellae of the uvea). The episclera is the outer vascular scleral surface, and the lamina cribrosa is the sieve-like scleral opening for the optic nerve. Lamina fusca bridges sclera to choroid."}'),
  ('6a3ef4c2-2i','{"options": ["Vitamin A and D", "Beta-carotene and Omega-3", "Lutein and Zeaxanthin", "Selenium and Vitamin C"], "correct": 2, "explanation": "Lutein and zeaxanthin are the carotenoids that concentrate as the macular pigment, filtering blue light and quenching free radicals, and are the combination specifically linked to lower cataract and age-related macular degeneration risk (the AREDS-type story). The other pairs have general roles but are not the signature macular-protective duo. Macular pigment = lutein + zeaxanthin."}'),
  ('2afbc9a9-1i','{"options": ["Optic disc", "Optic tract", "Geniculate body", "Optic chiasm"], "correct": 0, "explanation": "The optic disc has no photoreceptors (it is where axons leave the eye), so it is the blind spot and is non-reactive to light. The optic tract, geniculate body, and chiasm are downstream relay pathways, not the light-insensitive spot on the retina itself. Optic disc = physiologic blind spot."}'),
  ('ebaa7f0f-20','{"options": ["Destruction of the normal eyelid architecture", "Slow painless growth", "Well-circumscribed lesion", "Very painful growth"], "correct": 0, "explanation": "Destruction of the normal eyelid architecture (loss of the lid margin, distorted lashes, ulceration) is a hallmark of MALIGNANCY, not a benign lesion, so it is the correct ''NOT benign'' answer. Benign lesions are typically slow, painless, and well-circumscribed. VERIFY: ''very painful growth'' is also atypical of a benign lesion, so the item has two non-benign options; architecture destruction is the classic malignancy sign the key intends. Benign = slow, painless, defined; malignant = destructive."}'),
  ('f7b8c3b9-20','{"options": ["squamous", "wing", "flat", "columnar"], "correct": 2, "explanation": "The corneal epithelium has three named cell layers: superficial SQUAMOUS cells, intermediate WING cells, and deep basal COLUMNAR cells, so squamous, wing, and columnar are all genuine types and ''flat'' is the odd one out (it merely re-describes the squamous cells rather than naming a separate layer). VERIFY: because squamous cells ARE flat, this item is loosely worded; the intended EXCEPT is the redundant ''flat.'' Three layers: basal columnar, wing, superficial squamous."}'),
  ('0c41da12-1w','{"options": ["lack of sleep", "spending a lot of time on gadgets", "proper nutrition", "parents are too busy working"], "correct": 2, "explanation": "Proper nutrition PREVENTS vitamin deficiency, so it is the item that does not cause it (the EXCEPT). Poor sleep, excessive screen/gadget time (often displacing healthy meals and sun exposure), and unsupervised eating when parents are busy all contribute to deficient intake. The one healthy habit in the list is the exception."}'),
  ('002d5626-1c','{"options": ["end point of the visual pathway", "processing center for visual information", "receives input from the optic radiation", "receiver of input from optic tract"], "correct": 3, "explanation": "The visual cortex receives its input from the optic RADIATIONS (which come from the lateral geniculate nucleus), not directly from the optic TRACT, so ''receiver of input from optic tract'' is false. It is correctly the end point of the pathway, the processing center, and the target of the optic radiations. Pathway: optic tract to LGN to optic radiation to visual cortex."}'),
  ('82976db6-2o','{"options": ["They are rarely sensitive to the color of the light on their receptive fields.", "They are orientation selective.", "They analyze spatial information at a finer level of detail than Magno cells.", "They respond more quickly and transiently than M cells."], "correct": 2, "explanation": "Parvocellular (P) cells have small receptive fields and high spatial resolution, so they analyze fine spatial detail better than the magnocellular (M) cells, making C correct. They ARE color sensitive (so A is wrong), orientation selectivity is a cortical property not an LGN one (B wrong), and it is the M cells that respond quickly and transiently while P cells are sustained (D wrong). Parvo = detail + color, sustained; Magno = motion + contrast, fast."}'),
  ('30806ac1-17','{"options": ["Lens capsule", "Ciliary processes", "Ocular plexiform", "Zonular fibers"], "correct": 2, "explanation": "The ''ocular plexiform'' (a plexiform LAYER of the retina) plays no role in accommodation, which is a physical reshaping of the lens. Accommodation involves the ciliary muscle/body relaxing the zonular fibers so the elastic lens capsule can round the lens. The retinal plexiform layer is about neural signaling, not focusing."}'),
  ('6d23735d-13','{"options": ["Oculomotor", "Trochlear", "Optic", "Abducent"], "correct": 0, "explanation": "The inferior rectus is supplied by the oculomotor nerve (CN III), which runs four of the six extraocular muscles. The trochlear (CN IV) serves only the superior oblique, the abducent (CN VI) only the lateral rectus, and the optic nerve is sensory (vision), not motor. LR6 SO4, all the rest CN3: inferior rectus is a CN3 muscle."}'),
  ('1cd06215-2z','{"options": ["Midbrain", "Cerebellum", "Frontal lobe", "Pons varolii"], "correct": 0, "explanation": "The midbrain houses the oculomotor (CN III) and trochlear (CN IV) nuclei plus the Edinger-Westphal nucleus, so it coordinates eye movements, pupil size, and the accommodation (lens shape) reflex. The cerebellum fine-tunes coordination generally, the frontal lobe initiates saccades, and the pons contains the CN VI/horizontal gaze centers, but the integrator of pupil and lens control is the midbrain. Pupil + lens + eye-movement nuclei = midbrain."}'),
  ('74538f68-23','{"options": ["Isopter", "Peripheral vision", "Visual field", "Central vision"], "correct": 2, "explanation": "The visual field is the whole area visible while the eye fixates one target. An isopter is just one contour line of equal sensitivity on a field plot, peripheral vision is only the outer part, and central vision is only the foveal part. Visual field = everything seen at one fixation."}'),
  ('44171ef1-1n','{"options": ["The human model eye is based on the principle of thick lenses", "The cornea contributes 2/3 to the power of the eye.", "The nodal points coincide with the principal points.", "The eye is about 24.0 mm in axial length."], "correct": 2, "explanation": "In Gullstrand''s schematic eye the nodal points and principal points do NOT coincide (because the media on the two sides differ, image space is not air), so C is the contradicting statement. The true statements: it is a thick-lens model, the cornea provides about two-thirds of the eye''s roughly 60 D, and the axial length is about 24 mm. Nodal and principal points separate whenever object and image media differ."}'),
  ('18dad4d5-2d','{"options": ["Total hemianopsia", "Hemianopsia", "Congruous hemianopsia", "Partial hemianopsia"], "correct": 3, "explanation": "Partial hemianopsia is loss of LESS than a full half-field (an incomplete defect, such as a quadrant). A total (complete) hemianopsia loses the entire half, and ''congruous'' describes matching defects between the two eyes, not the amount lost. Partial = incomplete half-field."}'),
  ('d97093db-1d','{"options": ["360 degrees", "90 degrees", "180 degrees", "45 degrees"], "correct": 2, "explanation": "With both eyes open the horizontal binocular visual field spans roughly 180 to 200 degrees, so 180 degrees is the best answer. A single eye covers about 150 degrees; the two overlap centrally for stereopsis and extend the total width sideways. Two eyes together = about 180 degrees wide."}'),
  ('9e4a8fdf-2r','{"options": ["Bipolar cells", "Cones", "Fibers of muller", "Rods"], "correct": 1, "explanation": "Cones give high-acuity, color (photopic) vision and work in bright light; they are packed in the fovea. Rods handle dim (scotopic) light and motion but not color or fine detail. Bipolar cells are relay neurons (not photoreceptors), and Muller fibers are glial support. Cones = Color + Clarity + bright light."}'),
  ('fcdf7350-1u','{"options": ["diaphragm", "peritoneum", "thoracic cage", "fascia"], "correct": 0, "explanation": "The diaphragm is the dome-shaped muscle that separates the thoracic cavity above from the abdominopelvic cavity below and drives breathing. The peritoneum lines the abdominal cavity, the thoracic cage is bony wall, and fascia is connective wrapping. Diaphragm = the floor of the chest."}'),
  ('f0590c28-1e','{"options": ["enhances labor", "milk production", "development of alveoli", "ejection of colostrums"], "correct": 3, "explanation": "Oxytocin causes milk EJECTION (let-down / expelling colostrum) by squeezing the myoepithelial cells. Prolactin makes the milk; oxytocin pushes it out. Hint: OXytocin = OUT (ejection); prolactin = production."}'),
  ('647d164b-2g','{"options": ["Dot and blot hemorrhages", "Cotton-wool spots", "Neovascularization on the disc", "Microaneurysm"], "correct": 2, "explanation": "Neovascularization (new vessels, for example on the disc) DEFINES PROLIFERATIVE diabetic retinopathy, so it is not an NPDR finding. Dot-and-blot hemorrhages, cotton-wool spots, and microaneurysms are all non-proliferative (background) features. New vessels = the jump to proliferative disease."}'),
  ('9dd8a4c7-18','{"options": ["Choroid", "Ciliary body", "Crystalline lens", "Cornea"], "correct": 2, "explanation": "The iris rests its posterior surface on the front of the crystalline lens, which supports it; if the lens is removed (aphakia) the iris trembles (iridodonesis). The ciliary body is where the iris root attaches, the choroid is posterior, and the cornea is anterior with the aqueous-filled anterior chamber between. Iris lies on the lens."}'),
  ('1faf2359-1d','{"options": ["Ocular swelling", "Double vision", "Loss of color", "Light sensitivity"], "correct": 1, "explanation": "The major functional symptom of an orbital (blowout) fracture is double vision (diplopia), because an extraocular muscle (often the inferior rectus) becomes entrapped and limits eye movement. Swelling is a nonspecific sign, and loss of color or light sensitivity point to optic-nerve or corneal problems, not the fracture itself. Blowout fracture = entrapment = diplopia."}'),
  ('66548827-1e','{"options": ["+10.00", "+27.00", "+19.00", "+35.00"], "correct": 2, "explanation": "The crystalline lens contributes about +19 D to the eye''s total power. The cornea supplies the larger share (about +43 D), and together they give the roughly +60 D of the whole eye. Cornea about +43, lens about +19, eye about +60."}'),
  ('07ae987d-1y','{"options": ["Red-green defect is common in acquired optic nerve disease.", "Blue cone is sensitive to longer wavelength than green cone.", "Blue-yellow defect is common in glaucoma.", "Deuteranomaly is more common than deuteranopia."], "correct": 1, "explanation": "The blue (S) cone peaks at a SHORTER wavelength (about 420 nm) than the green (M) cone (about 530 nm), so saying the blue cone senses a LONGER wavelength than green is false. The true statements: acquired optic-nerve disease tends to give red-green loss, glaucoma tends to give blue-yellow loss, and the milder deuteranomaly is more common than the complete deuteranopia. Blue = short wavelength."}'),
  ('407d6c5d-10','{"options": ["Optic disc", "Cones", "Rods", "Macula"], "correct": 2, "explanation": "Visual purple is rhodopsin, the light-sensitive pigment found in the rods, which is bleached by light and mediates dim-light vision. Cones contain photopsins (color pigments), the optic disc has no photoreceptors, and the macula is cone-rich for acuity. Visual purple = rhodopsin = rods."}'),
  ('16e65da1-1y','{"options": ["Bowman''s layer", "Descemet''s membrane", "Anterior epithelium", "Corneal stroma"], "correct": 0, "explanation": "Bowman''s layer does not regenerate, so once it is breached the cornea heals with a permanent scar. The anterior epithelium regenerates cleanly without scarring, and Descemet''s membrane is regenerated by the endothelium. (Deep stromal injury can also scar, but Bowman''s is the classic ''damage-here-means-scar'' layer.) Bowman''s does not come back; it scars."}'),
  ('349d2aed-1o','{"options": ["Swinging penlight", "Schirmer''s", "Tear break up time", "Phenylephrine"], "correct": 0, "explanation": "The swinging (flashlight) penlight test screens for a relative afferent pupillary defect (Marcus Gunn pupil), a neuro sign of optic-nerve or retinal disease. Schirmer''s and tear break-up time assess the tear film (dry eye), and phenylephrine is a dilating drop, not a neuro test. Swinging penlight = RAPD = afferent pathway check."}'),
  ('f19ff031-22','{"options": ["Lateral rectus", "Inferior rectus", "Medial rectus", "Superior rectus"], "correct": 0, "explanation": "By the Spiral of Tillaux, the recti insert progressively farther from the limbus: medial 5.5, inferior 6.5, lateral 6.9, superior 7.7 mm. So 6.9 mm corresponds to the lateral rectus. Spiral of Tillaux: MR 5.5, IR 6.5, LR 6.9, SR 7.7."}'),
  ('156b7fb6-1a','{"options": ["Choroidal vessels", "Scleral vessels", "Ophthalmic artery", "Arterial circle of Zinn"], "correct": 1, "explanation": "The optic nerve head is fed by the peripapillary choroidal vessels, branches of the ophthalmic artery (posterior ciliary arteries), and the arterial circle of Zinn-Haller. The sclera is a dense, nearly avascular fibrous coat, so ''scleral vessels'' are not a source of optic-nerve blood supply. Optic nerve supply = ciliary/choroidal + circle of Zinn, not sclera."}'),
  ('8fd5a190-2y','{"options": ["Eyebrows", "Eyelids", "Lacrimal gland", "Conjunctiva"], "correct": 1, "explanation": "The eyelids spread the tear film evenly across the ocular surface with each blink (like windshield wipers). The lacrimal gland PRODUCES tears, the conjunctiva is the surface being wetted, and the eyebrows shield sweat/light. Blinking lids = tear distribution."}'),
  ('444f4a98-1m','{"options": ["Maxillary", "Zygomatic", "Nasal", "Mandible"], "correct": 3, "explanation": "In the context of orbital/midface trauma, the maxillary, zygomatic, and nasal bones are the ones commonly fractured (they form the orbit and midface). The mandible is the lower jaw, part of the lower face, so it is the odd one out here. VERIFY: the mandible IS one of the most fractured facial bones in general trauma, so if the item means ''facial fractures'' broadly the key is debatable; as a midface/orbital grouping the answer is the mandible."}'),
  ('17b1bb17-3w','{"options": ["Lens equator", "Lens cortex", "Anterior lens epithelium", "Lens capsule"], "correct": 3, "explanation": "The lens capsule is a thick basement membrane made mainly of type IV collagen; it is elastic, holds the lens fibers together, and reshapes (molds) the lens when zonular tension changes during accommodation. The equator is where zonules attach, the cortex is the outer fiber mass, and the anterior epithelium is a single cell layer under the front capsule. Capsule = type IV collagen elastic bag."}'),
  ('e28eab07-17','{"options": ["Sebaceous", "Ciliary", "Lacrimal", "Tarsal"], "correct": 1, "explanation": "The glands of Moll are the modified apocrine SWEAT glands of the eyelid margin, also called the ciliary glands. The sebaceous glands of Zeis make oil, the lacrimal gland makes tears, and the tarsal (Meibomian) glands make the lipid layer. Moll = ciliary = eyelid sweat glands."}'),
  ('6d281043-1c','{"options": ["Dua layer", "Bruch''s membrane", "Descemet''s membrane", "Bowman''s membrane"], "correct": 1, "explanation": "Bruch''s membrane belongs to the choroid/RPE complex at the back of the eye, not the cornea. The corneal layers front to back are epithelium, Bowman''s, stroma, Dua''s (a recently described pre-Descemet layer), Descemet''s, and endothelium. Bruch''s is a back-of-the-eye membrane."}'),
  ('774302a4-2h','{"options": ["Photoreceptor cells", "Bipolar cells", "Glial cells", "Ganglion cells"], "correct": 2, "explanation": "Glial (Muller) cells are non-neuronal support cells and do not generate or conduct action potentials. Ganglion cells clearly do (their axons form the optic nerve). VERIFY: strictly, photoreceptors and bipolar cells also signal with GRADED potentials rather than true action potentials, so those options are defensible too; the cleanest ''non-conducting'' answer is the glial cell. Glia support, they do not fire."}'),
  ('61d0c03a-2g','{"options": ["Horizontal", "Ganglion", "Bipolar", "Amacrine"], "correct": 1, "explanation": "The inner nuclear layer holds the nuclei of horizontal, bipolar, amacrine, and Muller cells. Ganglion cell nuclei sit in their own separate ganglion cell layer (the innermost cell layer), so they are the exception. INL = Horizontal, Bipolar, Amacrine (and Muller); ganglion cells have their own layer."}'),
  ('96b36e51-3a','{"options": ["proprioreceptors", "mechanoreceptors", "nocireceptors", "thermoreceptors"], "correct": 1, "explanation": "Vibration and pressure are sensed by mechanoreceptors (for example Pacinian corpuscles, which are tuned to vibration). Proprioceptors sense body/joint position, nociceptors sense pain, and thermoreceptors sense temperature. Mechano- = mechanical stimuli = touch/pressure/vibration."}'),
  ('3048ae3a-17','{"options": ["sense of position", "sense of pain", "cold temperature", "vibrations"], "correct": 1, "explanation": "Nociceptors are the pain receptors, firing in response to tissue-damaging stimuli. Position sense is proprioception, cold is a thermoreceptor function, and vibration is mechanoreception. Noci- (from ''noxious'') = pain."}'),
  ('c4b90951-16','{"options": ["Retina", "Crystalline lens", "Choroid and ciliary body", "Sclera and cornea"], "correct": 2, "explanation": "The vascular coat (uvea) is the choroid, ciliary body, and iris; among the options ''choroid and ciliary body'' names it. The retina is the inner neural coat, and the sclera and cornea form the outer fibrous coat. Three coats: fibrous (sclera/cornea), vascular (uvea), neural (retina)."}'),
  ('663779e6-1b','{"options": ["electrocardiogram", "ventilator or respirator", "sphygmomanometer", "spirometer"], "correct": 3, "explanation": "A spirometer measures lung volumes and airflow (pulmonary ventilation). The ECG records heart electrical activity, a ventilator/respirator supports breathing rather than measuring it, and a sphygmomanometer measures blood pressure. Spiro- = breathing measurement."}'),
  ('92b5d8f3-2d','{"options": ["lower surface", "upper surface", "tip", "edge"], "correct": 3, "explanation": "Lemon is SOUR, and on the classic tongue map sour is sensed mainly along the sides/edges of the tongue. The tip is associated with sweet (and salt), and the back with bitter. (Modern science shows all tastes are sensed broadly, but the board map assigns sour to the edges.) Sour = sides/edges."}'),
  ('a3fc4be8-p','{"options": ["Closure of the eyelid", "More light enters the eye", "Parasympathetic nerve innervated", "Sympathetic nerve is innervated"], "correct": 3, "explanation": "Pupil dilation (mydriasis) comes from SYMPATHETIC activation of the radial dilator pupillae muscle (fight-or-flight). Parasympathetic activity does the opposite (constriction via the sphincter). Bright light also constricts, not dilates. Sympathetic = dilate; parasympathetic = constrict."}'),
  ('0b4b944c-3t','{"options": ["Edward Hering and Wheatstone", "Bela Julesz and Edwald Hering", "Wheatstone and Torsten Wiesel", "David Hubel and Torsten Wiesel"], "correct": 3, "explanation": "David Hubel and Torsten Wiesel won the 1981 Nobel Prize for mapping how neurons in the primary visual cortex process information (orientation columns, ocular dominance). Hering is known for opponent-color theory, Wheatstone for the stereoscope, and Julesz for random-dot stereograms. Cortical visual neurons = Hubel and Wiesel."}'),
  ('c7b50c4b-2o','{"options": ["Snowbanking", "Vitreous flare", "Snowballs", "Vitreous cells"], "correct": 2, "explanation": "''Snowballs'' are the rounded aggregates of inflammatory cells floating in the vitreous, the classic sign of intermediate uveitis (pars planitis). ''Snowbanking'' is the exudate plastered over the pars plana, vitreous flare is protein haze, and scattered vitreous cells are individual, not aggregated. Snowballs float; snowbank plasters the pars plana."}'),
  ('68e65d13-1x','{"options": ["Abducens", "Optic", "Trochlear", "Facial"], "correct": 0, "explanation": "The abducens nerve (CN VI) drives the lateral rectus, which ABDUCTS (turns out) the eye. The optic nerve is sensory, the trochlear runs the superior oblique, and the facial nerve closes the lids. Abducens ABDUCTS."}'),
  ('d648fe49-1s','{"options": ["Superficial temporal artery", "Occipital artery", "Facial artery", "Posterior auricular artery"], "correct": 1, "explanation": "The occipital artery supplies the back (posterior) of the scalp. The superficial temporal supplies the side/top, the facial artery the face, and the posterior auricular the region behind the ear. Occipital = the occiput (back of head)."}'),
  ('4ec3bda8-11','{"options": ["Fovea centralis", "Ora serrata", "Macula lutea", "Optic disc"], "correct": 0, "explanation": "The fovea centralis (specifically the foveola) is the thinnest part of the retina: the inner layers are swept aside to form a pit so light hits the cones directly, giving sharpest vision. The ora serrata is the peripheral edge, the macula surrounds the fovea, and the optic disc is the nerve-head, not retinal tissue. Foveal pit = thinnest retina."}'),
  ('96bd020b-14','{"options": ["0.52", "0.75", "0.25", "1.0"], "correct": 0, "explanation": "The central cornea is about 0.52 mm (520 microns) thick, thinning centrally and thickening toward the periphery (about 0.7 mm). This central pachymetry value matters for tonometry correction and refractive surgery. Center about 0.5 mm, periphery about 0.7 mm."}'),
  ('88e8dcd7-1x','{"options": ["Vagus", "Hypoglossal", "Glosopharyngeal", "Facial"], "correct": 1, "explanation": "The hypoglossal nerve (CN XII) is the motor nerve to the tongue muscles, controlling its shape and movement. The vagus and glossopharyngeal carry taste/sensory and pharyngeal functions, and the facial nerve carries taste from the anterior tongue but not tongue movement. Hypoglossal = tongue muscles (hypo-GLOSSAL = under the tongue)."}'),
  ('077bbfd6-2o','{"options": ["hearing", "smell", "balance", "tactile"], "correct": 2, "explanation": "The three semicircular canals sense head rotation and are the organs of balance/equilibrium, which is the function this item emphasizes. VERIFY: the organ of Corti (also named in the stem) is actually the organ of HEARING, so the stem mixes two functions; if the key is testing the semicircular canals it is balance, if the organ of Corti it is hearing. Semicircular canals = balance; organ of Corti = hearing."}'),
  ('b8a31ae1-11','{"options": ["ossicles", "corti", "eardrum", "cochlea"], "correct": 0, "explanation": "The smallest bone in the body is the stapes, one of the middle-ear ossicles, so ''ossicles'' is the answer among these. The organ of Corti, the eardrum (tympanic membrane), and the cochlea are not bones. Smallest bone = stapes (an ear ossicle)."}'),
  ('207cdde1-2g','{"options": ["Somato-sensory", "Digestive", "Olfactory", "Parieto-sensory"], "correct": 0, "explanation": "Touch, heat, and pain from the skin are carried by the somatosensory system to the brain. The digestive system handles food processing, olfactory is smell, and ''parieto-sensory'' is not a standard system name. Skin senses = somatosensory."}'),
  ('7cb983d2-11','{"options": ["Regulation of temperature", "Control sight", "Control muscle tone and coordination of muscle movement", "Receive and interprets sensation of pain, touch and pressure"], "correct": 2, "explanation": "The cerebellum controls muscle tone, balance, and the smooth coordination of movement. Temperature regulation is the hypothalamus, vision is the occipital cortex, and interpreting pain/touch/pressure is the somatosensory cortex. Cerebellum = coordination and balance."}'),
  ('4cb900fd-1b','{"options": ["ears", "eyelid", "eye", "head"], "correct": 2, "explanation": "The eye is the sensory organ of the visual system. The ears serve hearing/balance, the eyelid only protects the eye, and the head is the general structure housing many systems. Vision = the eye."}'),
  ('593a5080-14','{"options": ["blood vessels", "chondroblasts", "osteoblasts", "osteocytes"], "correct": 0, "explanation": "Haversian (central) canals run through compact bone and carry the blood vessels (and nerves) that nourish the osteocytes. Chondroblasts build cartilage, osteoblasts build bone matrix (they line surfaces), and osteocytes sit in lacunae within the matrix, not in the canal itself. Haversian canal = the bone''s plumbing (vessels)."}'),
  ('1ce0b096-2c','{"options": ["Anterior Epithelium", "Endothelium", "Corneal Stroma", "Descemet''s membrane"], "correct": 1, "explanation": "The corneal endothelium runs the metabolic pump that continuously moves fluid out of the stroma, keeping the cornea in its semi-dehydrated (deturgescent) clear state. If the endothelium fails, the stroma swells and the cornea clouds (as in Fuchs'' dystrophy). The epithelium is a barrier but does not pump; the stroma is what stays dehydrated. Endothelial pump = corneal clarity."}'),
  ('7ba2e784-1s','{"options": ["Arthrology", "Neurology", "Kinesiology", "Splanchnology"], "correct": 0, "explanation": "Arthrology is the study of joints (arthro- = joint). Neurology studies nerves, kinesiology studies movement, and splanchnology studies the viscera/internal organs. Arthro = joint."}'),
  ('62effcab-26','{"options": ["Nasal Septum", "Nostrils", "Mucous membrane", "Sinuses"], "correct": 3, "explanation": "The paranasal sinuses are air-filled cavities that resonate and enrich the voice (which is why a congested nose changes voice quality). The nasal septum divides the nose, the nostrils are the openings, and the mucous membrane humidifies and filters air. Sinuses = voice resonators."}'),
  ('d8b406ea-3x','{"options": ["Squamous epithelial", "Squamous epithelium", "Stratified columnar epithelium", "Cuboidal"], "correct": 2, "explanation": "That surface is the conjunctiva, which is lined by stratified columnar epithelium (with goblet cells that add mucus to the tear film). The cornea itself is stratified squamous, but the conjunctiva lateral to it is stratified columnar. Conjunctiva = stratified columnar with goblet cells."}'),
  ('2101e838-22','{"options": ["redness", "normal function", "heat", "swelling"], "correct": 1, "explanation": "The cardinal signs of acute inflammation are redness (rubor), heat (calor), swelling (tumor), pain (dolor), and LOSS of function. ''Normal function'' is the opposite, so it is the EXCEPT. Inflammation impairs function, it does not preserve it."}'),
  ('90cce3e9-1j','{"options": ["Optic disc", "Fovea centralis", "Ora serrata", "Macula lutea"], "correct": 1, "explanation": "The fovea centralis has the densest packing of cones and the finest spatial resolution, giving the greatest visual acuity/sensitivity for detail. The optic disc is blind, the ora serrata is the far periphery, and the macula surrounds and includes the fovea but the peak point is the fovea. Sharpest vision = fovea centralis."}'),
  ('b4fcc631-1p','{"options": ["Inferior palpebral sulcus", "Superior palpebral sulcus", "Horizontal fold", "Common canaliculus"], "correct": 3, "explanation": "The upper and lower lacrimal canaliculi usually unite to form the common canaliculus (of Maier), which then opens into the lacrimal sac. The palpebral sulci are lid folds, not drainage junctions. Two canaliculi merge into the common canaliculus, then the sac."}'),
  ('a9e9136f-14','{"options": ["Lamina vitrea", "Endothelium", "Retina", "Lamina fusca"], "correct": 3, "explanation": "The lamina fusca is the innermost (brown, pigmented) surface of the sclera, facing the suprachoroid. The lamina vitrea is Bruch''s membrane of the choroid, the endothelium lines the cornea/vessels, and the retina is a separate inner coat. Inner sclera = lamina fusca."}'),
  ('fc20b858-16','{"options": ["Nourishes the eye", "Gives shape to the eyeball", "Strong, opaque, white fibrous", "Weak with yellow fibers"], "correct": 2, "explanation": "The sclera is best described as a strong, opaque, white fibrous coat (dense collagen) that protects the inner eye and gives it shape. ''Gives shape'' is a function but not the best structural description, ''nourishes the eye'' is the choroid''s job, and the sclera is strong (not weak with yellow fibers). Sclera = tough white collagen shell."}'),
  ('ac8e0eab-1f','{"options": ["smooth muscle fibers", "dilator pupillae", "pigment epithelium", "dua layer"], "correct": 3, "explanation": "The Dua layer is a deep corneal layer, not an iris structure. The iris does contain smooth muscle fibers (sphincter and dilator pupillae) and a posterior pigment epithelium. Dua = cornea, not iris."}'),
  ('e16978c4-1n','{"options": ["Painless blurring of vision", "Nyctalopia", "Blocked vision", "Floaters"], "correct": 3, "explanation": "Intermediate uveitis (pars planitis) classically presents with FLOATERS (from the inflammatory cells and snowballs in the vitreous), usually with little pain or redness. VERIFY: ''painless blurring of vision'' is also a genuine symptom, so the item has two defensible answers; floaters are the more distinctive complaint the key targets. Nyctalopia (night blindness) and ''blocked vision'' are not typical. Floaters + painless blur, quiet eye = intermediate uveitis."}'),
  ('67b83057-1o','{"options": ["retina", "iris", "choroid", "ciliary body"], "correct": 0, "explanation": "The middle layer is the uvea: iris, ciliary body, and choroid. The retina is the INNER (neural) layer, so it is the EXCEPT. Three coats: outer fibrous, middle uvea, inner retina."}'),
  ('6186e057-66','{"options": ["Dry eye syndrome", "Chalazion", "Blepharitis", "Meibomian gland dysfunction"], "correct": 3, "explanation": "Progressive obstruction of the Meibomian glands, with plugged orifices and an unstable (short) tear film, defines Meibomian gland dysfunction (MGD), the leading cause of evaporative dry eye. A chalazion is a single blocked-gland granuloma, blepharitis is lid-margin inflammation more broadly, and dry eye syndrome is the downstream result rather than the gland disease itself. Plugged glands + short TBUT = MGD."}'),
  ('fd03c8d9-1i','{"options": ["Lacrimal sac", "Canaliculi", "Nasociliary canal", "Lacrimal ducts"], "correct": 3, "explanation": "The lacrimal gland''s orbital and palpebral lobes are connected by its excretory lacrimal ducts, which pass from the orbital lobe through the palpebral lobe to open into the superior conjunctival fornix. The canaliculi and sac belong to the drainage system, not the gland''s internal connection. Lacrimal ducts link the two lobes."}'),
  ('283cb968-1s','{"options": ["Schirmer I", "Basic secretion test", "Tear break-up time", "Schirmer II"], "correct": 0, "explanation": "Schirmer I is done WITHOUT anesthesia, so the strip stimulates reflex tearing on top of basal secretion, measuring total (basic + reflex) tearing. The basic secretion test uses anesthesia to remove the reflex component (basic only), Schirmer II adds nasal stimulation to test reflex tearing, and TBUT measures film stability. No anesthesia (Schirmer I) = basic + reflex."}'),
  ('902bd34e-2o','{"options": ["Bowman''s membrane", "Corneal epithelium", "Corneal stroma", "Corneal endothelium"], "correct": 2, "explanation": "The corneal stroma is built of regularly stacked collagen lamellae whose precise, uniform spacing makes the cornea transparent; disrupt that order and the cornea clouds. Bowman''s is an acellular condensation, the epithelium is a cell layer, and the endothelium is a single pump layer. Ordered stromal lamellae = corneal clarity."}'),
  ('7537d0ea-14','{"options": ["Pupil", "Cornea", "Crystalline lens", "Conjunctiva"], "correct": 0, "explanation": "The pupil is the central aperture of the iris through which light passes to the retina. The cornea is the clear front window, the lens focuses behind the iris, and the conjunctiva is a surface membrane. Pupil = the hole in the iris."}'),
  ('e4d5aa36-1f','{"options": ["6", "5", "8", "7"], "correct": 3, "explanation": "Humans normally have 7 cervical vertebrae (C1 to C7), a count shared by almost all mammals. The 8 refers to cervical spinal-nerve pairs (there are 8 because of the extra pair above C1), not vertebrae. 7 cervical vertebrae, 8 cervical nerves."}'),
  ('91c3da04-29','{"options": ["Blind spot of Mariotte", "Fovea centralis", "Optic disc", "Macula lutea"], "correct": 2, "explanation": "The optic disc (optic nerve head) is where the ganglion-cell axons leave the eye; it has no photoreceptors, so it is insensitive to light. VERIFY: the ''blind spot of Mariotte'' is the visual-field correlate of that same structure, so it is essentially a synonym and a defensible answer; the item keys on the optic disc as the anatomical exit. Optic disc = anatomical blind spot; blind spot of Mariotte = its field scotoma."}'),
  ('af392cb3-26','{"options": ["Aortic valve", "Pulmonic valve", "Tricuspid valve", "Mitral valve"], "correct": 2, "explanation": "The tricuspid valve guards the right atrioventricular orifice (between right atrium and right ventricle). The mitral (bicuspid) valve is the LEFT AV valve, and the aortic and pulmonic are the semilunar (outflow) valves. Right = tricuspid, Left = mitral (LAB RAT: Left Atrium Bicuspid, Right Atrium Tricuspid)."}'),
  ('05433992-2c','{"options": ["Optical axis", "Visual axis", "Pupillary axis", "Fixation axis"], "correct": 3, "explanation": "The fixation axis joins the object of regard (fixation point) to the eye''s center of rotation. The optical axis passes through the optical centers of the refracting surfaces, the visual axis joins the fixation point to the fovea through the nodal points, and the pupillary axis is perpendicular to the cornea through the pupil center. Fixation axis = object to center of rotation."}'),
  ('2b65b89e-5b','{"options": ["III", "II", "IV", "I"], "correct": 3, "explanation": "The pituitary (item I, option D) is the ''master gland'': directed by the hypothalamus, it secretes tropic hormones (TSH, ACTH, FSH/LH) that drive the thyroid, adrenals, and gonads. The thyroid (III), pineal (II), and thymus (IV) do not command other endocrine glands. Master gland = pituitary."}'),
  ('dfc76191-2o','{"options": ["III", "II", "I", "IV"], "correct": 1, "explanation": "The pineal gland (item II, option B) secretes melatonin, which regulates the sleep-wake (circadian) cycle in response to light and darkness. The pituitary, thyroid, and thymus do not make melatonin. Pineal = melatonin = body clock."}'),
  ('e86f27d8-53','{"options": ["II", "IV", "I", "III"], "correct": 3, "explanation": "The thyroid (item III, option D) releases T3/T4, which raise the basal metabolic rate, increasing oxygen consumption and heat production. The pineal, thymus, and pituitary do not directly set metabolic rate (the pituitary only signals the thyroid via TSH). Thyroid = metabolic thermostat."}'),
  ('28e7689c-4i','{"options": ["IV", "II", "III", "I"], "correct": 2, "explanation": "A fixator (item III, option C) contracts to steady/stabilize the origin (or a nearby joint) so the prime mover can act efficiently. The prime mover (I) produces the main movement, the antagonist (II) opposes it, and the synergist (IV) assists and refines it. Fixator = anchors the origin."}'),
  ('18417341-3p','{"options": ["II", "I", "III", "IV"], "correct": 0, "explanation": "The antagonist (item II, option A) opposes the prime mover, so the muscle opposing a flexor is its antagonist (the extensor). The prime mover does the action, the fixator stabilizes, and the synergist assists. Flexor''s opponent = its antagonist (extensor)."}'),
  ('e576324b-3z','{"options": ["II", "IV", "III", "I"], "correct": 3, "explanation": "The prime mover (agonist) (item I, option D) is the muscle chiefly responsible for producing a given movement. The antagonist opposes it, the fixator stabilizes, and the synergist assists. Main mover = prime mover/agonist."}'),
  ('bb83e607-13','{"options": ["humoral immunity", "cellular immunity", "active immunity", "passive immunity"], "correct": 0, "explanation": "Humoral immunity. B-lymphocytes make antibodies that circulate in the blood/humors, so B = humoral (antibody-mediated). Cellular immunity is the T-cell job; active/passive describe how immunity was acquired, not which cell. Hint: B for Bodies (antiBODIES) = humoral; T for Tissue/cell-mediated."}'),
  ('ceffe014-14','{"options": ["megaloblastic anemia", "aplastic anemia", "iron deficiency anemia", "pernicious anemia"], "correct": 2, "explanation": "Iron-deficiency anemia, the most common anemia worldwide and especially in menstruating women who lose iron with monthly blood loss. Megaloblastic = B12/folate, pernicious = B12 (intrinsic factor loss), aplastic = marrow failure. Hint: monthly blood loss drains iron, so think iron deficiency first."}'),
  ('c4f2d4e9-1t','{"options": ["neutrophils", "thrombocytes", "erythrocytes", "T-lymphocytes"], "correct": 1, "explanation": "Thrombocytes (platelets) plug vessel breaks and start clotting, so they prevent hemorrhage. Neutrophils fight infection, erythrocytes carry oxygen, T-cells do cellular immunity. Hint: THROMBO- = clot = stop bleeding."}'),
  ('f35ecbb0-1w','{"options": ["neutrophils", "thrombocytes", "erythrocytes", "T-lymphocytes"], "correct": 3, "explanation": "T-lymphocytes do NOT mature in myeloid (bone-marrow) tissue, they migrate to the THYMUS to mature (T = Thymus). All the others (neutrophils, thrombocytes, erythrocytes) both form and mature in the marrow. Hint: T-cell = Thymus-trained; only that step happens outside the marrow."}'),
  ('6300dddc-1k','{"options": ["plasma", "serum", "aqueous humor", "cerebrospinal fluid"], "correct": 0, "explanation": "Plasma, the liquid part of blood kept unclotted with an anticoagulant, so it still contains fibrinogen. Serum is the liquid left AFTER clotting (no fibrinogen). Hint: plasma = anticoagulated (clotting factors intact); serum = clotted (factors used up)."}'),
  ('1bab6c94-3g','{"options": ["type O", "type B", "type A", "none of the above"], "correct": 2, "explanation": "Type A is impossible. Mother is heterozygous B (genotype BO), father is O (OO). The father can only give O, and the mother gives B or O, so children are type B (BO) or type O (OO), never type A. Hint: cross BO x OO, no A allele exists in either parent, so no A child."}'),
  ('3b76bc17-1j','{"options": ["zinc", "calcium", "selenium", "iron"], "correct": 3, "explanation": "Iron sits at the center of each heme group and binds oxygen. Zinc, calcium, and selenium are not the heme metal. Hint: heme = iron core; that is why iron deficiency starves hemoglobin."}'),
  ('02f5c2f7-1a','{"options": ["methemoglobin", "carboxyhemoglobin", "oxyhemoglobin", "carbaminohemoglobin"], "correct": 3, "explanation": "Carbaminohemoglobin, hemoglobin bound to carbon DIOXIDE (CO2 attaches to the globin amino groups). Do not confuse with carboxyhemoglobin (CO, carbon MONOXIDE poisoning) or oxyhemoglobin (O2). Hint: carbAMINO = CO2 on the amino group; carbOXY = CO the poison."}'),
  ('2a57d84c-10','{"options": ["prevent hemorrhage", "carry oxygen throughout the body", "fight the infections", "building blocks of body"], "correct": 2, "explanation": "Leukocytes (white cells) fight infection. Erythrocytes carry oxygen, thrombocytes stop bleeding, and ''building blocks'' is not a blood-cell role. Hint: leuko = the body''s soldiers against infection."}'),
  ('2d6b1317-12','{"options": ["prevent hemorrhage", "carry oxygen throughout the body", "fight the infections", "building blocks of body"], "correct": 1, "explanation": "Erythrocytes (red cells) carry oxygen via hemoglobin throughout the body. Hint: RBC = the oxygen taxi."}'),
  ('5e5ccee7-12','{"options": ["prevent hemorrhage", "carry oxygen throughout the body", "fight the infections", "building blocks of body"], "correct": 0, "explanation": "Thrombocytes prevent hemorrhage (clotting). Same fact as Q3, just asked forward. Hint: platelets = the leak-pluggers."}'),
  ('d4135eb9-1l','{"options": ["myeloid tissue", "muscles", "liver", "heart"], "correct": 2, "explanation": "The liver stores the largest amount of iron (as ferritin). Myeloid tissue uses iron, muscle stores some (myoglobin), but the liver is the main reservoir. Hint: the liver is the body''s storage warehouse, iron included."}'),
  ('be0fa8e3-w','{"options": ["macrophage", "mast cells", "acidophils", "plasma cells"], "correct": 0, "explanation": "A monocyte that has left the blood and entered tissue becomes a macrophage (the big eater). Hint: monocyte in blood -> macrophage in tissue."}'),
  ('f6a8aa65-w','{"options": ["macrophage", "mast cells", "acidophils", "plasma cells"], "correct": 1, "explanation": "A basophil residing in tissue is a mast cell (both release histamine in allergy). Hint: basophil (blood) = mast cell (tissue), the histamine twins."}'),
  ('ed26624a-24','{"options": ["creatinine", "uric acid", "ammonia", "amino acids"], "correct": 3, "explanation": "Amino acids are NOT waste, the kidney reabsorbs them for reuse. Creatinine, uric acid, and ammonia are true nitrogenous wastes excreted in urine. Hint: amino acids are building blocks the body keeps, not trash it dumps."}'),
  ('1727c19a-i','{"options": ["network of capillaries", "network of venules", "network of arterioles", "none of the above"], "correct": 0, "explanation": "The glomerulus is a network (tuft) of CAPILLARIES where plasma is filtered. Not venules or arterioles, though afferent/efferent arterioles feed and drain it. Hint: filtration happens across capillary walls, so the glomerulus must be capillaries."}'),
  ('d339c95c-2d','{"options": ["Detrusor muscles", "rectus abdominis", "myometrium", "myocardium"], "correct": 0, "explanation": "The detrusor muscle (bladder wall) contracts to expel urine. Rectus abdominis is abdominal wall, myometrium is uterus, myocardium is heart. Hint: deTRUSOR = it thrusts urine out."}'),
  ('eae077fd-26','{"options": ["micturition", "defecation", "menstruation", "deglutition"], "correct": 0, "explanation": "Micturition = urination (emptying the bladder). Defecation is stool, menstruation is menses, deglutition is swallowing. Hint: micturition is the fancy word for peeing."}'),
  ('130d127b-19','{"options": ["acidic", "has small amount of albumin", "ultrafiltrate plasma", "sterile absence of microbes"], "correct": 1, "explanation": "Normal urine has NO albumin, protein in urine (albuminuria) signals disease. Urine IS acidic, an ultrafiltrate of plasma, and normally sterile. Hint: ''has albumin'' is the abnormal one, so it is the EXCEPT."}'),
  ('3fc81585-2g','{"options": ["urinary retention", "urinary incontinence", "suppression", "catheterization"], "correct": 1, "explanation": "Urinary incontinence, involuntary leakage from weak urethral sphincters, common in the elderly. Retention is the opposite (cannot empty); suppression is no urine formed. Hint: inCONTINENCE = cannot contain = leaks."}'),
  ('e3fa5831-24','{"options": ["urinary tract infection", "nephrotic syndrome", "benign prostatic hyperplasia", "acute glomerulonephritis"], "correct": 2, "explanation": "Benign prostatic hyperplasia (BPH), an enlarged prostate blocks outflow and causes urinary RETENTION in older men. UTI and glomerulonephritis do not typically cause retention. Hint: old man + cannot empty = enlarged prostate (BPH)."}'),
  ('0fdfa07f-1z','{"options": ["UTI", "nephrotic syndrome", "nephrolithiasis", "diabetes mellitus"], "correct": 3, "explanation": "Diabetes mellitus, high blood sugar (hyperglycemia) spills glucose into urine (glucosuria) once it exceeds the renal threshold. Hint: sugar in blood AND urine together = diabetes mellitus."}'),
  ('e760ffe6-1w','{"options": ["polyuria", "poliosis", "polyphagia", "polydypsia"], "correct": 1, "explanation": "Poliosis (whitening of hair/lashes) is NOT a diabetes sign. The classic 3 P''s are polyuria, polyphagia, and polydipsia. Hint: match the three P''s; poliosis is the odd word about hair, not urine/thirst/hunger."}'),
  ('7136c0ed-1r','{"options": ["urinary bladder", "ureters", "urethra", "kidneys"], "correct": 0, "explanation": "Terminal dysuria (pain at the END of voiding) localizes to the urinary bladder/trigone. Pain at the START (initial dysuria) points to the urethra. Hint: END of stream = bladder base; START of stream = urethra."}'),
  ('c06aea32-1m','{"options": ["pancreas", "gallbladder", "duodenum", "vermiform appendix"], "correct": 2, "explanation": "The duodenum is part of the GI tract itself, not an accessory organ. Accessory digestive organs (pancreas, gallbladder, appendix, salivary glands, liver) sit beside the tract and aid it. Hint: if food actually passes THROUGH it, it is the tract, not an accessory."}'),
  ('ad64e0ed-1q','{"options": ["peptidase", "chymotrypsin", "amylopsin", "pepsin"], "correct": 1, "explanation": "Chymotrypsin is a pancreatic protease (digests protein). Amylopsin digests carbohydrate, pepsin is a stomach protease (not pancreatic). Hint: trypsin/chymotrypsin = pancreas protein enzymes; -in ending on ''peps'' is gastric."}'),
  ('590c218b-2e','{"options": ["amylopsin", "cholecystokinin", "ptyalin", "chymotrypsin"], "correct": 0, "explanation": "Amylopsin = pancreatic amylase, which digests carbohydrate. Ptyalin is SALIVARY amylase (mouth), not pancreatic; chymotrypsin is protein. Hint: AMYLO = starch/carbs; ''opsin'' tag here means the pancreatic version."}'),
  ('60dc4892-w','{"options": ["Glisson’s capsule", "fascia of Gerota", "falciform ligament", "Bowman’s capsule"], "correct": 0, "explanation": "GLISSON''S CAPSULE is the fibrous capsule enclosing the LIVER. Gerota''s fascia = kidney (Q50); falciform ligament attaches liver to abdominal wall; Bowman''s capsule = renal glomerulus. Liver capsule = Glisson''s."}'),
  ('6af160dd-1m','{"options": ["insulin", "glucagon", "bile", "lipase"], "correct": 1, "explanation": "Alpha cells of the islets secrete glucagon (raises blood sugar). Beta cells make insulin. Hint: Alpha = glucAgon (A with A); Beta = insulin."}'),
  ('3b23478f-1l','{"options": ["insulin", "glucagon", "bile", "lipase"], "correct": 0, "explanation": "Beta cells secrete insulin (lowers blood sugar). Pair with Q29. Hint: Beta = insulin; alpha = glucagon."}'),
  ('dce4dac5-1e','{"options": ["Magen blasé", "cardia", "McBurney’s area", "rugae"], "correct": 0, "explanation": "The magenblase (''stomach bubble'') is the gas pocket in the fundus of the stomach. Cardia is the entry, rugae are the folds, McBurney''s is an appendix landmark. Hint: ''blase/blase'' = bubble = the gastric air cap in the fundus."}'),
  ('9d7c8800-1u','{"options": ["sialorrhea", "salivation", "anosmia", "xerostomia"], "correct": 3, "explanation": "Xerostomia = dry mouth from deficient saliva, which promotes caries and halitosis. Sialorrhea/salivation is excess saliva, anosmia is loss of smell. Hint: XERO = dry (as in xerophthalmia = dry eye), here dry mouth."}'),
  ('2028c87e-1h','{"options": ["tunica albuginea", "cremaster muscle", "corpora cavernosa", "frenulum"], "correct": 1, "explanation": "The cremaster muscle raises and lowers the testes (thermoregulation). Tunica albuginea is the testis capsule, corpora cavernosa is erectile tissue, frenulum is a fold. Hint: creMASTER lifts the testes up and down."}'),
  ('e5693993-1t','{"options": ["tunica albuginea", "corpus albican", "primary oocyte", "fertilization"], "correct": 1, "explanation": "Corpus albicans is the option intended for the emptied follicle scar. Strictly, the just-ruptured Graafian follicle first becomes the corpus LUTEUM, which only later degenerates into the white scar corpus albicans, but corpus luteum is not offered here, so pick corpus albican. Hint: sequence is follicle -> corpus luteum -> corpus albicans (white scar)."}'),
  ('5e34b11f-19','{"options": ["corpus of uterus", "proximal 2/3 of oviducts", "cervix", "vagina"], "correct": 0, "explanation": "Implantation normally occurs in the body (corpus) of the uterus, usually the upper posterior wall. The oviduct/cervix/vagina sites would be ectopic. Hint: normal implantation = uterine body; anywhere else = ectopic."}'),
  ('3208b60f-z','{"options": ["proximal 2/3 of ampulla", "fimbriae", "infundibulum", "cervix"], "correct": 0, "explanation": "Fertilization normally happens in the ampulla of the fallopian tube. Fimbriae/infundibulum catch the ovum, the cervix is far too low. Hint: sperm meets egg in the ampulla; implantation happens later in the uterus."}'),
  ('47d4a6f1-w','{"options": ["tubaligation", "circumcision", "vasectomy", "dilatation & curettage"], "correct": 2, "explanation": "Vasectomy (cutting the vas deferens) is male sterilization. Tubal ligation is female, circumcision removes foreskin, D&C is a uterine procedure. Hint: VASectomy = the VAS in the male."}'),
  ('f4611c7c-y','{"options": ["tubaligation", "circumcision", "vasectomy", "dilatation & curettage"], "correct": 0, "explanation": "Tubal ligation (tying the fallopian tubes) is female sterilization. Pair with Q37. Hint: tubes = female; vas = male."}'),
  ('05d3ee7c-1g','{"options": ["clitoris", "vagina", "mammary glands", "labia"], "correct": 0, "explanation": "The clitoris is the most sensitive (most nerve-dense) part of the female genitalia. Hint: it is the female homolog of the glans penis, so likewise the most sensitive spot."}'),
  ('8ad851e8-s','{"options": ["glans penis", "testes", "prostate gland", "seminal vesicles"], "correct": 2, "explanation": "The prostate gland is the male ''G-spot'' stimulated during coitus. Glans is most sensitive externally, but the prostate is the internal pleasure point. Hint: distinguish Q40 (prostate, internal) from Q41 (glans, most sensitive surface)."}'),
  ('f0a1f77b-1e','{"options": ["glans penis", "testes", "prostate gland", "seminal vesicles"], "correct": 0, "explanation": "The glans penis is the most sensitive part of the male organ (homolog of the clitoris). Hint: glans = male clitoris equivalent = most sensitive."}'),
  ('c093e01d-1f','{"options": ["enhances labor", "milk production", "development of alveoli", "ejection of colostrums"], "correct": 1, "explanation": "Prolactin drives milk PRODUCTION in the alveoli. Pair with Q42 (oxytocin = ejection). Hint: proLACTin = makes the lact (milk)."}'),
  ('d7cbdbe3-12','{"options": ["IgG", "IgA", "IgM", "IgE"], "correct": 1, "explanation": "IgA is the main antibody in colostrum/breast milk, giving the newborn passive mucosal immunity (secretory IgA). Hint: A for Alimentary/mucosa, colostrum is loaded with IgA."}'),
  ('515e3ce4-m','{"options": ["AV node", "SA node", "node of Ranvier", "node of Tawara"], "correct": 1, "explanation": "The SA (sinoatrial) node is the heart''s natural pacemaker, setting the rhythm. The AV node is the backup relay. Hint: SA node = the Spark that Starts each beat."}'),
  ('01fa591c-p','{"options": ["aorta", "cerebral arteries", "coronary arteries", "pulmonary arteries"], "correct": 2, "explanation": "The coronary arteries supply the heart muscle itself. The aorta carries blood out, pulmonary arteries go to the lungs. Hint: the heart feeds itself through its own crown of coronary vessels."}'),
  ('4d9c5293-1j','{"options": ["pleural sac", "cranial cavity", "peritoneal cavity", "mediastinal cavity"], "correct": 3, "explanation": "The heart sits in the mediastinum (mediastinal cavity), between the lungs. Pleural sacs hold the lungs, cranial holds brain, peritoneal holds abdominal organs. Hint: MEDIAstinum = the MIDDLE compartment of the chest where the heart lives."}'),
  ('185237ad-v','{"options": ["closure of the semilunar valves", "rushing of blood to already filled ventricles", "closure of AV valves", "all of the above"], "correct": 0, "explanation": "S2 (''dub'') is the closure of the semilunar (aortic and pulmonic) valves at the start of diastole. S1 (''lub'') is AV-valve closure. Hint: S1 AV valves, S2 semilunar; ''lub-dub'' = AV then semilunar."}'),
  ('d11821bb-1p','{"options": ["pulmonic valve", "mitral valve", "aortic valve", "tricuspid valve"], "correct": 1, "explanation": "The mitral (bicuspid) valve guards the LEFT atrium and LEFT ventricle. The tricuspid guards the right side. Hint: mitral = left (Mitral and Left both have an ''L'' sound to pair); tricuspid = right."}'),
  ('9c73acd5-1i','{"options": ["pulmonic valve", "mitral valve", "aortic valve", "tricuspid valve"], "correct": 1, "explanation": "The mitral valve has only 2 cusps (bicuspid), the odd one out; pulmonic, aortic, and tricuspid all have 3. Hint: mitral = bi (2) cusps; everything else is tri (3)."}'),
  ('6d3e8b47-2t','{"options": ["foramen ovale", "interatrial septum", "ductus arteriosus", "interventricular septum"], "correct": 0, "explanation": "The foramen ovale is the fetal opening that shunts blood from the right atrium to the left atrium (bypassing the lungs). Ductus arteriosus links pulmonary artery to aorta. Hint: the ''atria-to-atria'' hole is the foramen ovale; the ''artery'' shunt is the ductus arteriosus."}'),
  ('42e95c70-1i','{"options": ["chronotrophic property", "bathnotrophic property", "inotrophic property", "dromotrophic property"], "correct": 2, "explanation": "Inotropic = strength/force of myocardial contraction. Chronotropic = rate, dromotropic = conduction speed, bathmotropic = excitability. Hint: INOtropic = force (think ''in-force'')."}'),
  ('f44c3f02-15','{"options": ["(L) 2nd intercostal space, sternal border", "® 2nd intercostal space, sternal border", "5th intercostal space, (L) sternal border", "5th intercostal space, (L) mid-clavicular line"], "correct": 3, "explanation": "Mitral auscultation is at the 5th intercostal space, LEFT midclavicular line (the apex). The 2nd interspaces at the sternal border are aortic/pulmonic areas. Hint: mitral = apex beat = 5th ICS, left midclavicular line."}'),
  ('5f8c28a7-1w','{"options": ["heart rate", "force of myocardial contraction", "vasodilation", "vasoconstriction"], "correct": 2, "explanation": "Vasodilation LOWERS blood pressure, so it is the EXCEPT. Higher heart rate, stronger contraction, and vasoconstriction all RAISE BP. Hint: widen the pipes (dilate) = pressure drops."}'),
  ('3a12be97-1g','{"options": ["loss of elasticity of blood vessels", "too much sympathetic stimulation", "increase work load of heart", "vasodilatation"], "correct": 0, "explanation": "In the elderly, arteries stiffen (loss of elasticity), so BP rises (especially systolic). Hint: old, hardened pipes cannot cushion the pulse, so pressure climbs."}'),
  ('627e8212-1f','{"options": ["loss of elasticity of blood vessels", "too much sympathetic stimulation", "increase work load of heart", "vasodilatation"], "correct": 2, "explanation": "In obesity, the heart faces an increased workload (more tissue to perfuse, higher volume), raising BP. Options 55/57 take elasticity and sympathetic, so obesity = workload by elimination too. Hint: more body mass = more work for the pump = higher pressure."}'),
  ('e844538d-1r','{"options": ["loss of elasticity of blood vessels", "too much sympathetic stimulation", "increase work load of heart", "vasodilatation"], "correct": 1, "explanation": "Emotional stress fires the sympathetic nervous system, which raises heart rate and constricts vessels, driving BP up. Hint: stress = fight-or-flight = sympathetic surge."}'),
  ('0f0f288a-14','{"options": ["atrial depolarization", "atrial repolarization", "ventricular repolarization", "ventricular depolarization"], "correct": 3, "explanation": "The QRS complex = ventricular depolarization (the ventricles firing to contract). The P wave is atrial depolarization; the T wave is ventricular repolarization. Hint: big QRS = big ventricles depolarizing."}'),
  ('233d600b-y','{"options": ["arch of aorta", "vena cava", "pulmonary capillaries", "arterioles"], "correct": 2, "explanation": "Capillaries (pulmonary capillaries here) are the smallest vessels, one cell thick for exchange. Hint: capillaries are the microscopic exchange vessels, the smallest of all."}'),
  ('fbf05feb-1f','{"options": ["artery", "veins", "capillaries", "all of the above"], "correct": 0, "explanation": "Arteries carry blood AWAY from the heart (Away = Artery). Veins return it. Hint: A for Artery = A for Away."}'),
  ('59ae96db-16','{"options": ["ovarian artery", "pulmonary artery", "coronary artery", "ophthalmic artery"], "correct": 1, "explanation": "The pulmonary artery is the exception, it carries DE-oxygenated blood (heart to lungs). All other arteries carry oxygenated blood. Hint: the pulmonary artery breaks the ''arteries are oxygenated'' rule."}'),
  ('9784f4ac-15','{"options": ["superior vena cava", "portal vein", "pulmonary vein", "vena verticosa"], "correct": 2, "explanation": "The pulmonary vein is the exception, it carries OXYGENATED blood (lungs back to heart). Other veins carry deoxygenated blood. Hint: pulmonary vessels are the reversers, artery is low-O2, vein is high-O2."}'),
  ('5e3faa9b-17','{"options": ["methemoglobin", "carboxyhemoglobin", "oxyhemoglobin", "carbaminohemoglobin"], "correct": 0, "explanation": "Methemoglobin carries iron in the ferric (Fe3+) state, which cannot bind oxygen well. Normal hemoglobin holds ferrous (Fe2+). Hint: MET-Hb = ferric (Fe3+), the dysfunctional oxidized form."}'),
  ('39a3632e-19','{"options": ["macrophage", "lymphocytes", "thrombocytes", "erythrocytes"], "correct": 0, "explanation": "Among blood cellular elements, the MACROPHAGE/monocyte lineage is the LARGEST. Lymphocytes are mid-sized; thrombocytes (platelets) are smallest (Q23); erythrocytes are ~7 µm. Largest = macrophage/monocyte."}'),
  ('669ed896-15','{"options": ["type O", "type A", "type B", "type AB"], "correct": 3, "explanation": "Type AB is the universal RECIPIENT (no anti-A or anti-B antibodies, so it accepts all). Type O is the universal DONOR. Hint: AB takes All Blood in; O gives to all."}'),
  ('2d45fc7a-1u','{"options": ["Chyne-Stoke respiration", "orthopnea", "Kusmaull breathing", "eupnea"], "correct": 3, "explanation": "Eupnea, normal quiet breathing, is the safe ''normal'' answer for a neonate. Be aware the writer may intend Cheyne-Stokes, since brief periodic breathing is normal in newborns, so VERIFY the key. Hint: eupnea = normal breathing; Cheyne-Stokes periodic breathing can also be normal in infants and the very old."}'),
  ('9d822616-1i','{"options": ["congestive heart failure", "pulmonary tuberculosis", "bronchial asthma", "rheumatic heart diseas"], "correct": 0, "explanation": "Orthopnea (breathlessness lying flat, relieved by sitting up) points to congestive heart failure from pulmonary congestion. Hint: orthopnea = ''needs to sit up to breathe'' = failing heart backing up into the lungs."}'),
  ('1ddade18-1e','{"options": ["corniculate", "arythenoid", "thyroid", "cricoid"], "correct": 2, "explanation": "The thyroid cartilage forms the laryngeal prominence (Adam''s apple). Cricoid is the ring below; corniculate/arytenoid are small posterior cartilages. Hint: the thyroid cartilage is the shield you can feel as the Adam''s apple."}'),
  ('ab552a5c-y','{"options": ["corniculate", "arythenoid", "thyroid", "cricoid"], "correct": 2, "explanation": "The thyroid cartilage is also the LARGEST laryngeal cartilage. Hint: same shield cartilage, biggest and most palpable."}'),
  ('63787fd9-1h','{"options": ["lacrimal duct", "Eustachian tube", "tympanic membrane", "fronto-nasal duct"], "correct": 1, "explanation": "The Eustachian (auditory) tube connects the middle ear to the nasopharynx and equalizes pressure. Hint: Eustachian = ear-to-throat pressure valve (why ears pop)."}'),
  ('a3eb918e-1j','{"options": ["frontal sinus", "sphenoid sinus", "maxillary antrum", "mastoid antrum"], "correct": 3, "explanation": "The mastoid antrum is NOT a paranasal sinus (it is an air space of the temporal bone by the ear). The paranasal sinuses are frontal, ethmoid, sphenoid, and maxillary. Hint: paranasal = around the NOSE; the mastoid is around the EAR."}'),
  ('95cb9fdf-f','{"options": ["nostrils", "chonae", "choncha", "Keisselbach triangle"], "correct": 1, "explanation": "The choanae (posterior nares) are the openings from the nasal cavity into the nasopharynx. Nostrils are the anterior nares. Hint: choanae = the BACK doors of the nose."}'),
  ('c08389db-h','{"options": ["nostrils", "chonae", "choncha", "Keisselbach triangle"], "correct": 3, "explanation": "Kiesselbach''s triangle (Little''s area) on the anterior nasal septum is the classic site of epistaxis (nosebleed). Hint: anterior septum = Kiesselbach = where nosebleeds start."}'),
  ('cf885ae0-1e','{"options": ["inferior meatus", "middle meatus", "superior meatus", "acoustic meatus"], "correct": 0, "explanation": "The nasolacrimal duct drains tears into the INFERIOR meatus of the nose (why you get a runny nose when crying). Hint: tears drain LOW, into the inferior meatus."}'),
  ('9bc1578d-19','{"options": ["alveolar sac", "larynx", "alveolar duct", "trachea"], "correct": 0, "explanation": "The alveolar sacs (alveoli) are the most important respiratory part, where actual gas exchange occurs. The larynx/trachea only conduct air. Hint: exchange = alveoli; the rest are just plumbing."}'),
  ('19c8eca8-2i','{"options": ["tendon", "aponeurosis", "ligament", "mucous membrane"], "correct": 1, "explanation": "An aponeurosis is the flat, sheet-like tendon at the ends of flat muscles such as the extraocular muscles. A tendon is cord-like; a ligament joins bone to bone. Hint: flat muscle -> flat tendon = aponeurosis."}'),
  ('d6fae7d9-1d','{"options": ["ankle", "thigh", "wrist", "vertebrae"], "correct": 0, "explanation": "The largest tendon is the Achilles (calcaneal) tendon at the ankle. Hint: Achilles = ankle = the body''s biggest, most famous tendon."}'),
  ('a63e927e-1m','{"options": ["hardness", "resiliency", "rigidity", "opacity"], "correct": 1, "explanation": "Resiliency (springy flexibility) comes from the ORGANIC collagen matrix, not calcium, so it is the EXCEPT. Calcium gives hardness, rigidity, and radiographic opacity. Hint: calcium = hard/rigid/radio-opaque; collagen = the bendy resilience."}'),
  ('87fec760-1x','{"options": ["femur", "sternum", "humerus", "os coxae"], "correct": 1, "explanation": "Sternum is the classic answer (a prime red-marrow and marrow-aspiration site). Note the pelvis/os coxae actually holds a greater total marrow volume, so if the key says os coxae, that is why, VERIFY. Hint: sternum and iliac crest are the go-to marrow-tap sites in adults."}'),
  ('894b61f2-x','{"options": ["carpals", "vomer", "patella", "os coxae"], "correct": 2, "explanation": "The patella (kneecap) is the largest sesamoid bone (a bone embedded in a tendon). Hint: sesamoid = bone-in-a-tendon; the biggest is the kneecap."}'),
  ('e62da888-h','{"options": ["ileum", "ischium", "ilium", "pubis"], "correct": 0, "explanation": "''Ileum'' (spelled like the small-intestine segment) is NOT a pelvic bone. The pelvic bones are the ilium, ischium, and pubis. Hint: watch the spelling, ilium = pelvis, ileum = gut."}'),
  ('c13e2711-s','{"options": ["ileum", "ischium", "ilium", "pubis"], "correct": 1, "explanation": "The ischium is the strongest pelvic bone (it bears your weight when sitting). The ilium is the largest, but ischium is strongest. Hint: you sit on your ischial tuberosities, so the ischium is built strongest."}'),
  ('8672b0e4-14','{"options": ["Haversian canal", "lacuna", "Volkman’s canal", "Haversian lamellae"], "correct": 1, "explanation": "Osteocytes sit in spaces called lacunae within the bone matrix. Haversian canals carry vessels; canaliculi connect lacunae. Hint: lacuna = little lake where the bone cell rests."}'),
  ('62549721-y','{"options": ["decompose", "decalcified", "mummified", "petrified"], "correct": 1, "explanation": "Submerging bone in nitric acid (HNO3) DECALCIFIES it, dissolving the mineral and leaving flexible collagen. Hint: acid strips the calcium, so the bone becomes rubbery (decalcified)."}'),
  ('3b1fb746-1p','{"options": ["ligaments", "tendon", "cartilage", "fontanels"], "correct": 3, "explanation": "FONTANELS (and flat skull bones) form by INTRAMEMBRANOUS (membranous) ossification — direct bone formation in mesenchyme, no cartilage model. Ligaments/tendons/cartilage are not membranous-ossified bone. Flat bones/fontanels = membranous ossification."}'),
  ('7d2c2d67-1s','{"options": ["occipital fontanel", "bregmatic fontanel", "mastoid fontanel", "sphenoid fontanel"], "correct": 1, "explanation": "The bregmatic (anterior) fontanelle does NOT close early, it stays open until about 18 to 24 months. The posterior/occipital fontanelle closes by about 2 months. Hint: Anterior fontanelle = closes late (up to 2 years); posterior = closes early (~2 months)."}'),
  ('8fa3acdc-1l','{"options": ["occipital fontanel", "bregmatic fontanel", "mastoid fontanel", "sphenoid fontanel"], "correct": 1, "explanation": "The bregmatic (anterior) fontanelle lies at the bregma, the junction of the coronal and sagittal sutures. Hint: bregma = where the coronal meets the sagittal = anterior fontanelle."}'),
  ('1662807d-1g','{"options": ["C1", "C2", "C7", "C8"], "correct": 1, "explanation": "C2 (and C3 to C6) have BIFID (double-tipped) spinous processes. C1 (atlas) has no true spinous process, and C7 has a long non-bifid one. Hint: mid-cervical spines are forked (bifid); C7''s is single and long."}'),
  ('af0c1d4b-1r','{"options": ["C1", "C2", "C7", "C8"], "correct": 2, "explanation": "C7 is the vertebra prominens, with the most prominent (longest, palpable) spinous process at the base of the neck. Hint: C7 is the bump you feel when you bow your head."}'),
  ('6d2badf4-4','{"options": ["C1", "C2", "C7", "C8"], "correct": 1, "explanation": "The axis is C2 (its dens/odontoid peg lets the head rotate). C1 is the atlas. Hint: Atlas (C1) holds the head; Axis (C2) lets it turn."}'),
  ('d97a83e6-r','{"options": ["thoracic", "cervical", "sacral", "lumbar"], "correct": 2, "explanation": "The sacral vertebrae are fused (false/fixed), so they are NOT a ''true'' movable vertebral column. Cervical, thoracic, and lumbar are the true (movable) ones. Hint: true = movable; sacrum and coccyx are fused = false."}'),
  ('3a51c668-10','{"options": ["thoracic", "cervical", "sacral", "lumbar"], "correct": 3, "explanation": "The lumbar vertebrae are the largest of the true (movable) vertebrae, built to bear body weight. Hint: lumbar = lower back = biggest load = biggest vertebrae."}'),
  ('6fb19c44-1f','{"options": ["between lumbar vertebrae", "between cervical vertebra", "between thoracic vertebrae", "between sacral vertebra"], "correct": 0, "explanation": "The thickest intervertebral discs are in the LUMBAR region (they cushion the most weight, and allow the most flexion). Hint: biggest lumbar vertebrae carry the thickest cushions."}'),
  ('67adeb69-1e','{"options": ["cervical vertebra", "hyoid", "sternum", "clavicle"], "correct": 1, "explanation": "The hyoid is the only bone in the anterior neck, and it is unique in articulating with no other bone (slung by muscles/ligaments). Hint: hyoid = the free-floating throat bone."}'),
  ('a7fdbe8d-1u','{"options": ["body or antrum", "manubrium sterni", "xyphoid process", "gladiolus"], "correct": 1, "explanation": "The manubrium sterni (upper part of the sternum) is where the clavicle and first rib attach. The body (gladiolus) is the middle; xiphoid is the tip. Hint: manubrium = the ''handle'' at the top, where the collarbones clip on."}'),
  ('a957706d-1k','{"options": ["symphysis pubis", "symphysis menti", "diarthrosis", "sutures"], "correct": 1, "explanation": "The midline union of the left and right mandible = SYMPHYSIS MENTI (the chin symphysis). Symphysis pubis is the pelvic midline joint (Q20). Mandibular midline = symphysis menti."}'),
  ('b01abf3f-14','{"options": ["spondylosis", "lordosis", "scoliosis", "kyphosis"], "correct": 2, "explanation": "Scoliosis is a LATERAL (sideways) curvature of the spine. Kyphosis is a hunchback (posterior), lordosis is swayback (anterior). Hint: sColiosis = Sideways/C-shape curve."}'),
  ('6893be27-19','{"options": ["ulna", "fibula", "tibia", "radius"], "correct": 0, "explanation": "The ulna is the medial forearm bone (little-finger side, in anatomical position). The radius is lateral (thumb side). Hint: ulna = medial, on the pinky side; radius rotates on the thumb side."}'),
  ('29ed2772-18','{"options": ["ulna", "fibula", "tibia", "radius"], "correct": 2, "explanation": "The tibia (shinbone) is the anterior, medial, weight-bearing bone of the leg. The fibula is the thin lateral bone. Hint: you bark your shin (tibia) on the coffee table, it is the front leg bone."}'),
  ('7223e2fd-20','{"options": ["Ciliary muscle relaxation", "Retinal dopamine release modulation", "Increased depth of focus", "Corneal flattening leading to myopic defocus"], "correct": 1, "explanation": "Atropine''s myopia-control effect is now attributed to modulating retinal DOPAMINE (and scleral receptor) signaling, not to relaxing accommodation. Hint: atropine works on the retina/sclera (dopamine), not by paralyzing the ciliary muscle."}'),
  ('c4488074-2g','{"options": ["Progressive addition lenses + dual focus contact lenses", "Atropine + orthokeratology", "Outdoor activity + atropine", "Orthokeratology + patching"], "correct": 1, "explanation": "Atropine plus orthokeratology shows an additive myopia-control effect (the AOK combination). Hint: low-dose atropine + ortho-k together beat either alone."}'),
  ('305b9c9d-1a','{"options": ["sural", "deltoid", "peroneal", "popliteal"], "correct": 1, "explanation": "The DELTOID is a standard IM injection site (also gluteal/vastus lateralis). Sural/peroneal/popliteal are nerve/fossa structures, not muscle injection sites. Deltoid = common upper-arm IM site (small-volume vaccines)."}'),
  ('9a272606-1a','{"options": ["thymus", "pancreas", "tonsils", "spleen"], "correct": 1, "explanation": "NOT lymphoid = answer. Thymus, tonsils, and spleen are lymphoid organs; the PANCREAS is a digestive/endocrine gland, not lymphoid. Lymphoid system = thymus, nodes, spleen, tonsils, MALT."}'),
  ('3fb05f52-t','{"options": ["thymus", "pancreas", "tonsils", "spleen"], "correct": 3, "explanation": "The SPLEEN is the largest lymphoid organ (blood filtration, immune surveillance, RBC recycling). Thymus/tonsils are smaller; pancreas isn''t lymphoid (Q4). Largest lymphoid organ = spleen."}'),
  ('7c0973aa-p','{"options": ["skin", "pancreas", "liver", "stomach"], "correct": 0, "explanation": "The SKIN is the largest organ of the body (surface area + integumentary functions). Liver is the largest internal organ/gland (Q7). Largest organ overall = skin."}'),
  ('467dc384-u','{"options": ["skin", "pancreas", "liver", "stomach"], "correct": 1, "explanation": "The PANCREAS is the SECOND-largest gland (after the liver), with exocrine (digestive enzymes) and endocrine (insulin/glucagon) roles. Next-largest gland = pancreas."}'),
  ('47b7669a-11','{"options": ["pleura", "pericardium", "peritoneum", "parietal"], "correct": 0, "explanation": "The PLEURA is the serous membrane covering the LUNGS. Pericardium covers the heart; peritoneum lines the abdomen; ''parietal'' is just a layer name. Lungs → pleura."}'),
  ('b01843e4-16','{"options": ["decompose", "decalcified", "mummified", "petrified"], "correct": 1, "explanation": "Submerging bone in MINERAL ACID dissolves the calcium salts → DECALCIFIED bone (flexible, organic matrix remains). Burying in soil → decomposition (Q11). Acid removes mineral = decalcified."}'),
  ('bc85db63-1m','{"options": ["decompose", "decalcified", "mummified", "petrified"], "correct": 0, "explanation": "Burying bone in soil leads to DECOMPOSITION (bacterial breakdown of organic matrix). Acid → decalcified; heat/dryness → mummified; mineral replacement over ages → petrified. Soil burial = decompose."}'),
  ('647de362-1m','{"options": ["occipital fontanel", "bregmatic fontanel", "mastoid fontanel", "sphenoid fontanel"], "correct": 1, "explanation": "The BREGMATIC (anterior) fontanel closes/ossifies by ~18-24 months — the latest-closing fontanel. The posterior (occipital) closes by ~2-3 months. Anterior fontanel = latest to close (~18-24 mo)."}'),
  ('3607977e-1k','{"options": ["frontal", "sphenoid", "maxillary", "mastoid"], "correct": 3, "explanation": "NOT a paranasal (pneumatic, air-containing) bone = answer. The frontal, sphenoid, ethmoid, and maxillary bones house paranasal SINUSES; the MASTOID (temporal) contains air cells but is NOT a paranasal sinus bone. Paranasal sinuses: frontal, ethmoid, sphenoid, maxillary."}'),
  ('433936b1-1r','{"options": ["C1", "C2", "C7", "C8"], "correct": 2, "explanation": "C7 (vertebra prominens) has the most prominent, palpable spinous process at the neck base. C1 (atlas) has no body/spine; C2 is the axis. Most prominent cervical spinous process = C7."}'),
  ('dac0d4c8-1d','{"options": ["C1", "C2", "C7", "C8"], "correct": 1, "explanation": "C2 is the AXIS (its odontoid/dens forms the pivot the atlas rotates on). C1 = atlas. Axis = C2 (the ''pivot'')."}'),
  ('e57b3ca4-1h','{"options": ["thoracic", "cervical", "sacral", "lumbar"], "correct": 2, "explanation": "NOT a true vertebra = answer. True (movable) vertebrae are cervical, thoracic, lumbar; the SACRAL vertebrae are FUSED (false/fixed). True vertebrae = C/T/L; sacrum & coccyx = fused."}'),
  ('4961a475-1c','{"options": ["thoracic", "cervical", "sacral", "lumbar"], "correct": 3, "explanation": "The LUMBAR vertebrae are the largest of the true (movable) vertebrae — they bear the most body weight (large bodies). Lumbar = largest true vertebrae."}'),
  ('8f972242-1h','{"options": ["symphysis pubis", "symphysis menti", "diarthrosis", "sutures"], "correct": 0, "explanation": "The midline union of the left and right pubic bones = SYMPHYSIS PUBIS (a cartilaginous joint). Symphysis menti is the chin. Pubic midline = symphysis pubis."}'),
  ('8f56c80a-x','{"options": ["parietal", "lacrimal", "sphenoid", "zygomatic"], "correct": 2, "explanation": "NOT paired = answer. Parietal, lacrimal, and zygomatic skull bones are PAIRED (left + right); the SPHENOID is UNPAIRED (single midline bone). Unpaired skull bones: frontal*, ethmoid, sphenoid, occipital, vomer, mandible."}'),
  ('f3cc38ad-1a','{"options": ["macrophage", "lymphocytes", "thrombocytes", "erythrocytes"], "correct": 2, "explanation": "THROMBOCYTES (platelets) are the SMALLEST cellular elements of blood (cell fragments ~2-3 µm). Macrophage = largest (Q22). Smallest = platelets."}'),
  ('12ede960-u','{"options": ["tibia", "femur", "humerus", "skull"], "correct": 1, "explanation": "The FEMUR (thigh bone) is the largest/longest bone in the body. Tibia/humerus are smaller long bones. Largest bone = femur."}'),
  ('ca028cd1-v','{"options": ["incus", "cuneiform", "patella", "stapes"], "correct": 3, "explanation": "The STAPES (in the middle ear) is the smallest bone in the body. Incus/cuneiform/patella are larger. Smallest bone = stapes (one of the three ossicles)."}'),
  ('0f7bcabd-1n','{"options": ["rectum", "cecum", "appendix", "jejunum"], "correct": 2, "explanation": "The APPENDIX (vermiform) is an ACCESSORY/vestigial structure off the cecum — not part of the main digestive tract function. Rectum/cecum/jejunum are true GI tract segments. Accessory/non-essential = appendix."}'),
  ('9bcce8b8-1b','{"options": ["stomach", "colon", "pancreas", "spleen"], "correct": 3, "explanation": "NOT a digestive organ = answer. Stomach, colon, and pancreas (enzymes) aid digestion; the SPLEEN is a lymphoid/hematologic organ, not digestive. Spleen = immune/blood, not GI."}'),
  ('55283007-12','{"options": ["Haversian system", "osteocytes", "Haversian lamellae", "lacuna"], "correct": 0, "explanation": "The HAVERSIAN SYSTEM (osteon) is the structural/functional UNIT of compact bone (central canal + concentric lamellae + osteocytes in lacunae). Osteocytes/lamellae/lacunae are components within it. Bone unit = osteon (Haversian system)."}'),
  ('7a34819a-u','{"options": ["nephrons", "neurons", "glomerulus", "lobules"], "correct": 0, "explanation": "The NEPHRON is the functional unit of the kidney (glomerulus + tubules). Neurons are nervous; glomerulus/lobules are parts. Kidney unit = nephron."}'),
  ('039b5444-1w','{"options": ["tendon", "ligaments", "aponeurosis", "serous membrane"], "correct": 2, "explanation": "An APONEUROSIS is the flat, sheet-like connective-tissue attachment of FLAT muscles (e.g., abdominal). Tendons are cord-like; ligaments join bone-to-bone. Flat-muscle attachment = aponeurosis."}'),
  ('ca9132b3-w','{"options": ["latissimus dorsi", "deltoid muscle", "Mueller’s muscle", "sartorius"], "correct": 3, "explanation": "The SARTORIUS (crossing the thigh from hip to medial knee) is the longest muscle in the body. Latissimus/deltoid are broad/large but not longest. Longest muscle = sartorius."}'),
  ('d4387780-18','{"options": ["sympathetic nervous system", "parasympathetic nervous system", "somatic nervous system", "central nervous system"], "correct": 1, "explanation": "The PARASYMPATHETIC nervous system is the ''cholinergic'' system — its pre- AND post-ganglionic transmission uses ACETYLCHOLINE. (Sympathetic post-ganglionic is mostly noradrenergic.) Parasympathetic = cholinergic. Cross-link: pupillary constriction (cholinergic, CN III)."}'),
  ('20497343-11','{"options": ["macrophages", "B-lymphocytes", "T-lymphocytes", "mast cells"], "correct": 1, "explanation": "B-LYMPHOCYTES mediate HUMORAL immunity (antibody-mediated, via plasma cells). T-cells mediate cell-mediated immunity. Humoral = B cells (antibodies)."}'),
  ('6fb52eeb-t','{"options": ["macrophages", "B-lymphocytes", "T-lymphocytes", "mast cells"], "correct": 1, "explanation": "B-LYMPHOCYTES (→ plasma cells) produce ANTIBODIES (immunoglobulins). T-cells regulate/kill; macrophages phagocytose; mast cells release histamine. Antibody factory = B cell/plasma cell."}'),
  ('752be812-1l','{"options": ["macrophages", "B-lymphocytes", "T-lymphocytes", "mast cells"], "correct": 3, "explanation": "MAST CELLS (and basophils) release HISTAMINE in allergic/Type-I hypersensitivity (IgE-triggered), causing the allergic response (e.g., allergic conjunctivitis). Histamine release = mast cells. Cross-link: IgE-mediated allergy (Q70)."}'),
  ('b495b0d7-1t','{"options": ["trachea", "nasopharynx", "larynx", "oropharynx"], "correct": 0, "explanation": "NOT upper respiratory = answer. The upper tract = nose, naso/oro-pharynx, larynx; the TRACHEA is the LOWER respiratory tract. URT ends at the larynx; trachea/bronchi/lungs = LRT."}'),
  ('2bd5b74a-1t','{"options": ["kidneys", "urinary bladder", "ureters", "renal pelvis"], "correct": 1, "explanation": "NOT upper urinary = answer. Upper urinary tract = kidneys, renal pelvis, ureters; the URINARY BLADDER (and urethra) is the LOWER tract. Bladder = lower urinary tract."}'),
  ('c75ab4ff-31','{"options": ["spleen", "pancreas", "liver and gallbladder", "vermiform appendix"], "correct": 2, "explanation": "The LIVER and GALLBLADDER occupy the RIGHT UPPER QUADRANT specifically. Spleen = LUQ; pancreas = central; appendix = RLQ. RUQ-specific = liver/gallbladder."}'),
  ('77cb7b64-31','{"options": ["spleen", "pancreas", "liver and gallbladder", "vermiform appendix"], "correct": 3, "explanation": "The VERMIFORM APPENDIX sits specifically in the RIGHT LOWER QUADRANT (McBurney''s point region, Q47). Spleen LUQ, liver RUQ, pancreas central. RLQ-specific = appendix."}'),
  ('183a114d-1f','{"options": ["coronal", "transverse", "sagittal", "midsagittal"], "correct": 0, "explanation": "The CORONAL (frontal) plane divides the body into VENTRAL (anterior) and DORSAL (posterior) halves. Transverse = superior/inferior; sagittal = left/right. Front-back split = coronal."}'),
  ('0db23bba-22','{"options": ["palm facing dorsally", "thumb pointing away from median plane", "face facing anteriorly", "upper extremities dangling on sides"], "correct": 0, "explanation": "NOT normal anatomic position = answer. Anatomic position has palms facing ANTERIORLY (forward), not dorsally; thumbs point away from midline, face forward, arms at sides. PALM FACING DORSALLY breaks the position. Anatomic position = palms forward."}'),
  ('e31f827e-1d','{"options": ["coronal", "transverse", "sagittal", "midsagittal"], "correct": 1, "explanation": "A vertical line/plane PERPENDICULAR to the sagittal plane is the TRANSVERSE? — actually the plane perpendicular to sagittal and vertical is the CORONAL... [the keyed ''transverse'' refers to the perpendicular reference]; the coronal plane is vertical and perpendicular to the sagittal. Anchor: sagittal (L/R) ⟂ coronal (front/back); transverse is horizontal."}'),
  ('632592fc-1c','{"options": ["adrenal glands", "pineal gland", "pancreas", "parathyroid glands"], "correct": 1, "explanation": "NOT an endocrine gland = answer... the PINEAL gland IS endocrine (melatonin), as are adrenal, pancreas (islets), parathyroid — so the keyed ''pineal'' as non-endocrine is questionable; verify. [All four listed are endocrine; if forced, the intended ''exception'' may target the gland with a non-hormonal primary role.] Note: pineal = melatonin (endocrine)."}'),
  ('b038ae64-1q','{"options": ["McBurney’s point", "taenia coli", "appendices epiploica", "ligament of Treitz"], "correct": 0, "explanation": "McBURNEY''S POINT (1/3 from the ASIS to the umbilicus, RLQ) marks the appendix/incision site in appendectomy. Taenia coli/epiploica are colon features; ligament of Treitz is the duodenojejunal flexure. Appendectomy landmark = McBurney''s point."}'),
  ('f4acdb97-k','{"options": ["neprolithiasis", "cholelithiasis", "fecaliths", "urolithiasis"], "correct": 1, "explanation": "Stone in the GALLBLADDER = CHOLELITHIASIS (chole = bile/gall). Nephro/uro-lithiasis = kidney/urinary; fecaliths = stool. Gallstone = cholelithiasis."}'),
  ('fdfd4eef-y','{"options": ["Glisson’s capsule", "fascia of Gerota", "falciform ligament", "Bowman’s capsule"], "correct": 1, "explanation": "GEROTA''S FASCIA (renal fascia) encloses the KIDNEYS (and perinephric fat). Glisson = liver; Bowman = glomerulus; falciform = liver attachment. Kidney capsule/fascia = Gerota''s."}'),
  ('b5cfca5b-k','{"options": ["neprolithiasis", "cholelithiasis", "fecaliths", "hydronephrosis"], "correct": 0, "explanation": "Stone in the KIDNEY = NEPHROLITHIASIS (nephro = kidney). Cholelithiasis = gallbladder; fecaliths = stool; hydronephrosis = urine backup/swelling. Kidney stone = nephrolithiasis."}'),
  ('be3e18b9-1c','{"options": ["tactile", "auditory", "Dazzle reflex", "orbicularis"], "correct": 1, "explanation": "Blink triggered by a LOUD SOUND = AUDITORY (cochleo-palpebral) reflex blink. Tactile = lash/cornea touch; dazzle = bright light. Loud sound → auditory blink reflex."}'),
  ('4eb7a904-1h','{"options": ["tactile", "auditory", "Dazzle reflex", "orbicularis"], "correct": 0, "explanation": "Blink from touching the EYELASHES/cornea = TACTILE (corneal/lash) reflex blink. Auditory = sound; dazzle = light. Touch → tactile blink (corneal reflex, CN V→VII)."}'),
  ('5bfef7b6-19','{"options": ["orbicularis oculi", "Mueller’s muscles", "LPS", "frontalis muscles"], "correct": 1, "explanation": "MÜLLER''S muscle (superior tarsal muscle) is the SMOOTH (sympathetically innervated) lid muscle that adds ~2 mm of lid elevation. Orbicularis (closes) and LPS (elevates) are SKELETAL; frontalis is facial. Smooth lid muscle = Müller''s. Cross-link: its loss = ptosis in Horner''s."}'),
  ('dd3cf1f7-x','{"options": ["tarsal plate", "undersurface of LPS", "inferior rectus", "annulus of Zinn"], "correct": 1, "explanation": "The upper Müller''s muscle ORIGINATES from the UNDERSURFACE of the LEVATOR (LPS) and inserts on the upper tarsal plate. Sympathetic innervation. Origin = undersurface of LPS; insertion = superior tarsus."}'),
  ('423cc7e3-2f','{"options": ["space of Schwalbe", "node of Ranvier", "pleural sac", "cul-de-sac"], "correct": 3, "explanation": "The CUL-DE-SAC (conjunctival fornix sac, ~2 mm deep) between bulbar and palpebral conjunctiva is where tears pool/pass. Schwalbe''s space/node of Ranvier/pleural sac are unrelated. Tear-holding sac = conjunctival cul-de-sac/fornix."}'),
  ('e64f322d-1f','{"options": ["Schirmer’s test", "TBUT", "fluorescein dye test", "cocaine test"], "correct": 2, "explanation": "Lacrimal drainage PATENCY is checked with the FLUORESCEIN DYE (disappearance / Jones) test — dye instilled, then assess clearance into the nose. Schirmer = tear quantity; TBUT = quality; cocaine = (Horner''s). Patency = dye test."}'),
  ('09fd7d14-1p','{"options": ["IgE", "IgA", "IgG", "IgM"], "correct": 1, "explanation": "Secretory IgA is the major tear antibody providing antibacterial/mucosal defense. IgE = allergy; IgG/IgM are minor in tears. Tear immune defense = secretory IgA."}'),
  ('b8438cdc-14','{"options": ["main lacrimal glands", "Meibomian glands", "accessory lacrimal glands", "goblet cells"], "correct": 0, "explanation": "REFLEX tearing stimulates the MAIN LACRIMAL gland (large aqueous output via CN VII parasympathetics). Accessory glands (Krause/Wolfring) handle BASAL secretion (Q62). Reflex = main lacrimal gland."}'),
  ('1380a7c1-14','{"options": ["main lacrimal glands", "Meibomian glands", "accessory lacrimal glands", "goblet cells"], "correct": 2, "explanation": "BASAL (basic) tear secretion to keep the eye wet comes from the ACCESSORY lacrimal glands (Krause and Wolfring). Main gland = reflex; Meibomian = lipid; goblet = mucin. Basal aqueous = accessory glands."}'),
  ('630c2a73-1m','{"options": ["thinking the saddest moment of life", "after drinking very hot coffee or tea", "prolong exposure to bright light", "while sleeping"], "correct": 3, "explanation": "Does NOT stimulate reflex tearing = answer. Emotion, hot drinks/irritants, and bright light evoke reflex tears; during SLEEP reflex secretion is shut OFF (eyes closed, low secretion). Sleep = no reflex tearing."}'),
  ('e2d072e9-1k','{"options": ["cholesterol", "ester wax", "triglycerides", "free fatty acids"], "correct": 1, "explanation": "The tear LIPID (oily) layer''s main component is WAX (ester) and cholesterol esters from the Meibomian glands (with some triglycerides/free fatty acids). Predominant = wax esters. Lipid layer retards evaporation."}'),
  ('665e5ec5-m','{"options": ["slightly acidic", "slightly alkaline", "neutral", "none of the above"], "correct": 1, "explanation": "Normal tear pH is slightly ALKALINE (~7.4, range ~7.0-7.4). Not acidic or strictly neutral. Tear pH ≈ 7.4 (slightly alkaline). Relevant to drug formulation/comfort."}'),
  ('c9692439-1w','{"options": ["puncta lacrimalis", "lacrimal sac", "lacrimal canaliculi", "nasolacrimal duct"], "correct": 3, "explanation": "The NASOLACRIMAL DUCT is the LAST part of the drainage passage to canalize/open in development (hence congenital NLD obstruction in infants from a persistent membrane of Hasner). Puncta/canaliculi/sac open earlier. Last to open = NLD."}'),
  ('a32c8dad-1b','{"options": ["tarsal glands", "goblet cells of conjunctiva", "lacrimal glands", "ciliary process"], "correct": 2, "explanation": "The AQUEOUS (middle) layer of the tear film is produced by the LACRIMAL glands (main + accessory). Tarsal/Meibomian = lipid; goblet = mucin; ciliary process = aqueous humor (not tears). Aqueous tear layer = lacrimal glands."}'),
  ('0cae8c08-19','{"options": ["tarsal glands", "goblet cells of conjunctiva", "lacrimal glands", "ciliary process"], "correct": 0, "explanation": "The LIPID (outer) tear layer is produced by the TARSAL (Meibomian) glands. Goblet = mucin; lacrimal = aqueous. Lipid layer = Meibomian/tarsal glands (Q64)."}'),
  ('d220b43c-19','{"options": ["tarsal glands", "goblet cells of conjunctiva", "lacrimal glands", "ciliary process"], "correct": 1, "explanation": "The MUCIN (inner) tear layer is produced by the conjunctival GOBLET CELLS, which wet the hydrophobic corneal epithelium so the aqueous spreads. Tarsal = lipid; lacrimal = aqueous. Mucin = goblet cells."}'),
  ('39cb80e3-1m','{"options": ["IgD", "IgE", "IgM", "IgG"], "correct": 1, "explanation": "IgE predominates in ALLERGIC conjunctivitis (Type-I hypersensitivity), binding mast cells to trigger histamine release (Q37). IgG/IgM/IgD differ. Allergy = IgE. Cross-link: mast cells + histamine."}'),
  ('24e298dd-2c','{"options": ["neural crest", "mesoderm", "surface ectoderm", "endoderm"], "correct": 3, "explanation": "EXCEPT. The visual apparatus arises from NEUROECTODERM (neural crest), MESODERM, and SURFACE ECTODERM — NOT from ENDODERM. Endoderm forms gut/respiratory linings, not eye. Eye germ layers: neuro-ectoderm, surface ectoderm, neural crest, mesoderm (no endoderm)."}'),
  ('45415d52-1z','{"options": ["bulbar conjunctiva", "fornix conjunctiva", "palpebral conjunctiva", "puncta lacrimalis"], "correct": 2, "explanation": "The PALPEBRAL conjunctiva (tightly adherent to the tarsus) does NOT swell (chemose) much with inflammation, unlike the loosely attached bulbar/fornix conjunctiva. Tight adhesion to tarsus = no chemosis. Palpebral = non-swelling."}'),
  ('d06c7dda-1q','{"options": ["bulbar conjunctiva", "fornix conjunctiva", "palpebral conjunctiva", "puncta lacrimalis"], "correct": 1, "explanation": "The FORNIX conjunctiva (loosest attachment) is the FIRST to swell in conjunctivitis (chemosis starts where tissue is loose). Bulbar swells too; palpebral resists (Q72). First chemosis = fornix."}'),
  ('d72bd141-s','{"options": ["tarsus", "LPS", "conjunctiva", "skin and subcutaneous tissue"], "correct": 0, "explanation": "The TARSUS (tarsal plate) is the dense FIBROUS layer giving the eyelid its shape/rigidity. LPS = muscle; conjunctiva = mucosa; skin = outer. Lid fibrous skeleton = tarsus."}'),
  ('af3d6d90-10','{"options": ["tarsus", "LPS", "palpebral conjunctiva", "bulbar conjunctiva"], "correct": 2, "explanation": "The PALPEBRAL CONJUNCTIVA is the MUCOUS-membrane (innermost) layer of the eyelid (lines the inner lid against the globe). Tarsus = fibrous; LPS = muscle. Lid mucosa = palpebral conjunctiva."}'),
  ('5ab3071d-1f','{"options": ["lateral fornix", "superior fornix", "medial fornix", "inferior fornix"], "correct": 0, "explanation": "The LATERAL fornix is the DEEPEST/farthest from the limbus (~14 mm). Medial is shallowest (caruncle/plica). Deepest fornix = lateral. (Useful for foreign-body sweeping and fitting.)"}'),
  ('bbc712b6-1e','{"options": ["lateral fornix", "superior fornix", "medial fornix", "inferior fornix"], "correct": 1, "explanation": "Among the fornices, the keyed ''nearest the limbus'' is the SUPERIOR fornix per the source — though clinically the MEDIAL fornix is the shallowest; depths run lateral (deepest) > superior > inferior > medial (shallowest). [Verify intended answer; the lateral fornix is reliably the deepest/farthest.] Anchor: lateral deepest, medial shallowest."}'),
  ('eeb8e7e2-20','{"options": ["muscle sheath", "ligament of Lockwood", "muscle cone", "check ligament"], "correct": 2, "explanation": "The four recti uniting near the annulus of Zinn form the MUSCLE CONE (the retrobulbar surgical/anesthetic space). Muscle sheath/check ligaments/Lockwood are other fascial structures. Recti at the apex = muscle cone."}'),
  ('063484d5-2j','{"options": ["muscle sheath", "ligament of Lockwood", "muscle cone", "check ligament"], "correct": 1, "explanation": "The LIGAMENT OF LOCKWOOD is the hammock-like thickening from the sheaths/fascia of the INFERIOR rectus and inferior oblique that SLINGS/supports the globe inferiorly. Check ligaments limit muscle excursion. Inferior support sling = Lockwood''s ligament."}'),
  ('1ec4625a-1t','{"options": ["ligament of Lockwood", "lateral palpebral ligament", "check ligament", "ligament of Weiger"], "correct": 3, "explanation": "EXCEPT (not attached to the lateral orbital tubercle of Whitnall). The lateral palpebral ligament, lateral check ligament, and Lockwood''s ligament attach at the lateral orbital tubercle; the ''ligament of Weiger'' (hyaloideocapsular, lens-vitreous) is INTRAOCULAR, not orbital. Weiger = lens/vitreous, not the orbit."}'),
  ('e7493f26-1m','{"options": ["facial nerve", "oculomotor nerve", "trochlear nerve", "abducens nerve"], "correct": 0, "explanation": "Does NOT pass the superior orbital fissure = answer. The SOF transmits CN III, IV, VI, and V1 branches; the FACIAL nerve (CN VII) does NOT pass through it (it exits the skull elsewhere). SOF: III, IV, V1, VI (not VII)."}'),
  ('43ef3c1f-z','{"options": ["orbital margins", "superior orbital fissure", "optic foramen", "inferior orbital fissure"], "correct": 0, "explanation": "The BASE of the orbit corresponds to the ORBITAL MARGINS (the anterior rim). The apex = optic foramen (Q85). Orbital base = the rim/margins."}'),
  ('abc57a40-1v','{"options": ["frontal bone", "zygomatic bone", "lacrimal bone", "ethmoid bone"], "correct": 1, "explanation": "The ZYGOMATIC bone is the paired, quadrilateral orbital bone on the TEMPORAL (lateral) side (forms the lateral wall/rim, the ''cheekbone''). Frontal = roof; lacrimal/ethmoid = medial. Temporal/lateral orbital bone = zygomatic."}'),
  ('f03dcc0c-25','{"options": ["frontal bone", "zygomatic bone", "lacrimal bone", "ethmoid bone"], "correct": 3, "explanation": "The ETHMOID is the cuboidal, unpaired orbital bone along the NASAL (medial) side (forms most of the medial wall via the lamina papyracea). Zygomatic = lateral; lacrimal = small medial. Medial/nasal unpaired orbital bone = ethmoid."}'),
  ('4dd18ac4-1d','{"options": ["orbital margins", "superior orbital fissure", "optic foramen", "inferior orbital fissure"], "correct": 1, "explanation": "The SUPERIOR ORBITAL FISSURE lies between the GREATER and LESSER wings of the sphenoid, dividing them (and transmitting III, IV, V1, VI). Optic foramen is within the lesser wing. SOF = the greater/lesser wing gap."}'),
  ('9ba0430b-12','{"options": ["trochlear nerve", "oculomotor nerve", "trigeminal nerve", "abducens nerve"], "correct": 2, "explanation": "NOT motor to the orbit = answer. CN III (oculomotor), IV (trochlear), and VI (abducens) are MOTOR to the EOMs; the TRIGEMINAL (V) is SENSORY (ophthalmic branch) — not ocular-motor. Ocular motor nerves = III, IV, VI; V = sensory."}'),
  ('986ed9df-1d','{"options": ["frontal nerve", "nasociliary nerve", "lacrimal nerve", "infraorbital nerve"], "correct": 3, "explanation": "The INFRAORBITAL nerve (V2 branch) passes through the INFERIOR orbital fissure (and infraorbital groove/canal). Frontal/nasociliary/lacrimal nerves run via the SUPERIOR orbital fissure. Inferior orbital fissure = infraorbital (V2)."}'),
  ('99d758f7-17','{"options": ["trochea", "maxillary sinus", "orbital tubercle", "fossa for lacrimal sac"], "correct": 1, "explanation": "The MAXILLARY SINUS sits beneath the orbital FLOOR (the floor is the sinus roof) — relevant to blow-out fractures herniating orbital contents into the antrum. Trochlea (superonasal), tubercle (lateral), lacrimal fossa (medial) are elsewhere. Orbital floor = over the maxillary sinus."}'),
  ('27817c70-1a','{"options": ["sphenoid", "frontal", "ethmoid", "lacrimal"], "correct": 0, "explanation": "The SPHENOID bone encloses the ''master gland'' — the PITUITARY sits in the sella turcica of the sphenoid. Hence trans-sphenoidal pituitary surgery. Master gland (pituitary) = within the sphenoid."}'),
  ('8bb0dcdf-1m','{"options": ["Green tint,", "Yellow tint,", "Gray tint,", "Polaroid lenses ,"], "correct": 1, "explanation": "EXCEPT. Photophobia is eased by gray/neutral tints, polarized (Polaroid) lenses (cut glare), and certain tints — but YELLOW tint INCREASES light transmission/contrast (it blocks blue, used for low light), so it does NOT relieve photophobia. Gray = uniform dimming; yellow = the odd one out for glare."}'),
  ('d5890ab3-3u','{"options": ["Decompensated exophora at far, perform vision training to increase positive fusional reserve", "Decompensated exophora at far, perform vision training to increase negative fusional reserve", "Compensated exophoria, no need for prismatic correction", "Compensated exophoria"], "correct": 0, "explanation": "Far findings: 12Δ EXOphoria with low base-out (convergence) reserves (16/12, 17/14 break/recovery are low relative to a 12 exo) = DECOMPENSATED exophoria at distance → vision training to build POSITIVE fusional reserve (convergence) to meet Sheard''s. Exo needs MORE convergence reserve; VT increases PFV. Manage by training the deficient (positive) reserve."}'),
  ('d53c0ae8-1g','{"options": ["1.75D", "3.00D", "2.50D", "3.50D"], "correct": 2, "explanation": "The maximum normal LAG measured on the Binocular Cross-Cylinder (BCC, OEP #14B near) is about +2.50 D — values beyond suggest accommodative insufficiency. The BCC measures the accommodative posture (lag) under binocular conditions. Reference value for the near add work-up."}'),
  ('7b3437ec-5c','{"options": ["Myopic", "Hyperopic", "Emmetropic", "Astigmatism"], "correct": 3, "explanation": "With both eyes showing significant cylinder (compound myopic astigmatism) and corneal astigmatism on K, the refractive condition is astigmatism."}'),
  ('c76d2be9-2a','{"options": ["Paralysis of Accommodation", "Spasm of Accommodation", "Lead of Accommodation", "Convergence excess"], "correct": 1, "explanation": "If the autorefractor reads more minus than the subjective refraction, that instrument over-minus reflects a spasm of accommodation."}'),
  ('32d23a32-15','{"options": ["Tangent Screen’.", "Perimeter arc’.", "Stereo butterfly’.", "Worth four dot test’."], "correct": 0, "explanation": "The TANGENT SCREEN (Bjerrum) uses colored test objects/pigment targets on a black screen to plot the central field. Perimeter arcs use lights; stereo-butterfly and W4D test binocularity. Tangent screen = pigment/colored-target central field test."}'),
  ('213e961e-21','{"options": ["Increased aberrations.", "Uncooperative or inattentive during static retinoscopy.", "Decreased depth of focus.", "Added inconvenience for patient, parent and doctor."], "correct": 3, "explanation": "EXCEPT (not a disadvantage of cycloplegic retinoscopy). Real downsides: increased aberrations and decreased depth of focus (dilated pupil), plus possible cooperation issues. ''Added inconvenience for patient/parent/doctor'' is a practical nuisance, not an optical disadvantage of the technique itself — the keyed exception. Separate optical drawbacks from logistical ones."}'),
  ('c999fe15-46','{"options": ["accommodation test", "convergence test", "phoria test", "a & b"], "correct": 0, "explanation": "Varying the accommodative stimulus with plus/minus lenses while convergence is held constant is the basis of accommodative (gradient/facility) testing."}'),
  ('56101063-3y','{"options": ["135o", "120o", "045o", "150o"], "correct": 0, "explanation": "With the 10 to 11 o''clock line clearest on the clock dial, the correcting minus-cylinder axis lies along that meridian, about 135 degrees. VERIFY: clock-dial-to-axis reading (rule of 30) is easy to mis-apply for an ''in-between'' line, so confirm; 135 fits the upper-left line orientation."}'),
  ('781e7c89-2l','{"options": ["MA", "CHA", "CMA", "SHA"], "correct": 1, "explanation": "Both principal powers of +1.50 sph = -0.50 cyl x 45 are plus (+1.50 and +1.00), so both foci sit behind the retina: compound hyperopic astigmatism (CHA), oblique axis."}'),
  ('ac1f9f70-3a','{"options": ["the original blackest line remains the blackest", "the original blurred line becomes the blackest", "the original blurred line does not get blacker", "the original blacker line reappear as blacker"], "correct": 0, "explanation": "If the correcting cylinder is too weak, the originally blackest meridian line still looks blackest (the astigmatism is under-corrected)."}'),
  ('4aa591ca-13','{"options": ["0.25-0.75", "0.50-0.75", "0.75-1.00", "0.25-1.00"], "correct": 0, "explanation": "The normal lag of accommodation is small, on the order of +0.25 to +0.75 D (about +0.50 D expected)."}'),
  ('e6431904-4q','{"options": ["090 degrees", "180 degrees", "045 degrees", "135 degrees"], "correct": 1, "explanation": "To add minus power in the 90-degree (vertical) meridian, the minus-cylinder axis is placed at 180 (power acts perpendicular to the axis)."}'),
  ('059a338b-1x','{"options": ["0.50D", "0.75D", "0.83D"], "correct": 0, "explanation": "The fused cross-cylinder finding (5 exo here) corresponds to a small accommodative lag, about +0.50 D in this item. VERIFY: the phoria-to-lag relationship is system-specific and the value is uncertain, so confirm against the source."}'),
  ('fff52cca-2s','{"options": ["-0.75= -1.25C X 90", "-0.75= -1.25C X 180", "-0.75= +1.25C X 90", "-0.75= +1.25C X 180"], "correct": 0, "explanation": "Two meridional readings combine into sphero-cylinder form by taking the LESS minus reading as the sphere and the difference as the cylinder. Sphere = -0.75, the less minus of the two. Cyl = -2.00 - (-0.75) = -1.25. The axis goes with the meridian that carries the sphere, which is 90. Answer: -0.75 = -1.25 C x 90. Sanity check by transposing back: -0.75 at 90 and -0.75 + -1.25 = -2.00 at 180, which is exactly the two readings you started with."}'),
  ('e9578ea0-3i','{"options": ["exact", "more plus/least minus", "less plus/more minus"], "correct": 2, "explanation": "Scoping from FARTHER than the standard working distance makes you subtract too much working-distance power, giving a result with less plus / more minus."}'),
  ('12754464-2y','{"options": ["0.50D", "-0.50D", "4.50D", "- 2.50D"], "correct": 3, "explanation": "VERIFY (OEP system item): tests #7 and #19 belong to the 21-point analytical sequence, so the amplitude is read from that specific protocol, not a simple subtraction. Confirm against the OEP analysis; the listed numbers do not give a clean stand-alone amplitude."}'),
  ('d01064f9-37','{"options": ["accom. conv. is not fully developed", "insufficient plus in test no. 7", "suppression of the right eye", "suppression of the left eye"], "correct": 2, "explanation": "Seeing the target shift to one side instead of doubling on a convergence test indicates suppression of one eye. VERIFY: the suppressed-eye side depends on the exact setup, so confirm; here suppression of the right eye is the listed answer."}'),
  ('5e5e4481-1s','{"options": ["Habitual phoria at far", "Induced phoria at far", "True adduction at far", "Convergence at far"], "correct": 2, "explanation": "VERIFY (OEP system item): in the 21-point sequence the first fused (binocular) prism test is the base-out (true adduction) at far. Confirm the numbering against the OEP protocol the source uses."}'),
  ('a7fcd3e3-17','{"options": ["Base-in prism needed for vertical alignment of dissociated image", "Base-out prism needed for vertical alignment of dissociated image", "Base-up prism needed for horizontal alignment of dissociated image", "Base-down prism needed for horizontal alignment of dissociated image"], "correct": 0, "explanation": "VERIFY (OEP system item): test #3 is the vertical-alignment (vertical phoria) step that uses base-in/out prism to align the vertically dissociated images. Confirm the exact operation name in the source protocol."}'),
  ('4e60743a-1v','{"options": ["stimulation", "inhibition", "accommodation", "convergence"], "correct": 1, "explanation": "VERIFY (OEP system item): the Dissociated Cross-Cylinder test uses an ''inhibition'' type of probing in this framework. Confirm against the source''s probing-type classification."}'),
  ('0d159a3f-20','{"options": ["Ophthalmoscope", "BIO", "high amount of plus lens"], "correct": 1, "explanation": "Indirect MONOCULAR ophthalmoscopy uses a direct-type scope with a high-plus condensing lens; the BIO (binocular indirect ophthalmoscope) is the exception (it is binocular)."}'),
  ('6a2187b5-15','{"options": ["1.5-2mm", "3-4mm", "4-5mm", "5-6mm"], "correct": 0, "explanation": "The optic disc measures roughly 1.5 mm horizontally and about 1.9 mm vertically, so 1.5 to 2 mm covers it. Answer: 1.5-2mm. It is worth carrying the number because disc findings get described in disc diameters, so a ''one disc diameter'' lesion is about 1.5 mm across."}'),
  ('f71c20f8-14','{"options": ["0.2-0.3mm", "0.3-0.4mm", "0.4-0.4mm"], "correct": 1, "explanation": "The average cup-to-disc ratio is about 0.3 (roughly 0.3 to 0.4). VERIFY: confirm the source value; normal average C/D is near 0.3."}'),
  ('85631269-31','{"options": ["Leave the target as is", "Leave the letters under the green filter clearer", "Leave the letters under the red filter clearer"], "correct": 1, "explanation": "When finishing the sphere on duochrome with no exact equality, leave the GREEN side slightly clearer (avoids over-minusing/relaxes accommodation)."}'),
  ('3ecb4964-5k','{"options": ["OD -1.25/OS -1.50", "OD -1.75/OS -1.50", "OD -0.75/OS -1.00", "OD -1.00/OD -0.75"], "correct": 0, "explanation": "VERIFY (OEP binocular-balance item): reducing from OU -1.50 when one eye is preferred once leads to an unequal split such as OD -1.25 / OS -1.50. Confirm the exact step against the source balance protocol."}'),
  ('f48998e4-2m','{"options": ["central disorder", "retinal involvements", "associated with hysteria", "corneal problem"], "correct": 0, "explanation": "A sluggish direct pupillary reaction can indicate a central (neurological) disorder along the reflex pathway. VERIFY: sluggish responses have several causes (afferent/efferent), so confirm the intended answer."}'),
  ('89da1380-38','{"options": ["-1.00C X 45", "-1.00C X 135", "-1.50C X 45", "-0.50C X 135"], "correct": 2, "explanation": "Javal''s rule scales corneal astigmatism up (about 1.25x plus a physiologic component), giving roughly -1.50 D for this cornea. VERIFY: with an oblique axis the vector form is messy, so confirm the source''s intended total-astigmatism answer."}'),
  ('9b743f8e-34','{"options": ["OS Supra 4/2; Infra 3/1", "OS Supra 3/1; Infra 4/2", "Rt. Hyperphoria", "Left Hypophoria"], "correct": 0, "explanation": "Vertical vergences are reciprocal between the eyes: OD base-down/base-up findings map to OS supra/infra of the same magnitudes (Supra 4/2; Infra 3/1). VERIFY: the supra/infra labeling can flip by convention, so confirm."}'),
  ('420e52f0-5v','{"options": ["+1.00 = +1.25 x 180", "+1.00 = +0.25 x 180", "+1.25 = +0.25 x180", "+0.75 = +1.25 x180"], "correct": 2, "explanation": "Two rules settle this, and the first one alone eliminates half the options. Rule 1, spherical equivalent is held constant. Every 0.50 D you change the cylinder must be matched by 0.25 D of sphere in the OPPOSITE direction. Options A and B change the cyl while leaving the sphere at +1.00, so both break that rule and neither can be right whichever way the patient answered. Rule 2, the red dot is the MINUS axis. Preferring it aligned with the correcting cylinder axis means the patient wants less plus cylinder, so +0.75 comes down. Two preferences without equality is two 0.25 steps, giving +0.75 - 0.50 = +0.25. Compensate the sphere the other way: +1.00 + 0.25 = +1.25. Answer: +1.25 = +0.25 x 180. Option D is the mirror of this, what you would write if the WHITE dot had been preferred: cyl up to +1.25, sphere down to +0.75. Both D and the answer keep the spherical equivalent intact, which is why the dot colour is the only thing separating them."}'),
  ('f69735f6-6b','{"options": ["give the present prescription that offers clear vision", "reduce the power to reduce the amount of phoria", "give the present prescription and advise AB to undergo VTO"], "correct": 2, "explanation": "An increase in exophoria with the new (stronger) prescription is best managed by giving the clear prescription and advising vision therapy (orthoptics) for the phoria."}'),
  ('c5ffd401-37','{"options": ["Presbyopia[", "Glaucoma[", "Myopia[", "Astigmatism["], "correct": 3, "explanation": "Headaches with focusing difficulty can be evaluated for ASTIGMATism (uncorrected astigmatism causes asthenopic strain/headache and blur at all distances). Among the options it''s the refractive cause of strain-headache. (Presbyopia/myopia give distance/near patterns; glaucoma is usually painless.) Uncorrected astigmatism = asthenopic headaches."}'),
  ('a1456184-66','{"options": ["Increase the lens power in the weaker eye", "Consider a different type of lens material", "Assess for any binocular vision issues and reassess the prescription", "Recommend a follow-up after several months"], "correct": 2, "explanation": "Persistent discomfort after correcting anisometropia → ASSESS for BINOCULAR VISION issues (aniseikonia, induced prism, fusion problems) and reassess the Rx — adaptation trouble often reflects binocular/aniseikonic strain, not just lens power/material. Reassess binocularity before changing power."}'),
  ('15a730ce-3z','{"options": ["Prescribing contact lenses to reduce the effect of anisometropia", "Using prisms to correct binocular vision", "Vision therapy focused on enhancing depth perception", "Surgical correction of anisometropia"], "correct": 0, "explanation": "To improve STEREOPSIS in significant anisometropia, PRESCRIBE CONTACT LENSES — they minimize aniseikonia and induced prism (vs spectacles), restoring more equal retinal image sizes and enabling fusion/depth. Prisms/VT/surgery are lesser first steps. Anisometropia + stereo goal = contacts."}'),
  ('e5ebe8e1-2f','{"options": ["A lesion on the lateral geniculate body will not have an effect on the pupillary light reflex;", "Normal direct and consensual light reflex is observed if light is presented on the opposite eye of the eye with a lesion on the optic nerve;", "A normal response on direct and consensual light reflex is observed, regardless where light is presented, if the lesion lies on the crossed optic chiasma;", "No direct and consensual light reflex is observed if the light is presented on the eye with a lesion on the optic nerve;"], "correct": 1, "explanation": "NOT TRUE = answer. With an OPTIC NERVE lesion, light in the OPPOSITE (good) eye drives BOTH pupils normally (intact afferent), so ''normal direct and consensual when light is on the opposite eye'' is actually TRUE... the FALSE/keyed option misstates this relationship (claims normality where the lesion would alter it, or vice versa). [Work each option through the afferent/efferent arc: nerve lesion = no response only when the BAD eye is lit; LGB lesion spares the pupil reflex.]"}'),
  ('39580922-2m','{"options": ["Symmetric, homologous", "Symmetric, heterologous", "Asymmetric, homonymous", "Asymmetric, heteronymous"], "correct": 0, "explanation": "With both eyes showing the same minus-cyl axis (90) and the same against-the-rule type, the astigmatism is symmetric and homologous. VERIFY: the symmetric/homologous vs heterologous classification is easy to confuse, so confirm the source''s scheme."}'),
  ('418121c9-2n','{"options": ["Symmetric, homologous/", "Symmetric, heterologous/", "Asymmetric, homonymous/", "Asymmetric, heteronymous/"], "correct": 0, "explanation": "Both corneas: OD −1.50×170, OS −1.75×10 — the axes (170 and 10) are mirror-symmetric about 180/0, and both eyes are the same astigmatism type, so the pattern is SYMMETRIC and HOMOLOGOUS (mirror-image axes, same type). Symmetric = mirror axes; homologous = same type both eyes."}'),
  ('7308e3d1-26','{"options": ["Right optic tract;", "Left optic tract;", "Right lateral geniculate body;;", "Left lateral geniculate body;"], "correct": 3, "explanation": "RIGHT homonymous CONGRUOUS hemianopsia = a LEFT-sided retrochiasmal lesion, and CONGRUITY implies a POSTERIOR location — among options the LEFT LGB (a complete, congruous homonymous defect). (More posterior = more congruous; the LGB/occipital give congruous defects.) Right field loss = left pathway; congruous = posterior."}'),
  ('5bcb2d0f-1y','{"options": ["vertical straight line;", "horizontal straight line;", "vertically oval;", "horizontally oval;"], "correct": 3, "explanation": "Simple hyperopic astigmatism WTR: the vertical meridian is emmetropic (focuses to a horizontal line) and the horizontal meridian is hyperopic — the blur image (Sturm conoid, anterior line) is a HORIZONTAL oval/line. (WTR places the anterior focal line horizontally.) Image shape follows the focal-line orientation."}'),
  ('c9c526b4-1x','{"options": ["vertical straight line=", "horizontal straight line=", "vertically oval=", "horizontally oval="], "correct": 3, "explanation": "Compound myopic astigmatism ATR: both meridians myopic with the steeper power horizontal; the point image (conoid of Sturm) elongates into a HORIZONTALLY OVAL blur. (ATR orientation gives a horizontal blur ellipse.) Image = horizontally oval."}'),
  ('b704ddab-1i','{"options": ["Short axial length of the eye", "Refractive system is too weak for its axial length", "Index of refraction of the aqueous humor and cornea is too low", "Increased depth of anterior chamber"], "correct": 3, "explanation": "Myopia results when the eye is too long for its optics; among these a deeper (increased) anterior chamber, lengthening the eye, fits a myopic shift. VERIFY: the options are awkwardly worded (several actually describe hyperopia), so confirm the intended myopia cause."}'),
  ('2c69d420-1r','{"options": ["Exophoria.", "Constant intermittent blur.", "Divergent strabismus.", "Less near work required."], "correct": 1, "explanation": "Hyperopic correction should be FULL when there is CONSTANT/intermittent BLUR (symptomatic, the patient can''t compensate) — symptoms drive full correction. With exophoria/divergent strabismus you may UNDER-correct (plus worsens exo via reduced accommodative convergence); minimal near work needs less. Symptomatic blur → correct fully."}'),
  ('a8f3f2fd-1p','{"options": ["It leads the patient to become more hyperopic due to the changes in the axial length/", "It leads to myopia due to changes in the eye''s anatomy and optical alignment/", "It can improve myopia by increasing the focusing power of the eye/", "It can completely correct hyperopia without the need for corrective lenses/"], "correct": 1, "explanation": "EXOPHTHALMOS (proptosis) can shift the eye toward MYOPIA by altering axial alignment/length and posterior pressure on the globe (and induced astigmatism from lid/orbital changes). It doesn''t improve myopia or correct hyperopia. Proptosis → myopic/astigmatic shift."}'),
  ('52d9eaca-50','{"options": ["Induced myopia due to variation in blood sugar levels", "Acquired myopia due to nuclear sclerosis of the crystalline lens", "Degenerative myopia based on the case history", "Pseudomyopia that needs cycloplegic refraction to be fully diagnose"], "correct": 3, "explanation": "Occasional near blur that will not clear with effort, needing cycloplegic refraction to diagnose, points to pseudomyopia (accommodative spasm)."}'),
  ('1d596689-2d','{"options": ["Perkins handheld", "Schiotz tonometer", "Goldmann tonometer", "Biomicroscope"], "correct": 1, "explanation": "The Schiotz tonometer measures IOP by INDENTATION: a weighted plunger presses into the cornea and how far it sinks indicates the pressure. Perkins and Goldmann are APPLANATION tonometers (they flatten a set area), and the biomicroscope is the slit lamp. Schiotz = indentation; Goldmann/Perkins = applanation."}'),
  ('9bd4511b-36','{"options": ["Brock string", "Panum''s area", "Visual fields", "Visuoscope"], "correct": 3, "explanation": "The visuoscope (a modified ophthalmoscope with a fixation target) is used to assess the fixation pattern and detect eccentric fixation directly on the retina. Brock string tests convergence, Panum''s area is a fusion concept, and visual fields map sensitivity. Visuoscope = fixation assessment."}'),
  ('6db426dc-16','{"options": ["1–3 years", "1–3 months", "3–6 months", "3–4 years"], "correct": 1, "explanation": "Motor fusion first appears at approximately 1–3 months of age. The fusional mechanism is fully developed by 1–1.5 years."}'),
  ('1f5f5f0a-23','{"options": ["Amblyopia", "Suppression", "Diplopia", "Centric fixation"], "correct": 3, "explanation": "Central (centric) fixation is a NORMAL finding, so there is nothing to treat with orthoptics. Amblyopia, suppression, and diplopia are the very conditions orthoptics/vision therapy targets. If fixation is already central and normal, no therapy is indicated."}'),
  ('e6bcb6fc-2g','{"options": ["Hypertension", "Kidney failure", "Multiple sclerosis", "Diabetes mellitus"], "correct": 3, "explanation": "Diabetes mellitus causes lens swelling (due to sorbitol accumulation) and index changes, leading to transient myopia. Uncontrolled DM can shift refraction toward myopia."}'),
  ('5f7b2d33-1c','{"options": ["Subjective refraction", "Delayed fogging", "Dry refraction", "Wet refraction"], "correct": 3, "explanation": "Wet refraction = cycloplegic refraction. Cycloplegic agents (e.g., cyclopentolate, atropine) paralyze the ciliary muscle to relax accommodation and reveal true refractive error."}'),
  ('fb63b0e0-1x','{"options": ["Indirect Proximal Illumination", "Diffuse illumination", "Sunset Illumination", "Direct focal illumination"], "correct": 0, "explanation": "Aqueous flare (protein in anterior chamber) is best seen with Indirect Proximal Illumination (oblique broad beam through the AC). The Tyndall effect scatters light off protein particles."}'),
  ('dd7e5ec5-3l','{"options": ["Visual field test", "Shadow Test", "Goldmann three-mirror test", "Gonioscopy"], "correct": 0, "explanation": "High IOP alone is not glaucoma; confirming the diagnosis requires demonstrating the characteristic functional damage, which the VISUAL FIELD test reveals (arcuate/nasal step defects). Gonioscopy classifies the angle (type of glaucoma) rather than confirming damage, the three-mirror examines the fundus/angle, and the shadow test is for cataract. Diagnosis of glaucoma = structural + FIELD damage, not IOP alone."}'),
  ('d2f3ad66-31','{"options": ["0.00 D", "2.50 D", "0.17 D", "1.00 D"], "correct": 2, "explanation": "The dioptric (accommodative) demand equals 1 divided by the distance in meters: 1/6 = 0.167, about 0.17 D. This is so small that 6 m is treated as optical infinity where the eye is essentially relaxed. Demand (D) = 1/distance(m)."}'),
  ('986ce68d-3p','{"options": ["diabetes mellitus", "heart disease", "glaucoma", "hypertension"], "correct": 1, "explanation": "Diabetes (retinopathy), glaucoma, and hypertension (hypertensive retinopathy) are directly sight-threatening and are routinely asked about. Heart disease, while important systemically, is not itself a primary sight-threatening ocular cause, so it is the EXCEPT here."}'),
  ('739ae559-2i','{"options": ["Ages 20 to 40", "Ages 40 to 60", "Ages 65 to 74", "Ages 12 to 17"], "correct": 2, "explanation": "By ages 65–74, nearly 90% of people wear plus (reading) lenses due to presbyopia. The crystalline lens loses elasticity progressively from age 40 onward."}'),
  ('67a4fee2-2l','{"options": ["10.00 D", "12.00 D", "24.00 D", "15.00 D"], "correct": 3, "explanation": "The crystalline lens contributes approximately 15–19 D to total eye power. Clear lens extraction (CLE) can neutralize up to ~15.00 D of myopia by removing the refracting power of the lens."}'),
  ('5db61fe2-2q','{"options": ["small amount of accommodative-convergence", "small amount of accommodation", "use of negative fusional vergence", "small amount of positive fusional vergence"], "correct": 2, "explanation": "An uncorrected myope is already focused for near, so at reading distance they use little accommodation and little accommodative convergence, and they tend to be exophoric at near, calling on POSITIVE fusional vergence (convergence) to stay single. They do NOT use negative fusional vergence (divergence), so that is the EXCEPT. Uncorrected myope at near = exo tendency = needs convergence, not divergence."}'),
  ('cc3c618b-2b','{"options": ["Goldmann tonometry", "Digital tonometry", "Field analyzer", "Gonioscopy"], "correct": 3, "explanation": "Gonioscopy directly visualizes the iridocorneal angle. A narrow or occludable angle indicates risk for acute angle-closure glaucoma."}'),
  ('75288543-21','{"options": ["Posterior subcapsular cataracts", "Miosis and nuclear sclerosis", "Miosis and pseudophakia", "Nuclear and posterior subcapsular cataracts"], "correct": 0, "explanation": "Posterior subcapsular cataracts (PSC) are located directly in the visual axis and cause maximum disability glare and reduced contrast sensitivity, especially in bright light or with oncoming headlights."}'),
  ('e1406e08-2u','{"options": ["43.00 D to 44.00 D", "46.00 D to 49.00 D", "40.00 D to 42.00 D", "36.00 D to 39.00 D"], "correct": 0, "explanation": "The average corneal power is about 43 to 44 D, which is roughly two-thirds of the eye''s total of about 60 D (the lens supplies the remaining ~19 D). Cornea about 43 D, lens about 19 D, eye about 60 D."}'),
  ('059382a8-3a','{"options": ["against-the-rule astigmatism", "irregular astigmatism", "oblique astigmatism", "with-the-rule astigmatism"], "correct": 0, "explanation": "With age the cornea shifts so the horizontal meridian steepens, moving astigmatism toward AGAINST-the-rule. So the age-related increase is against-the-rule astigmatism. Young eyes tend with-the-rule; older eyes drift against-the-rule."}'),
  ('4051c252-4d','{"options": ["5X", "2X", "3X", "4X"], "correct": 3, "explanation": "The magnification needed is the ratio of the acuities: 200/50 = 4X. A 4X telescope takes the 20/200 target detail up to the 20/50 level. Needed magnification = starting denominator / target denominator."}'),
  ('7628026e-1w','{"options": ["Smooth, accurate, extensive movement", "Smooth, full, and minimum jerk", "Jerk, full, extensive movement", "Limited but accurate movement"], "correct": 1, "explanation": "A full range of pursuit movement = smooth, full, with minimum jerk. Any saccadic intrusion indicates restricted or abnormal pursuit. Grading: full range = smooth, full, minimum jerk."}'),
  ('cea8d850-1m','{"options": ["Enlargement of blind spot", "Abnormal IOP", "Cupping of optic disc", "Swollen optic disc"], "correct": 3, "explanation": "Swollen optic disc (papilledema) indicates raised INTRACRANIAL pressure — not glaucoma. Glaucoma produces CUPPING (excavation) of the optic disc, not swelling. Signs include: abnormal IOP, cupping, enlarged blind spot, visual field loss."}'),
  ('913d3f8b-3y','{"options": ["Extent of field", "Depth of focus", "Depth of field", "Retinal field"], "correct": 1, "explanation": "Depth of focus refers to the range of vergences (image positions in front of or behind the retina) over which a retinal image appears acceptably sharp. It is a property of the optical system of the eye."}'),
  ('e059a5e2-2w','{"options": ["Synergist", "Antagonist", "Agonist", "Yoke muscle"], "correct": 1, "explanation": "The ANTAGONIST acts in the OPPOSITE direction of the primary (agonist) muscle within the SAME eye. Yoke muscles are contralateral muscles that move both eyes in the same direction (versions)."}'),
  ('a023c3e5-2x','{"options": ["Esotropia", "Exotropia", "Hyperopia", "Exophoria"], "correct": 0, "explanation": "A prominent epicanthal fold covers the nasal sclera and makes the eyes LOOK crossed, mimicking esotropia (pseudoesotropia). So a prominent epicanthal fold is frequently correlated with an esotropic appearance. Cover test would show the eyes are actually straight. Epicanthus = pseudo-esotropia."}'),
  ('24a8edbf-4c','{"options": ["180 degrees", "30 degrees", "90 degrees", "60 degrees"], "correct": 2, "explanation": "By the clock-dial ''rule of 30'', the axis of the correcting minus cylinder equals the clock hour of the clearest line times 30. The 9 o''clock line lies along the 3-9 meridian, so using 3: 3 x 30 = 90 degrees. VERIFY: fan-dial conventions differ, so confirm against the specific technique used. Rule of 30 puts the horizontal clear line at a 90-degree minus-cyl axis."}'),
  ('0c1a86ab-2r','{"options": ["Base-down prism", "Base-out prism", "Contact lenses", "Base-up prism"], "correct": 1, "explanation": "An esotropia (eye turned IN) is compensated with BASE-OUT prism, which shifts the image outward so the eye does not have to. Base-up/down correct vertical deviations. Eso = base-out; exo = base-in."}'),
  ('02687f07-14','{"options": ["2 to 4 weeks", "Birth", "2 to 3 months", "6 months"], "correct": 0, "explanation": "Steady fixation develops early, around 2 to 4 weeks as the fixation reflex matures (well before motor fusion at 3-6 months). VERIFY: some texts place well-established central fixation nearer 2 to 3 months, so the exact window is debatable; fixation is the earliest of the binocular milestones."}'),
  ('ae1b97f1-33','{"options": ["Stage 2", "Stage 4", "Stage 1", "Stage 3"], "correct": 0, "explanation": "Copper wiring (increased arteriolar light reflex with a reddish-orange color) is a Stage 2 finding in hypertensive retinopathy (Keith-Wagener classification). Stage 1 = silver wiring; Stages 3–4 = hemorrhages, papilledema."}'),
  ('45b5309c-5m','{"options": ["Perkins tonometer", "Pulse air tonometry", "Goldmann tonometer", "Digital tonometry"], "correct": 2, "explanation": "The prism doubling, cobalt-blue filter, and two fluorescein semicircles (mires) aligned inner-edge-to-inner-edge describe Goldmann APPLANATION tonometry mounted on the slit lamp. Perkins uses the same principle but is a handheld version, pulse-air is non-contact, and digital is finger tension. The slit-lamp mounted mires = Goldmann."}'),
  ('46a56295-3v','{"options": ["0.50 to 1.00 D of hyperopia", "4.00 to 8.00 D of hyperopia", "2.00 to 6.00 D of hyperopia", "6.00 to 10.00 D of hyperopia"], "correct": 0, "explanation": "Emmetropization drives most children toward a small residual of about +0.50 to +1.00 D of hyperopia by age 6. Larger amounts would be abnormal. The typical age-6 endpoint is low hyperopia."}'),
  ('9d901cc0-3p','{"options": ["10.00 D to 20.00 D of hyperopia", "0.25 D to 6.00 D of hyperopia", "10.00 D to 20.00 D of myopia", "0.25 D to 6.00 D of myopia"], "correct": 3, "explanation": "Prematurity is associated with MYOPIA (myopia of prematurity); in a heavier preemie with mature fundi the amount is modest, about 0.25 to 6.00 D of myopia rather than the extreme values. Premature = myopic tendency, mild when the fundus is mature."}'),
  ('e3215741-2r','{"options": ["Curvature hyperopia", "Facultative hyperopia", "Clonic hyperopia", "Absolute hyperopia"], "correct": 1, "explanation": "Facultative hyperopia is the portion of total hyperopia that CAN be overcome by accommodation. Absolute hyperopia cannot be overcome. Latent hyperopia is masked by ciliary muscle tone."}'),
  ('80a20053-2b','{"options": ["Corneal power is about 44.00 D", "Lenticular power is reaching 58.00 D", "Axial length is reaching 24 mm", "Anterior chamber depth is about 3.6 mm"], "correct": 1, "explanation": "Lenticular (crystalline lens) power is approximately 19–20 D — NOT 58 D. The total eye power is ~58.64 D (cornea + lens combined). Stating lenticular power = 58 D is incorrect."}'),
  ('16189e24-3h','{"options": ["Weak accommodative facility", "strong accommodative facility", "normal accommodative facility", "Adequate accommodative facility"], "correct": 2, "explanation": "About 8 to 10 cycles per minute with plus/minus 2.00 flippers falls within the expected adult range, indicating NORMAL accommodative facility. Far fewer cycles would indicate weak/reduced facility. Roughly 8 to 12 cpm = normal."}'),
  ('a01002f2-3n','{"options": ["25", "8", "16", "45"], "correct": 3, "explanation": "Convergence at the near point in prism diopters is PD(cm)/NPC(m) = 6/0.125 = 48 prism diopters; adjusting for the distance phoria gives about 45. VERIFY: strictly, an exophoria at distance would ADD to give ~51, so this item keys on 48 minus 3 = 45; treat the sign convention as the source intends. Convergence (PD) = PD in cm divided by distance in meters."}'),
  ('9863a601-21','{"options": ["Cluster headaches", "Cranial arteritis", "Hypertension headaches", "Migraine headaches"], "correct": 3, "explanation": "Migraines are most prevalent in young adults, particularly those aged 20–40. Cluster headaches and cranial arteritis are less common in young patients. Migraine is the #1 headache type in optometric practice for young adults."}'),
  ('d204bf94-2e','{"options": ["Specular Reflection", "Sclerotic Scatter", "Retro-illumination", "Van Herick Technique"], "correct": 0, "explanation": "Specular reflection uses the principle of equal angles — light striking the corneal or lens surface is reflected at the same angle. This illuminates the endothelium and tear film with minimal scatter."}'),
  ('10cba5b7-3s','{"options": ["20 cms", "10 cms", "30 cms", "40 cms"], "correct": 0, "explanation": "Near point = 1/AA = 1/5.00 D = 0.20 m = 20 cm. An emmetrope can work at 20 cm when fully accommodating with 5.00 D of amplitude."}'),
  ('722b65af-x','{"options": ["Examining interior eye", "Measuring corneal thickness", "Identifying EOR", "Determining IOL power"], "correct": 0, "explanation": "The ophthalmoscope (direct or indirect) is used to examine the interior of the eye — optic disc, retina, vessels, macula, and vitreous. Corneal thickness = pachymeter; IOL power = biometry."}'),
  ('c6c0a4cf-q','{"options": ["2 to 3 months", "2 to 4 weeks", "6 months", "At birth"], "correct": 0, "explanation": "Stable fixation develops at approximately 2–3 months of age. At birth, the infant can briefly follow a target but cannot maintain steady fixation."}'),
  ('3ee62b3b-3m','{"options": ["Steep", "Loose", "Tight", "Flat"], "correct": 0, "explanation": "The average cornea is about 43 to 44 D; the left eye readings (45.25 and 47.75 D) are well above that, so the cornea is STEEP (more curved than average). Higher keratometry power = steeper cornea. A flat cornea would read below ~42 D."}'),
  ('2f2c3656-31','{"options": ["1.50 D or more of hyperopia", "+0.50 D to −0.50 D", "+0.50 to +1.50 D", "0.50 D or more of myopia"], "correct": 0, "explanation": "Children with 1.50 D or more of hyperopia at ages 5–6 have insufficient emmetropization reserve and are most likely to remain hyperopic at ages 14–16. Lower initial hyperopia tends to resolve through normal emmetropization."}'),
  ('00987166-2h','{"options": ["Ocular disease", "Ametropia", "Neurological disease", "Dichromacy"], "correct": 3, "explanation": "Dichromacy is color vision deficiency — it does NOT reduce visual acuity or cause blurred vision. Ocular disease, ametropia, and neurological disease can all cause blurred vision or visual loss."}'),
  ('b8222c6f-12','{"options": ["Visual acuity", "Vernier acuity", "Esophoria", "Detection"], "correct": 0, "explanation": "Resolving power = the ability to resolve two separate points = minimum angle of resolution (MAR) = visual acuity. Vernier acuity is hyperacuity (detecting alignment differences); detection is threshold presence/absence."}'),
  ('381b9fba-1z','{"options": ["Convergence insufficiency", "Convergence excess", "Divergence excess", "Accommodative insufficiency"], "correct": 0, "explanation": "A receded near point of convergence (more than about 10 to 12 cm) means the eyes cannot converge close enough, the hallmark of CONVERGENCE INSUFFICIENCY. Convergence excess shows a very NEAR NPC. Remote NPC = convergence insufficiency."}'),
  ('c59c44fb-11','{"options": ["Distance blur", "Eyestrain", "Blurring at near", "Diplopia"], "correct": 0, "explanation": "The primary symptom of myopia is blurred DISTANCE vision. Near vision is clear in myopes because the near point is within normal working distance. Eyestrain is common but secondary."}'),
  ('a6a80e60-1h','{"options": ["concave sphere with convex cylinder lens", "concave sphere with concave cylinder", "convex sphere with concave cylinder lens", "convex sphere with convex cylinder lens"], "correct": 1, "explanation": "In compound myopic astigmatism BOTH principal meridians focus in front of the retina (both myopic), so both a minus (concave) sphere and a minus (concave) cylinder are needed. Any plus (convex) component would over-correct. Both meridians myopic = minus sphere + minus cylinder."}'),
  ('0c64f3b3-2p','{"options": ["15 prism diopters", "20 prism diopters", "10 prism diopters", "5 prism diopters"], "correct": 0, "explanation": "Convergence demand = PD(cm)/distance(m) = 6/0.40 = 15 prism diopters. A 40 cm target with a 60 mm PD calls for about 15 prism diopters of convergence. Convergence (PD) = PD in cm divided by distance in meters."}'),
  ('7212af49-23','{"options": ["Excessive decrease in accommodation", "Excessive increase in divergence", "Dispersion by prism", "Excessive increase in accommodation"], "correct": 0, "explanation": "Base-in prism reduces the convergence demand. Via the AC/A ratio, less convergence leads to LESS accommodation. The resultant decrease in accommodation causes blur (underfocused)."}'),
  ('7e85fed2-35','{"options": ["1.00 D", "0.50 D", "1.50 D", "3.00 D"], "correct": 3, "explanation": "Accommodative demand = 1/distance(m) = 1/0.33 m ≈ 3.00 D. At 33 cm (standard near point), an emmetrope requires approximately 3 D of accommodation."}'),
  ('a525f2f2-1x','{"options": ["0.25 D ATR", "1.25 D WTR", "1.00 D ATR", "0.50 D WTR"], "correct": 0, "explanation": "After age 45, astigmatism shifts toward ATR (against-the-rule) at a rate of approximately 0.25 D per decade. The vertical meridian weakens, increasing ATR astigmatism with aging."}'),
  ('a0cd29f0-36','{"options": ["70", "55", "63", "47"], "correct": 2, "explanation": "Presbyopia progresses as accommodation declines and plateaus once accommodation is essentially gone, around the early-to-mid 60s (about age 63). After that the reading add stays roughly constant. Add climbs until ~60-65, then levels off."}'),
  ('a489afd7-1x','{"options": ["Detection", "One minute of arc", "Esophoria", "Visual acuity"], "correct": 0, "explanation": "Detection threshold = the minimum stimulus intensity needed to be seen (present vs absent). Visual acuity = resolution; one minute of arc = minimum angle of resolution."}'),
  ('e910fbda-1s','{"options": ["Crystalline lens", "Vitreous humor", "Aqueous humor", "Cornea"], "correct": 3, "explanation": "The CORNEA is the most powerful single refractive element, about 43 D of the eye''s ~60 D (mostly from the air-to-tear/cornea interface). The lens adds about 19 D, and the aqueous/vitreous are transmitting media, not strong refractors. Cornea = the eye''s strongest lens."}'),
  ('f26d7f5b-3r','{"options": ["Presbyopia", "Astigmatism", "Myopia", "Hyperopia"], "correct": 2, "explanation": "If the refractive system is TOO STRONG (excessive plus power) relative to axial length, the image focuses IN FRONT of the retina = MYOPIA. Hyperopia = system too weak (or axial length too short)."}'),
  ('e589cf8e-1m','{"options": ["Hypertension", "Corneal steepening", "Cataract formation", "Diabetes mellitus"], "correct": 2, "explanation": "Certain cataract types (e.g., cortical) can reduce the effective plus power of the lens, shifting the refractive error toward hyperopia. Diabetes typically causes index myopia via nuclear changes."}'),
  ('1ae742db-2q','{"options": ["Compound myopic astigmatism", "Compound hyperopic astigmatism", "Simple myopic astigmatism", "Mixed astigmatism"], "correct": 3, "explanation": "One meridian is +3.00 D (hyperopic) and the other is +3.00 minus 6.00 = -3.00 D (myopic). One meridian in front of and one behind the retina defines MIXED astigmatism. Opposite-sign meridians = mixed astigmatism."}'),
  ('adc588ba-33','{"options": ["about 1.00 or 1.25 D per year", "about 0.75 or 1.00 D per year", "about 0.40 or 0.50 D per year", "about 1.00 or 1.50 D per year"], "correct": 2, "explanation": "School-age (juvenile) myopia typically progresses at a modest rate of about 0.40 to 0.50 D per year. Rates of 1.00 D or more per year would be unusually fast. Juvenile myopia creeps up ~0.50 D/year."}'),
  ('7659abd6-4m','{"options": ["22 prism diopters", "12 prism diopters", "32 prism diopters", "10 prism diopters"], "correct": 1, "explanation": "Total convergence = Accommodative Convergence (AC) + Fusional Convergence (FC). AC = Total − FC = 22 − 10 = 12 prism diopters."}'),
  ('6469023d-2g','{"options": ["magnify the retinal image size", "create spherical aberration", "minify the retinal image size", "cause a distorted image"], "correct": 0, "explanation": "Increasing the vertex distance of a PLUS lens increases its spectacle magnification, so the retinal image gets LARGER. (A minus lens moved out would minify.) Plus lens moved away = more magnification."}'),
  ('8413a2af-31','{"options": ["5.00 D", "10.00 D", "4.00 D", "8.00 D"], "correct": 0, "explanation": "Required add = 1/working distance(m) = 1/0.20 = 5.00 D. At 20 cm, 5.00 D of plus power is needed to bring the near point to that distance."}'),
  ('77a9a606-1w','{"options": ["Plus lens and BI prism", "Minus lens and BI prism", "Plus lens and BO prism", "Minus lens and BO prism"], "correct": 1, "explanation": "Exotropia (eyes drifting OUT) is managed by stimulating convergence with a MINUS lens (over-minus drives accommodative convergence) and by relieving prism placed BASE-IN. Base-out would worsen an exo. Exo = minus lens + base-in prism."}'),
  ('b9d7391d-2f','{"options": ["Ages 40 to 60", "Ages 65 to 74", "Ages 20 to 40", "Ages 12 to 17"], "correct": 1, "explanation": "By ages 65–74, approximately 90% of individuals use plus (reading) lenses due to fully manifest presbyopia. Presbyopia begins at ~40 but affects nearly all by age 65."}'),
  ('24ae5588-47','{"options": ["180 degrees", "30 degrees", "90 degrees", "60 degrees"], "correct": 2, "explanation": "The 3 o''clock line is the same horizontal (3-9) meridian as before; by the rule of 30, 3 x 30 = 90 degrees for the correcting minus cylinder. VERIFY: fan-dial conventions vary; the horizontal clear line maps to a 90-degree minus-cyl axis under the rule of 30."}'),
  ('4eb813b3-1v','{"options": ["6 to 8 weeks", "2 to 5 months", "Birth", "15 to 30 days"], "correct": 1, "explanation": "The blink-to-threat (menace) reflex is not present at birth; it emerges around 2 to 5 months as visual and cortical pathways mature. Menace reflex appears at a few months, not at birth."}'),
  ('d7373f50-1r','{"options": ["Point of neutrality", "Working distance power", "Maximum plus to relax", "Plane conjugate to retina"], "correct": 3, "explanation": "Autorefractors work on the optometer principle: they adjust optics until the target plane is CONJUGATE with the retina (the reflected image is in focus at the detector), then read off the power. Point of neutrality is retinoscopy, and ''max plus to relax'' is a subjective endpoint. Autorefraction = detect retinal conjugacy."}'),
  ('ae0452e9-1v','{"options": ["Symptoms", "Signs", "Complaints", "Eyestrain"], "correct": 1, "explanation": "Signs = objective findings observed by the clinician = manifestations of altered structure or function. Symptoms and complaints = subjective reports from the patient."}'),
  ('554053d7-44','{"options": ["Absolute hyperopia", "Latent hyperopia", "Facultative hyperopia", "Total hyperopia"], "correct": 0, "explanation": "ABSOLUTE hyperopia is the part of the error that accommodation CANNOT overcome, so it must be corrected optically. Facultative hyperopia can be overcome by accommodating, and latent hyperopia is masked by tone. The uncorrectable-by-focusing portion = absolute hyperopia."}'),
  ('e98b3df6-3b','{"options": ["Hyperopia", "Myopia", "Astigmatism", "Presbyopia"], "correct": 1, "explanation": "Deepening the anterior chamber moves the crystalline lens backward, reducing its effective plus power (a hyperopic shift), which lessens a MYOPIC error. So myopia is the condition reduced. Lens sits further back = less plus = less myopia."}'),
  ('f8a8ca15-2o','{"options": ["Hypertension", "Nerve disease", "Thyroid disease", "Diabetes"], "correct": 0, "explanation": "While hypertension can indirectly cause diplopia via vasculopathic cranial nerve palsy, it is the LEAST directly related. Nerve disease (CN palsy), thyroid disease (Graves ophthalmopathy), and diabetes (diabetic CN palsy) are direct, well-established causes of diplopia."}'),
  ('6e33ccda-1w','{"options": ["Hyperphoria", "Hypotropia", "Hypertropia", "Hypophoria"], "correct": 3, "explanation": "When the left eye moves DOWN upon covering (fusion broken), the left eye''s resting position is BELOW fixation — indicating left HYPOPHORIA (latent downward deviation of the left eye)."}'),
  ('1a05cb83-33','{"options": ["Stenopaic slit", "Prism dissociation", "Robinson Cohen", "Paraboline test"], "correct": 1, "explanation": "Prism DISSOCIATION is a binocular balancing technique for the SPHERE, not a way to find the cylinder. The stenopaic slit, Robinson-Cohen chart, and paraboline test all help determine the cylindrical (astigmatic) component. Prism dissociation balances sphere, it does not find cylinder."}'),
  ('6900401c-32','{"options": ["Between the ages of 14 to 20 years", "From birth to 13 years", "Between the ages of 5 to 6 years", "Between the ages of 5 to 6 years"], "correct": 0, "explanation": "After puberty (around age 14–20), refractive error is relatively stable for approximately 20 years until presbyopic changes begin around age 40. Childhood and early presbyopia are periods of more significant change."}'),
  ('c2db5f48-2a','{"options": ["Sclerocorneal angle", "Trabecular meshwork", "Schlemm''s canal", "Iridocorneal angle"], "correct": 3, "explanation": "The iridocorneal angle (also called the filtration angle or anterior chamber angle) is the anatomical space formed between the peripheral cornea and the iris root. This is where aqueous drains through the trabecular meshwork."}'),
  ('0c593b4f-2l','{"options": ["Do you have any health problems?", "When was your last eye exam?", "Are you taking any medications now?", "What is the problem?"], "correct": 0, "explanation": "''Do you have any health problems?'' directly elicits medical history information (systemic diseases, conditions). The other options relate to ocular history (last exam), medications (separate category), or chief complaint."}'),
  ('66bdbd90-1f','{"options": ["Itching", "Excessive tearing", "Eye pain", "Entoptic phenomena"], "correct": 3, "explanation": "Entoptic phenomena (e.g., floaters, phosphenes, afterimages) originate from within the eye or visual system and can cause visual distortions. Itching, tearing, and eye pain are non-visual ocular symptoms."}'),
  ('00d881fa-3w','{"options": ["16.00 D", "4.10 D", "20.00 D", "6.60 D"], "correct": 0, "explanation": "Amplitude = (1/near point) minus (1/far point) = (1/0.05) - (1/0.20) = 20 - 5 = 15 D. VERIFY: the exact 15 D is not offered, so this item is defective; 16.00 D is the nearest listed value. Amplitude (D) = near-point power minus far-point power."}'),
  ('cb097ce1-2b','{"options": ["Both are developed well", "Temporal to nasal is better than nasal to temporal", "Nasal to temporal is better than temporal to nasal", "Both are not well developed"], "correct": 2, "explanation": "In early infancy, nasal-to-temporal (N-T) pursuit is relatively better developed than temporal-to-nasal (T-N). This asymmetry resolves as binocular cortical development progresses, typically by 3–5 months."}'),
  ('540233e0-23','{"options": ["Concave setting", "Streak retinoscopy", "Spot retinoscopy", "Off-axis retinoscopy"], "correct": 3, "explanation": "Off-axis retinoscopy avoids the central opacity by angling the reflex through a clearer peripheral area. This allows an accurate reflex reading despite central media opacities like central corneal scars or cataracts."}'),
  ('80ec7e0a-2m','{"options": ["ill-sustained accommodation", "divergence excess", "convergence excess", "accommodative excess"], "correct": 2, "explanation": "A very NEAR point of convergence (about 3 cm) means the eyes converge strongly and easily, consistent with CONVERGENCE EXCESS. A remote NPC would instead suggest convergence insufficiency. Very close NPC = convergence excess."}'),
  ('2a2c899a-1c','{"options": ["Exophthalmometer", "Biomicroscope", "Indentation device", "Applanation tonometer"], "correct": 0, "explanation": "The exophthalmometer (Hertel) measures the degree of proptosis (forward protrusion of the eye) — NOT intraocular pressure. Indentation, applanation, and non-contact tonometers all measure IOP."}'),
  ('cfee8511-26','{"options": ["Vertical prism", "Optical correction for ametropia", "Vision therapy for accommodative insufficiency", "Vision therapy for amblyopia"], "correct": 2, "explanation": "Divergence insufficiency is treated with BI (base-in) prism, optical correction, and divergence-specific vision therapy. Vision therapy for ACCOMMODATIVE INSUFFICIENCY addresses a separate condition not related to divergence insufficiency."}'),
  ('5b9a108b-1z','{"options": ["2.00 D", "2.50 D", "3.00 D", "1.75 D"], "correct": 2, "explanation": "Hofstetter''s minimum AA = 15 − 0.25(age) = 15 − 0.25(48) = 15 − 12 = 3.00 D."}'),
  ('79fc3080-20','{"options": ["Markedly reduced amplitude of accommodation", "Marked diplopia", "With much near work required", "With constant intermittent blur"], "correct": 1, "explanation": "In cases of marked diplopia, prescribing the full refractive correction may WORSEN diplopia if the patient has adapted to uncorrected status. Prisms or partial correction may be used first. Other conditions (reduced AA, near work, blur) all warrant full correction."}'),
  ('fb63b731-1r','{"options": ["Toroidal", "Hyperbolic", "Elliptical", "Spherical"], "correct": 3, "explanation": "During full accommodation, the ciliary muscle contracts and zonular tension is released, allowing the crystalline lens to assume its natural, more SPHERICAL shape (increased curvature of anterior surface especially)."}'),
  ('3cf4362d-2q','{"options": ["1.00 D to 2.00 D EOR", "1.50 D to 2.50 D EOR", "1.50 D to 2.00 D EOR", "0.50 D to 2.50 D EOR"], "correct": 1, "explanation": "At standard working distance of 67 cm (1.50 D), subtract the working distance from the gross retinoscopy: 3.00−1.50 = 1.50 D and 4.00−1.50 = 2.50 D. EOR = 1.50 to 2.50 D."}'),
  ('171075ca-20','{"options": ["Multiple sclerosis", "Age-related maculopathy", "Cataracts", "Glaucoma"], "correct": 0, "explanation": "Multiple sclerosis typically affects younger adults (20–50 years) and is NOT a major cause of blindness in the elderly. Leading causes of blindness in the elderly: cataracts, AMD (age-related maculopathy), glaucoma, and diabetic retinopathy."}'),
  ('e751ebb5-2e','{"options": ["divergence excess", "convergence excess", "divergence insufficiency", "convergence insufficiency"], "correct": 1, "explanation": "A break point closer than about 5 cm means the eyes converge unusually strongly and easily, indicating CONVERGENCE EXCESS. A remote break point would be convergence insufficiency. Very near NPC break = convergence excess."}'),
  ('46d2a72d-2e','{"options": ["14 to 15 years", "40 to 60 years", "5 to 6 years", "20 to 40 years"], "correct": 0, "explanation": "Leptokurtic distribution (narrow, tall peak) in refractive error means most eyes cluster near emmetropia — this first becomes marked at ages 14–15 years after the emmetropization process."}'),
  ('d27a0d56-3f','{"options": ["Prism dissociation", "Duochrome test", "Maddox Rod", "Bichrome test"], "correct": 2, "explanation": "The MADDOX ROD is a heterophoria (eye-alignment) test, not a way to balance the SPHERE. Prism dissociation balances accommodation between the eyes, and the duochrome (bichrome) red-green test checks the spherical endpoint. Maddox rod = phoria, not sphere balance."}'),
  ('736eccd5-3c','{"options": ["Diabetic retinopathy", "Glaucoma", "Traumatic injury", "Age-related maculopathy"], "correct": 2, "explanation": "Diabetic retinopathy, glaucoma, and age-related maculopathy are the leading causes of blindness in the elderly. Traumatic injury is a more common cause of vision loss in younger, working-age people, so it is the exception here. Elderly blindness = DR, glaucoma, AMD (and cataract)."}'),
  ('03f2f274-26','{"options": ["patient demographics", "chief complaints", "medical history", "ocular history"], "correct": 2, "explanation": "Systemic conditions like hypertension and diabetes belong to the MEDICAL (general health) history. Demographics are age/occupation, the chief complaint is the presenting problem, and ocular history covers past eye issues. Systemic disease questions = medical history."}'),
  ('7e9bcc48-28','{"options": ["Fixation test", "Heterotropia", "Patient observation", "External Assessment"], "correct": 3, "explanation": "External Assessment is the systematic observation and examination of the patient''s external features (face, adnexa, ocular alignment) before instrumented testing. It includes noting posture, lids, pupils, and alignment by direct observation."}'),
  ('f545b5fd-1j','{"options": ["Double vision", "Headache", "Blurred vision", "Asthenopia"], "correct": 2, "explanation": "Blurred vision is the most common and primary presenting symptom of all forms of ametropia (myopia, hyperopia, astigmatism). Headache and asthenopia are common secondary symptoms."}'),
  ('ddd3d798-1b','{"options": ["Mexican", "Korean", "Australian", "Filipino"], "correct": 3, "explanation": "In the Philippine optometry curriculum, Filipinos are classified as predominantly hyperopic in early life (consistent with Southeast Asian population studies showing higher prevalence of hyperopia in early childhood compared to East Asian myopia patterns)."}'),
  ('182909d2-16','{"options": ["Color blindness", "Heterophoria", "Ametropia", "Orthophoria"], "correct": 2, "explanation": "Blurring of vision = failure of the optical system to focus clearly on the retina = ametropia (any refractive error). Orthophoria and heterophoria relate to ocular alignment, not image clarity."}'),
  ('7df540db-2p','{"options": ["- 0.50 cyl x 90", "- 0.50 D", "- 0.50 cyl x 180", "- 1.00 D"], "correct": 3, "explanation": "A -1.00 D error is clinically significant enough to warrant correction, whereas small -0.50 D spheres/cylinders are often asymptomatic and left uncorrected. The larger error is the significant one. About 1.00 D is the usual ''worth correcting'' threshold for many patients."}'),
  ('ccf82436-11','{"options": ["Crystalline lens provides 1/3 power of the eye.", "Crystalline lens is situated 3.6 mm behind the cornea.", "Complete power of the eye is 45.00 D.", "Cornea contributes 2/3 of refracting power."], "correct": 2, "explanation": "The complete power of the eye is about 60 D, not 45 D (45 D is roughly the cornea alone), so that statement is the incorrect one. The lens does provide about one-third (~19 D), sits about 3.6 mm behind the cornea, and the cornea supplies about two-thirds. Total eye ~60 D, cornea ~43-45 D, lens ~19 D."}'),
  ('bc17e6d1-1v','{"options": ["Starring expression", "Blurring at far", "Squinting of eyelids", "Blurring at near"], "correct": 3, "explanation": "Myopes see NEAR clearly (near point is within comfortable working distance). Blurring at near is NOT a myope''s symptom. Starring expression, squinting, and far blur are all characteristic myopia symptoms."}'),
  ('e19d0865-1w','{"options": ["Duction tests", "Maddox Double Prism", "Maddox Wing", "Phoria test"], "correct": 1, "explanation": "The Maddox DOUBLE prism (double Maddox rod) is the classic test for CYCLOPHORIA (a torsional deviation): the patient aligns two horizontal streaks, and any tilt reveals cyclodeviation. Duction tests check rotations, and the Maddox wing measures near horizontal/vertical phoria. Torsion = double Maddox rod."}'),
  ('accd31fa-31','{"options": ["Autorefraction", "Dynamic retinoscopy", "Static retinoscopy", "Videokeratoscopy"], "correct": 1, "explanation": "Dynamic retinoscopy (e.g., MEM, Nott, bell retinoscopy) measures the accommodative response at near working distance while the patient reads or fixates near targets. It provides objective near refractive data."}'),
  ('7afbb019-1l','{"options": ["65 percent of all esotropia", "78 percent of all accommodative esotropia", "50 percent of all alternating exotropia", "60 percent of exotropia"], "correct": 1, "explanation": "ACCOMMODATIVE esotropia is driven by uncorrected hyperopia, so correcting the hyperopia with lenses alone straightens a large share (about 78 percent). General eso/exotropias are far less responsive to lenses alone. Accommodative eso responds to the plus correction."}'),
  ('f69a60d9-1t','{"options": ["to balance the stereoacuity between the two eyes", "to balance the visual acuity of the two eyes", "to balance the heterophorias between the two eyes", "to balance the accommodation between the two eyes"], "correct": 3, "explanation": "Binocular (end-point) balancing equalizes the ACCOMMODATIVE state between the two eyes so both are equally relaxed/fogged at the end of refraction. It cannot equalize acuity if one eye is amblyopic, and it is not a stereo or phoria test. Balance = equal accommodation, not equal acuity."}'),
  ('0003a0c1-4a','{"options": ["IV", "I", "III", "II"], "correct": 1, "explanation": "An image formed IN FRONT of the retina is MYOPIA (I, option B). Hyperopia focuses behind, emmetropia on the retina, and astigmatism at two lines. Front of retina = myopia."}'),
  ('a7b42de8-3r','{"options": ["IV", "I", "II", "III"], "correct": 2, "explanation": "A FLATTER cornea supplies less converging power, shifting the eye toward HYPEROPIA (II, option C). A steep cornea gives myopia. Flat cornea = less plus = hyperopia."}'),
  ('94c5b3bd-3t','{"options": ["III", "IV", "II and III", "I and III"], "correct": 3, "explanation": "Keratoconus steepens and distorts the cornea, producing MYOPIA and irregular ASTIGMATISM, so I and III (option D). Its progressive thinning cone induces myopic astigmatism. Keratoconus = myopia + (irregular) astigmatism."}'),
  ('43c10345-54','{"options": ["IV", "I", "III", "II"], "correct": 2, "explanation": "With accommodation relaxed, an image formed BEHIND the retina is HYPEROPIA (III, option C in this legend). The hyperope must accommodate to pull it forward onto the retina. Behind the retina (relaxed) = hyperopia."}'),
  ('90e522d7-58','{"options": ["IV", "II", "III", "I"], "correct": 3, "explanation": "An image IN FRONT of the retina with accommodation relaxed is MYOPIA (I, option D in this legend). Accommodation only adds plus power, so it cannot fix myopia. Front of retina = myopia."}'),
  ('a8927f98-3j','{"options": ["I", "III", "II", "IV"], "correct": 3, "explanation": "EMMETROPIA (IV, option D) is the normal, no-error state, so it is NOT an ametropia. Myopia, hyperopia, and astigmatism are the ametropias. Ametropia means a refractive error; emmetropia has none."}'),
  ('a3807984-55','{"options": ["I", "III", "IV", "II"], "correct": 0, "explanation": "Ametropia (a refractive error) is first managed by providing LENS CORRECTION (I, option A). Visual training, penalization, and prism address binocular/functional problems, not the basic refractive blur. Refractive error = lenses first."}'),
  ('0b86a7c6-6l','{"options": ["I and IV", "III and IV", "IV", "I and II"], "correct": 0, "explanation": "A hyperope with near diplopia needs both the LENS CORRECTION (I) for the hyperopia and PRISM CORRECTION (IV) to relieve the deviation causing the doubling, so I and IV (option A). Correct the refraction and add prism for the diplopia."}'),
  ('71d0b6e1-5e','{"options": ["II", "IV", "I", "III"], "correct": 2, "explanation": "For a young child the initial step is usually to provide the LENS CORRECTION first (I, option C) and let vision develop before adding therapy. VERIFY: if the case is amblyopia, pharmacologic penalization could be argued, so confirm against the source; lens correction is the standard first move."}'),
  ('7c53a682-1y','{"options": ["Excessive lacrimation", "Headache", "Loss of vision", "Diplopia"], "correct": 0, "explanation": "EXCESSIVE LACRIMATION is an OCULAR symptom (a problem of the eye/adnexa itself). Loss of vision and diplopia are VISUAL symptoms, and headache is a referred/general symptom. Ocular = the eye''s own physical complaint (tearing)."}'),
  ('801ce44d-2g','{"options": ["Vertigo", "Headache", "Mild nausea", "Twitching"], "correct": 1, "explanation": "Of these associated complaints, HEADACHE is the one tied to visual effort (asthenopic/eyestrain headache from uncorrected error or binocular stress). VERIFY: vertigo, nausea, and twitching are non-visual associated symptoms, and this item''s grouping is loose; headache is the vision-related choice."}'),
  ('6ecdd100-22','{"options": ["Pain", "Fatigue", "Stress", "Distortion"], "correct": 3, "explanation": "DISTORTION of the image (metamorphopsia) is a genuine VISUAL symptom, arising from macular or optical changes. Pain, fatigue, and stress are general/comfort complaints, not visual. Distortion = a symptom of vision itself."}'),
  ('a08cf973-61','{"options": ["I", "III", "II", "IV"], "correct": 0, "explanation": "Confusing right and left is a laterality/directionality problem, tested by VISUAL SPATIAL skills (I, option A). Analysis, information-processing, and sequential skills address form/memory rather than spatial orientation. Right-left confusion = spatial skills."}'),
  ('602c5019-6d','{"options": ["II", "III", "IV", "I"], "correct": 1, "explanation": "Recognition plus recall of visual information falls under VISUAL INFORMATION PROCESSING skills (III, option B), the umbrella covering visual memory and analysis. VERIFY: ''recall'' could also be classed under visual analysis (memory), so this mapping is debatable. Memory/recall of visual info = information-processing skills."}'),
  ('0f0f6719-5w','{"options": ["II", "III", "IV", "I"], "correct": 0, "explanation": "Recognizing the distinguishing FEATURES of a stimulus is VISUAL ANALYSIS (II, option A), which includes discrimination and form perception. VERIFY: analysis and information-processing overlap, so the category split is loose. Discriminating features = visual analysis skills."}'),
  ('e11e57cf-3b','{"options": ["Divergence excess", "Divergence insufficiency", "Convergence insufficiency", "Convergence excess"], "correct": 2, "explanation": "Orthophoria at distance with a RECEDED near point of convergence (14 cm, well beyond the normal ~10 cm) is the picture of CONVERGENCE INSUFFICIENCY. The eyes align fine far away but cannot sustain convergence up close. Ortho far + remote NPC = convergence insufficiency."}'),
  ('976010df-1m','{"options": ["7.14 prism diopter", "14.28 prism diopter", "44.48 prism diopter", "86.80 prism diopter"], "correct": 2, "explanation": "Convergence at the near point = PD(cm)/NPC(m) = 6.2/0.14 = about 44 prism diopters; with orthophoria at distance (zero far demand) the amplitude is essentially that value, about 44 prism diopters. Amplitude of convergence (PD) = PD in cm divided by NPC in meters."}'),
  ('813ff18c-2b','{"options": ["Maddox Rod test", "Cover test", "Version test", "Adduction test"], "correct": 1, "explanation": "The COVER test at near objectively reveals the exophoria/exo-drift that accompanies convergence insufficiency, confirming the finding alongside the receded NPC. Version and adduction tests assess ductions/rotations, and Maddox rod is subjective. Cover test confirms the near exo deviation."}'),
  ('eea3b260-29','{"options": ["raised ICP", "raised IOP", "reduced ECG", "decreased EEG"], "correct": 0, "explanation": "A swollen (edematous) optic disc, papilledema, is the key sign of raised INTRACRANIAL pressure. Raised IOP causes CUPPING, not swelling. Swollen disc = raised ICP; cupped disc = raised IOP."}'),
  ('4b1bf81b-2a','{"options": ["Optic neuritis", "Glaucoma", "Papilledema", "Optic atrophy"], "correct": 1, "explanation": "Cupping (an enlarged optic-cup-to-disc ratio from axon loss) is the hallmark of GLAUCOMA. Papilledema swells the disc, optic neuritis inflames it, and optic atrophy pales it. Cupped disc = glaucoma."}'),
  ('500aa544-2n','{"options": ["Indirect ophthalmoscope", "Slit Lamp", "Direct ophthalmoscope", "Video Keratoscope"], "correct": 0, "explanation": "The INDIRECT ophthalmoscope gives a wide, panoramic (though inverted) view of the fundus and better peripheral reach. The direct ophthalmoscope gives high magnification but a narrow field. Wide fundus view = indirect ophthalmoscopy."}'),
  ('73d1e7aa-1m','{"options": ["Randot test", "Bagolini lenses", "Worth dot test", "4 prism BO test"], "correct": 2, "explanation": "The WORTH 4-dot is a relatively gross, dissociating test of peripheral fusion and misses a tiny microtropia. The 4-prism base-out test and Bagolini lenses are designed to catch subtle microtropia, and Randot assesses fine stereo. VERIFY: sensitivity depends on test distance/spot size. Microtropia hides from the Worth 4-dot."}'),
  ('c4c6f4ad-1w','{"options": ["Bagolini", "Maddox", "Red filter", "Worth dot"], "correct": 0, "explanation": "BAGOLINI striated lenses barely disturb normal seeing (nearly natural viewing conditions), so they are the LEAST dissociating and best reflect everyday binocular status. Maddox rod, red filter, and Worth dot dissociate the eyes much more. Bagolini = most natural, least dissociating."}'),
  ('ebc2f857-3l','{"options": ["4 prism BO test", "Cover test", "Bagolini lenses", "Pinhole test"], "correct": 1, "explanation": "The COVER test is the objective way to separate a phoria (latent, appears only under cover) from a tropia (manifest, present with both eyes open). Bagolini and 4-prism BO probe fusion/microtropia, and the pinhole checks refractive vs pathological blur. Cover test = phoria vs tropia."}'),
  ('b2a214b3-25','{"options": ["Myopia, with-the-rule astigmatism", "Myopia, against-the-rule astigmatism", "Myopia, oblique astigmatism", "Simple myopic astigmatism"], "correct": 0, "explanation": "Both meridians are myopic (a -1.25 sphere with added minus cylinder), and the minus-cylinder axis of 175 is near 180, which is WITH-the-rule. So it is myopia with with-the-rule astigmatism. Minus-cyl axis near 180 = with-the-rule."}'),
  ('bfc3ffba-24','{"options": ["Mixed astigmatism", "Compound myopic astigmatism", "Myopia, against-the-rule astigmatism", "Myopia, oblique astigmatism"], "correct": 1, "explanation": "With a -1.25 sphere and -1.25 cylinder, BOTH meridians are myopic, which is COMPOUND MYOPIC astigmatism. It is not mixed (that needs one plus and one minus meridian). Both meridians myopic = compound myopic astigmatism."}'),
  ('00ac2bcb-2o','{"options": ["Against-the-rule astigmatism", "Oblique astigmatism", "Inverse astigmatism", "With-the-rule astigmatism"], "correct": 3, "explanation": "The refractive astigmatism is with-the-rule (minus-cyl axis near 180), and corneal astigmatism should match, with the steeper meridian vertical, giving WITH-the-rule corneal astigmatism. Refractive and corneal astigmatism type generally agree; here both are with-the-rule."}'),
  ('20c5398a-2c','{"options": ["Atherosclerosis", "Diabetes mellitus", "Hypercalcemia", "Hypertension"], "correct": 1, "explanation": "DIABETES raises blood glucose, which swells the crystalline lens and induces a MYOPIC shift. Atherosclerosis, hypercalcemia, and hypertension do not swell the lens this way. High sugar = swollen lens = more myopia."}'),
  ('19afa4f4-2f','{"options": ["Diabetes mellitus", "Hypertension", "Myasthenia gravis", "Atherosclerosis"], "correct": 0, "explanation": "DIABETES can also cause a HYPEROPIC shift, classically when hyperglycemia is corrected and the lens rebounds. VERIFY: this repeats diabetes as the answer for the opposite shift too, which is unusual for a matching set; diabetes is simply the systemic disease that shifts refraction in BOTH directions depending on glucose control."}'),
  ('d33a83d9-2v','{"options": ["thyroid disease", "diabetes", "nerve disease", "hypertension"], "correct": 3, "explanation": "Thyroid disease (restrictive myopathy), diabetes (cranial-nerve palsy), and nerve disease all cause diplopia. Hypertension is the least directly related, so it is the EXCEPT. Diplopia work-up: thyroid, diabetes, nerve first; hypertension is the outlier."}'),
  ('f01f6aff-1u','{"options": ["Limit of fusion field", "Total positive convergence in reserve", "Limit of positive fusional convergence", "Positive fusional divergence in reserve"], "correct": 2, "explanation": "As base-out prism is added, the first BLUR marks where fusional (relative) convergence is maxed out and accommodation begins to be disturbed: the LIMIT OF POSITIVE FUSIONAL CONVERGENCE with clear vision. VERIFY: terminology for blur/break/recovery varies between texts. Blur = the clear-vision limit of positive fusional convergence."}'),
  ('d9d114a4-1o','{"options": ["Limit of positive fusional convergence", "Limit of fusion field", "Total positive convergence", "Positive fusional divergence"], "correct": 2, "explanation": "The BREAK point (where single vision splits into double) reflects the TOTAL positive convergence the patient can muster before fusion fails. VERIFY: some texts label the break as the ''limit of the fusion field''; the concept is the maximum convergence at which fusion is lost."}'),
  ('ad8afdc4-1u','{"options": ["Total positive convergence", "Total fusional innervation", "Limit of fusion field", "Limit of fusional convergence"], "correct": 1, "explanation": "The RECOVERY point (regaining single vision after the break) reflects the patient''s total fusional innervation/reserve, how readily they can re-fuse. VERIFY: blur/break/recovery labeling differs by source, so confirm against the key; recovery indexes the fusional reserve."}'),
  ('c29bcdcf-2e','{"options": ["Functional", "Ocular", "Visual", "Referred"], "correct": 2, "explanation": "Blurred vision is a VISUAL complaint (a problem with the clarity of sight itself). Ocular complaints are about the eye''s comfort/appearance, functional refers to task performance, and referred are secondary (like headache). Blur = visual category."}'),
  ('d66b6e19-2g','{"options": ["Functional", "Referred", "Visual", "Ocular"], "correct": 2, "explanation": "Double vision (diplopia) is a VISUAL symptom, a disturbance of sight/binocularity. It is not merely an ocular-comfort or referred complaint. Diplopia = visual category."}'),
  ('bf9fc9ea-2b','{"options": ["Referred", "Functional", "Ocular", "Visual"], "correct": 0, "explanation": "Headache is a REFERRED symptom: the visual/ocular strain refers pain to the head rather than being felt in the eye itself. It is secondary to the underlying visual stress. Eyestrain headache = referred symptom."}'),
  ('07fa81c3-3n','{"options": ["Isometropic amblyopia", "Anisometropic amblyopia", "Organic amblyopia", "Functional amblyopia"], "correct": 0, "explanation": "Both eyes carry high, roughly EQUAL hyperopic astigmatism with equally reduced acuity (20/200 each), which is ISOMETROPIC (bilateral ametropic) amblyopia. Anisometropic amblyopia needs a large difference between the eyes, and the media/fundi are healthy (not organic). Equal high bilateral error = isoametropic amblyopia."}'),
  ('94bbe676-1l','{"options": ["+8.25 sph", "+4.00 sph - 1.25 cyl x 10", "+8.50 sph - 1.25 cyl x 10", "+7.50 sph"], "correct": 2, "explanation": "For a young hyperope with accommodative esotropia and bilateral ametropic amblyopia, give essentially the FULL cycloplegic hyperopic correction including the astigmatism, best represented by +8.50 sph -1.25 cyl x 10. Under-plus options (like +4.00 or +7.50) would leave eso and amblyopia undertreated. Accommodative eso + high hyperopia = prescribe (near) full plus with cylinder."}'),
  ('e28f1645-47','{"options": ["Centric fixation", "Suppression", "Eccentric viewing", "Eccentric fixation"], "correct": 3, "explanation": "Residual amblyopia that plateaus at 20/60 despite correction commonly harbors ECCENTRIC FIXATION (the fovea is no longer the preferred fixation point). Centric fixation would be normal, and eccentric viewing is a low-vision adaptation. Stuck residual amblyopia = suspect eccentric fixation."}'),
  ('9cf6b5dd-32','{"options": ["entrance pupil", "Vernier acuity", "Pinhole", "pupillometer"], "correct": 1, "explanation": "VERNIER acuity is the hyperacuity for detecting misalignment of two line segments placed end to end, sensitive to a fraction of a photoreceptor width. The pinhole and entrance pupil concern light entry, and the pupillometer measures PD. Line-offset detection = vernier acuity."}'),
  ('a8a78113-37','{"options": ["Minimum Legible", "Resolution", "Localization", "Minimum Distinguishable"], "correct": 2, "explanation": "Detecting a small displacement between a point and a line is a LOCALIZATION (minimum discriminable) task, the vernier-type acuity. Minimum legible is letter recognition and resolution is separating two points. Offset/alignment judgment = localization."}'),
  ('5e27b0c7-2q','{"options": ["Pinhole", "Pupillometer", "Stenopaic slit", "Vernier acuity"], "correct": 1, "explanation": "The PUPILLOMETER is the dedicated device for measuring interpupillary distance accurately (more precise than a ruler). The pinhole and stenopaic slit are refraction aids, and vernier acuity is a visual task. PD measurement = pupillometer."}'),
  ('a9ed35a5-27','{"options": ["Specular Reflection", "Sclerotic Scatter", "Van Herick Technique", "Retro-illumination"], "correct": 2, "explanation": "The VAN HERICK technique estimates the peripheral anterior chamber depth/angle by comparing the width of the corneal optical section to the dark gap before the iris. Specular reflection shows endothelium, sclerotic scatter shows corneal edema, and retro-illumination backlights lesions. Angle/chamber-depth estimate = Van Herick."}'),
  ('f3534c2d-24','{"options": ["Van Herick Technique", "Retro-illumination", "Specular Reflection", "Sclerotic Scatter"], "correct": 3, "explanation": "SCLEROTIC SCATTER shines light at the limbus so it travels through the cornea by total internal reflection; a clear cornea stays dark, but edema/opacity lights up as a glow. Van Herick estimates the angle, specular shows endothelium, and retro-illumination backlights the iris/lens. Corneal edema glow = sclerotic scatter."}'),
  ('7ce1b299-2o','{"options": ["Tangential illumination", "Retroillumination", "Sclerotic scatter", "Specular reflection"], "correct": 3, "explanation": "SPECULAR reflection produces the mirror-bright zone that reveals the endothelial cell mosaic and any debris/guttata on it. Tangential grazes the surface, retro-illumination backlights, and sclerotic scatter shows edema. Endothelial detail = specular reflection."}'),
  ('5c010e66-1x','{"options": ["Diffuse illumination", "Tangential Illumination", "Indirect Proximal Illumination", "Direct focal illumination"], "correct": 0, "explanation": "DIFFUSE illumination floods the anterior segment with soft, wide light for a general OVERVIEW of the lids, conjunctiva, cornea, and iris. The focal/tangential/indirect methods isolate specific structures. Broad survey = diffuse illumination."}'),
  ('63fdf767-24','{"options": ["Sunset Illumination", "Diffuse illumination", "Direct focal illumination", "Indirect Proximal Illumination"], "correct": 2, "explanation": "DIRECT FOCAL illumination (a parallelepiped or optic section) cuts an optical slice through the cornea and lens to examine the stroma, lens surfaces, and depth of any lesion. Diffuse gives only an overview. Slicing through the optical media = direct focal illumination."}'),
  ('5319f7d3-1z','{"options": ["Direct focal illumination", "Tangential Illumination", "Diffuse illumination", "Indirect Proximal Illumination"], "correct": 3, "explanation": "INDIRECT (proximal) illumination places the bright beam next to the area of interest so scattered light backlights subtle epithelial erosions and reveals iris transillumination defects. Direct focal lights the lesion straight on and can wash out these faint findings. Subtle epithelial/iris findings = indirect illumination."}'),
  ('740d04cd-1z','{"options": ["Increase accommodative demand.", "Produce peripheral hyperopic defocus.", "Create peripheral myopic defocus to slow axial elongation.", "Increase central retinal blur and depth of field."], "correct": 2, "explanation": "Create peripheral myopic defocus to slow axial elongation, the core idea of myopia-control lenses. Hint: peripheral MYOPIC defocus (image in front of the peripheral retina) is the growth brake."}'),
  ('5d33a968-t','{"options": ["Light rays focus anterior to the retina.", "Light rays focus posterior to the retina.", "Light rays focuses in the peripheral retina.", "Accommodation is completely relaxed."], "correct": 1, "explanation": "Hyperopic defocus = light focuses POSTERIOR to (behind) the retina. Hint: hyperopic = focus behind; myopic = focus in front."}'),
  ('c61fa6f1-6k','{"options": ["Accommodative spasm", "Latent hyperopia", "Presbyopia", "Myopic shift"], "correct": 2, "explanation": "Presbyopia, a 48-year-old with clear distance (20/20), needing to hold print farther and getting near eyestrain, is the classic picture. Hint: 40s + near-only trouble + arms getting longer = presbyopia."}'),
  ('a1a3dfd2-1z','{"options": ["Increased rigidity of the crystalline lens and decreased lens elasticity.", "Weakening of the extra ocular muscles.", "Progressive flattening of the cornea", "Increased vitreous liquefaction"], "correct": 0, "explanation": "Increased lens rigidity and decreased elasticity, the lens can no longer round up to focus near. Hint: presbyopia = the aging lens goes stiff, not the muscles."}'),
  ('695cba4e-1d','{"options": ["Hyperopic defocus generally slows axial elongation.", "Myopic defocus is associated with stimulation of eye growth.", "Hyperopic defocus may stimulate axial elongation, whereas myopic defocus tends to inhibit it.", "Both myopic and hyperopic defocus have identical effects on eye growth."], "correct": 2, "explanation": "TRUE: hyperopic defocus may STIMULATE axial elongation while myopic defocus tends to INHIBIT it. Hint: behind-the-retina (hyperopic) defocus grows the eye; in-front (myopic) defocus slows it."}'),
  ('871f0e5e-1y','{"options": ["Progressive reduction in accommodative amplitude.", "Difficulty with sustained near tasks.", "Increased elasticity of the crystalline lens.", "Increasing need for plus lenses for near vision."], "correct": 2, "explanation": "''Increased elasticity of the lens'' is the EXCEPT, presbyopia is DECREASED elasticity. Hint: the presbyopic lens loses elasticity, it does not gain it."}'),
  ('3a9eaf7b-1p','{"options": ["It is primarily caused by decreased crystalline lens elasticity.", "Symptoms usually Negin between 40 and 45 years.", "Presbyopia causes permanent reduction of distance visual acuity.", "Near addition generally increases with age."], "correct": 2, "explanation": "FALSE: presbyopia does NOT reduce DISTANCE acuity (distance vision is unaffected). The others are true. Hint: presbyopia hits near vision only; distance stays fine."}'),
  ('bccddba2-3g','{"options": ["2-3 HOURS", "8-24 HOURS", "More than 30 HOURS", "5 HOURS"], "correct": 1, "explanation": "Cyclopentolate accommodation returns in about 8 to 24 hours (cycloplegia). Hint: cyclopentolate = a day to fully recover accommodation (mydriasis a bit longer)."}'),
  ('024ea5e8-1h','{"options": ["‘a. High value of IOP", "‘b. Shallow depth of anterior chamber", "‘c. Narrow angle glaucoma", "‘d. Anisometropia"], "correct": 3, "explanation": "EXCEPT (not a contraindication). Cycloplegia is contraindicated when dilation is dangerous: high IOP, shallow anterior chamber, narrow-angle glaucoma (risk of angle closure). ANISOMETROPIA is NOT a contraindication — it''s actually a reason to cycloplege (accurate refraction). Angle-closure risk = the real contraindications."}'),
  ('7db5b853-3b','{"options": ["Increased pupil size increases depth of focus.", "Smaller pupils increase depth of focus.", "Bright light increases accommodation.", "Bright light eliminates presbyopia."], "correct": 1, "explanation": "Smaller pupils (in bright light) increase depth of focus, easing near reading for the presbyope. Hint: bright light -> small pupil -> pinhole effect -> more depth of focus."}'),
  ('ae24c1a7-29','{"options": ["Slowing axial elongation", "Creating peripheral myopic retinal defocus", "Providing clear central vision", "Creating peripheral hyperopic defocus"], "correct": 3, "explanation": "''Creating peripheral hyperopic defocus'' is the EXCEPT, hyperopic defocus PROMOTES growth (the opposite of control). Hint: control uses MYOPIC defocus; hyperopic defocus is the enemy."}'),
  ('1983c10a-18','{"options": ["It has been shown to reduce axial elongation.", "It is utilized in orthokeratology.", "It promoted faster myopia progression.", "It is incorporated into some spectacle lens designs."], "correct": 2, "explanation": "FALSE: myopic defocus does NOT speed progression, it SLOWS axial elongation (used in ortho-k and control lenses). Hint: myopic defocus is protective, not progressive."}'),
  ('3604bfa1-34','{"options": ["Topical corticosteroids indefinitely", "Warm compresses, lid hygiene, and lubricating eye drops", "Topical antiviral medication", "Immediate punctal occlusion"], "correct": 1, "explanation": "Warm compresses, lid hygiene, and lubricating drops, first-line for mild evaporative dry eye/MGD. Hint: MGD basics = heat, lid scrubs, and tears before anything invasive."}'),
  ('9aa2915e-2b','{"options": ["Presbyopia", "Aphakic", "Macular edema", "Anisometropia"], "correct": 3, "explanation": "Anisometropia is the EXCEPT (it is an indication for cycloplegic retinoscopy, not a reason to avoid it). Hint: as in Q9, anisometropia calls FOR cyclo-refraction."}'),
  ('9c4b4697-33','{"options": ["Reduced axial elongation", "Increased axial elongation", "Development of presbyopia", "Lens opacification"], "correct": 1, "explanation": "Increased axial elongation, imposed peripheral hyperopic defocus drives eye growth in animal models. Hint: hyperopic defocus = grow signal = longer eye."}'),
  ('21b63844-2v','{"options": ["Depth of focus", "Depth of field", "Depth perception", "Depth of anterior chamber"], "correct": 0, "explanation": "Depth of focus, the range in front of/behind the retina over which the image still looks sharp (image-side). Hint: depth of FOCUS = image-side tolerance; depth of FIELD = object-side."}'),
  ('84285b85-1p','{"options": ["A 70-year-old patient with advanced presbyopia", "A 25-year-old hyperopic patient with active accommodation", "A patient with dense unilateral cataract", "A patient with no light perception in one eye"], "correct": 1, "explanation": "The 25-year-old hyperope with active accommodation benefits most from binocular balancing (equalizing accommodation between eyes). Hint: balancing matters where accommodation is active, so a young hyperope, not a presbyope or one-eyed patient."}'),
  ('a3cb0850-30','{"options": ["Examiner overestimates interpupillary distance.", "Accommodation may not be fully relaxed, resulting in an inaccurate measurement of refractive error.", "Examiner observes neutral motion immediately.", "Retinoscope produces a scissors reflex."], "correct": 1, "explanation": "Accommodation may not be fully relaxed, giving an inaccurate (over-minused) result. Hint: lose distance fixation and accommodation creeps in, spoiling the retinoscopy."}'),
  ('94bcabd2-30','{"options": ["Increase plus power or reduce minus power.", "Increase minus power.", "Rotate cylinder axis.", "Add prism."], "correct": 0, "explanation": "Green clearer means the eye is over-minused, so ADD plus (or reduce minus). Hint: duochrome, Green clearer = add Plus (GRP: Green-Reduce-with-Plus)."}'),
  ('fef05754-28','{"options": ["It maximizes retinal magnification.", "It eliminates the need for pupil dilation.", "Light rays are essentially parallel, requiring minimal accommodation.", "It provides better color discrimination."], "correct": 2, "explanation": "At 6 m (20 ft) light rays are essentially parallel, so accommodation is nearly relaxed for a true distance measure. Hint: 20 feet is ''optical infinity'', minimal accommodation needed."}'),
  ('234d8e6c-2d','{"options": ["Emmetropia", "Astigmatism", "Muscular imbalance", "Hyperopia"], "correct": 2, "explanation": "Muscular imbalance, when binocular acuity is WORSE than each eye alone, a binocular/motor problem (interference) is suspected. Hint: binocular < monocular = a binocular interference (muscle imbalance/suppression)."}'),
  ('620a89ea-2t','{"options": ["Vertically", "Horizontally", "Obliquely at 45°", "The orientation is unimportant"], "correct": 0, "explanation": "To scope the VERTICAL meridian, align the streak VERTICALLY (and sweep horizontally). Hint: the streak is aligned WITH the meridian you are neutralizing."}'),
  ('da10948d-23','{"options": ["-1.25 D ATR", "-1.25 D WTR", "-2.25 D WTR", "-2.25 D ATR"], "correct": 1, "explanation": "Astigmatism = 43.25 minus 42.00 = 1.25 D, steeper vertically (at 90) = WITH-the-rule; as minus cyl, -1.25 D WTR. Hint: steeper vertical meridian = WTR; steep horizontal = ATR."}'),
  ('765c72f3-3y','{"options": ["Yes, because the fusional reserve is greater than the phoria.", "Yes, because 10∆ is greater than twice the phoria.", "No, because the compensating fusional reserve should be at least 12∆.", "No, because Sheard''s Criterion applies only to esophoria."], "correct": 2, "explanation": "No, Sheard''s wants the compensating fusional reserve to be at least TWICE the phoria (2 x 6 = 12 prism), but only 10 is available. Hint: Sheard''s rule of thumb, reserve >= twice the phoria."}'),
  ('470a3f58-16','{"options": ["Before objective refraction", "Before monocular subjective refraction", "After monocular subjective refraction and before binocular testing", "After prescribing spectacles"], "correct": 2, "explanation": "Binocular balancing comes AFTER monocular subjective refraction and BEFORE binocular testing. Hint: balance the two eyes once each is individually refined, before binocular steps."}'),
  ('f0289934-20','{"options": ["Myopia", "Hyperopia", "Mixed astigmatism only", "Emmetropia"], "correct": 1, "explanation": "''With'' motion is seen in hyperopia (and in emmetropia/low myopia less than the working-distance value). Hint: WITH motion at the usual working distance = hyperope (add plus)."}'),
  ('89de68e2-23','{"options": ["Minimum separable", "Minimum visible", "Minimum cognoscible (legible)", "Vernier acuity"], "correct": 2, "explanation": "Minimum cognoscible (legible) acuity, the threshold for identifying/recognizing letters. Hint: reCOGNizing letters = cognoscible; just detecting a gap = separable."}'),
  ('5aa0b201-44','{"options": ["Add plus power to the eye viewing the clearer image until both images appear equally clear.", "Add minus power to the eye viewing the blurrier image.", "Increase cylinder power in both eyes.", "Repeat retinoscopy immediately."], "correct": 0, "explanation": "Add PLUS to the eye seeing the CLEARER image until both blur equally (fog the sharper eye down to match). Hint: in balancing, blur the better eye with plus until the two are equal."}'),
  ('dc3e66b2-36','{"options": ["Prescribe the stronger minus lens.", "Increase the lens change to 1.00 D.", "Record the current result and proceed to the next step of refraction.", "Begin retinoscopy again."], "correct": 2, "explanation": "If both choices look identical, record the current result and move on (you are at the endpoint). Hint: ''no preference'' = you have reached the endpoint; do not push more minus."}'),
  ('e65697d4-36','{"options": ["Optic disc", "Peripheral retina", "Fovea", "Ora serrata"], "correct": 2, "explanation": "The fovea gives the highest acuity (densest cones). Hint: cone-packed fovea = sharpest vision."}'),
  ('fba4c9b5-12','{"options": ["Strongest minus lens providing 20/20 vision", "Weakest plus lens providing acceptable vision", "Maximum plus (or minimum minus) lens that gives the best visual acuity", "Plano correction for all patients"], "correct": 2, "explanation": "Maximum plus (or minimum minus) that still gives best acuity, to avoid stimulating accommodation. Hint: give the LEAST minus that reaches best VA (max-plus principle)."}'),
  ('5aba108d-1f','{"options": ["Cylinder → Sphere → Binocular Balance → Sphere", "Sphere → Cylinder → Sphere → Binocular Balance", "Binocular Balance → Sphere → Cylinder → Duochrome", "Sphere → Binocular Balance → Cylinder → Sphere"], "correct": 1, "explanation": "Sphere -> Cylinder -> Sphere -> Binocular Balance is the subjective refraction order. Hint: refine sphere, then cylinder, re-check sphere, then balance the eyes."}'),
  ('9a13f303-21','{"options": ["Floaters", "Blur or fluctuating vision at near point", "Sudden vision loss", "Photophobia only"], "correct": 1, "explanation": "Blur or fluctuating vision at near is the classic accommodative-deficiency symptom. Hint: near blur that comes and goes = accommodation struggling."}'),
  ('a6366e18-3d','{"options": ["Spherical ametropia", "Emmetropia", "Astigmatism", "Presbyopia"], "correct": 2, "explanation": "Astigmatism, a reflex that differs in thickness between meridians and shows skew (break) is astigmatic. Hint: skew/break and unequal thickness across meridians = astigmatism."}'),
  ('33d5b148-2s','{"options": ["Astigmatism is present.", "Patient has myopia.", "No significant astigmatism is present.", "Cylinder axis is incorrect."], "correct": 2, "explanation": "No significant astigmatism, when all astigmatic-dial lines look equally black, the meridians are balanced. Hint: all lines equal on the clock dial = no meaningful cylinder."}'),
  ('0937b889-2u','{"options": ["Large aperture", "Slit beam", "Micro-spot (small aperture)", "Grid aperture"], "correct": 2, "explanation": "The micro-spot (small) aperture is best for a small, undilated pupil. Hint: small pupil = small aperture (micro-spot) to get light in cleanly."}'),
  ('a121d7e2-2t','{"options": ["Patient is presbyopic.", "Patient is accommodating during the examination.", "Patient has cataracts.", "Patient has anisometropia."], "correct": 1, "explanation": "The patient is accommodating during the exam (extra minus is being ''eaten'' by accommodation). Hint: accepting more minus with no VA gain = active accommodation."}'),
  ('43968695-3m','{"options": ["Minimum cognoscible", "Minimum separable", "Detection acuity", "Localization acuity"], "correct": 1, "explanation": "Minimum separable acuity, resolving that two lines are separate (a resolution task), distinct from recognizing letters. Hint: telling two lines apart = separable (resolution)."}'),
  ('f3b8ec63-4m','{"options": ["Positive Relative Accommodation", "Negative Relative Accommodation", "Positive Fusional Reserve", "Negative Fusional Reserve"], "correct": 2, "explanation": "Positive fusional reserve (PFR), it measures the convergence reserve that compensates a near EXOphoria. Hint: exo needs CONVERGENCE reserve = positive fusional (vergence) reserve."}'),
  ('856a81c9-2h','{"options": ["+1.00 D", "+0.50 D", "+1.50 D", "+2.00 D"], "correct": 1, "explanation": "Net = gross minus working-distance dioptric value = +2.50 minus 2.00 (for 50 cm) = +0.50 D. Hint: subtract the working-distance lens (1/0.5 m = 2 D) from the gross."}'),
  ('78510dfa-1z','{"options": ["It determines distance visual acuity.", "It influences the accommodative demand required for near tasks.", "It measures interpupillary distance.", "It determines cylinder axis."], "correct": 1, "explanation": "Working distance sets the accommodative DEMAND, so it dictates the near add. Hint: how close they work = how much add they need."}'),
  ('f99e68ae-12','{"options": ["Determine refractive error while fixating at distance", "Determine refractive state while fixating on a near object", "Measure intraocular pressure", "Evaluate color vision"], "correct": 1, "explanation": "Dynamic retinoscopy measures the refractive state while the patient fixates a NEAR target (accommodation active). Hint: DYNAMIC = eye focusing at NEAR (lag/lead of accommodation)."}'),
  ('1c245fbd-29','{"options": ["Magnification and field of view both increase.", "Magnification increases while field of view decreases.", "Magnification decreases while field of view increases.", "Neither changes."], "correct": 2, "explanation": "A stronger condensing lens DECREASES magnification but INCREASES field of view in indirect ophthalmoscopy. Hint: more diopters on the condensing lens = smaller, wider image."}'),
  ('ccf16db2-3b','{"options": ["Near addition is too weak for closer working distances.", "Patient has excessive minus power.", "Patient requires stronger distance prescription.", "Patient has hyperopia."], "correct": 0, "explanation": "The near add is too weak for the closer 25 cm distance (a stronger add or shorter chosen distance is needed). Hint: closer than the add is set for = it runs out of plus, so it blurs."}'),
  ('015dc54e-2u','{"options": ["Minus lenses", "Plus lenses", "Cylindrical lenses", "Prism lenses"], "correct": 1, "explanation": "Introduce PLUS lenses to neutralize a ''with'' motion in MEM (the with motion reflects an accommodative lag). Hint: with motion = add plus to reach neutral."}'),
  ('70b5cb6d-3g','{"options": ["Decrease minus cylinder by 0.25 D.", "Increase minus cylinder in 0.25 D steps until equality is achieved.", "Increase sphere by +1.00 D.", "Rotate cylinder axis by 20°."], "correct": 1, "explanation": "Increase minus cylinder in 0.25 D steps until the two flip positions look equal (a consistent preference means more cyl is needed). Hint: JCC power step, keep adding minus cyl until no preference."}'),
  ('1bda57ee-2g','{"options": ["Downward", "Upward", "To the right", "It does not move"], "correct": 1, "explanation": "With a plane mirror, tilting it downward makes the apparent source of light appear to move upward (the virtual image swings opposite to the tilt). VERIFY, mirror-direction items are easy to reverse. Hint: plane mirror, apparent source moves OPPOSITE the tilt; concave mirror, same direction."}'),
  ('eb6709bf-2c','{"options": ["1.00 D", "0.50 D", "0.25 D", "0.75 D"], "correct": 2, "explanation": "Spherical power is refined in 0.25 D steps. Hint: fine refraction moves in quarter-diopter clicks."}'),
  ('be46fb21-2x','{"options": ["Accommodative demand has been successfully equalized between the two eyes.", "Patient requires additional minus power in both eyes.", "Cylinder axis should be refined again.", "Objective refraction was inaccurate."], "correct": 0, "explanation": "Accommodative demand has been successfully equalized between the two eyes (the aim of balancing). Hint: equal clarity, unchanged binocular VA = balance achieved."}'),
  ('dc97838d-14','{"options": ["Dynamic retinoscopy findings", "Cycloplegic refraction only", "The objective refraction result", "Keratometry readings"], "correct": 2, "explanation": "Subjective refraction starts from the OBJECTIVE refraction (retinoscopy/autorefractor) result. Hint: objective findings are the launch pad for subjective refinement."}'),
  ('26e34385-1j','{"options": ["Improve contrast sensitivity", "Relax accommodation by placing the image in front of the retina", "Determine cylinder axis", "Create an artificially myopic condition"], "correct": 1, "explanation": "Fogging relaxes accommodation by placing the image IN FRONT of the retina (artificial myopia). Hint: fog = add plus = push focus forward = relax accommodation."}'),
  ('c0ec4119-t','{"options": ["Can see at 60 feet what a normal person sees at 20 feet.", "Can see at 20 feet what a normal person sees at 60 feet.", "Has normal vision.", "Has no refractive error."], "correct": 1, "explanation": "20/60 means the patient sees at 20 ft what a normal eye sees at 60 ft. Hint: Snellen, your distance over the normal person''s distance for that line."}'),
  ('15e453c7-39','{"options": ["Fogging method", "Prism dissociation method", "Occlusion method", "Bichrome method"], "correct": 1, "explanation": "The prism dissociation method separates the two eyes'' images with a prism while both eyes stay open. Hint: prism splits the images vertically so each eye''s target is seen separately."}'),
  ('781a1710-3y','{"options": ["Increase minus power for distance.", "Prescribe an appropriate near addition after evaluating near visual needs.", "Repeat retinoscopy only.", "Prescribe prism correction immediately."], "correct": 1, "explanation": "Prescribe an appropriate near addition after assessing near needs, classic early presbyopia. Hint: 48 + near strain + reduced amplitude = time for a near add."}'),
  ('f916747d-38','{"options": ["Patient may be over-accommodating.", "Patient has complete cycloplegia.", "Patient has perfect emmetropia.", "Patient requires immediate prism correction."], "correct": 0, "explanation": "The patient may be over-accommodating (accepting minus without a real VA gain). Hint: chasing minus with no VA benefit = latent accommodation."}'),
  ('cf484650-2y','{"options": ["Add +0.25 D sphere", "Add −0.25 D sphere", "Add +0.50 D sphere", "No spherical change is required"], "correct": 0, "explanation": "Add +0.25 D sphere, adding -0.50 D cylinder shifts the circle of least confusion, so move the sphere HALF the cyl in the opposite sign to re-center it on the retina. Hint: for every -0.50 cyl added, add +0.25 sphere to keep Sturm centered."}'),
  ('67c9194e-21','{"options": ["Standard Snellen chart", "ETDRS chart", "Lea Symbols", "Jaeger chart"], "correct": 2, "explanation": "Lea Symbols, ideal for a cooperative 3-year-old who cannot yet read letters. Hint: preliterate child = picture/symbol optotypes (Lea)."}'),
  ('f0e5f126-2f','{"options": ["Retinal mosaic", "Lateral illumination and glare", "Spectral nature of light", "Lid pressure"], "correct": 1, "explanation": "Lateral illumination and glare from oncoming headlights scatters light and blurs vision. Hint: night-driving headlight blur = glare/scatter."}'),
  ('5e24a693-1i','{"options": ["1.00 D", "2.00 D", "2.50 D", "4.00 D"], "correct": 2, "explanation": "At 40 cm (16 in) the accommodative stimulus is 1/0.40 = 2.50 D. Hint: 40 cm = 2.50 D of accommodative demand."}'),
  ('3c495544-22','{"options": ["Alphabetically", "In the order mentioned by the patient", "From highest to lowest concern or medical risk", "By duration of symptoms"], "correct": 2, "explanation": "Document multiple complaints from highest to lowest concern/medical risk (most urgent first). Hint: triage the chief complaints by severity/risk, not by order spoken."}'),
  ('a483442a-28','{"options": ["Improve accommodation", "Provide strongest correction possible", "Achieve best visual acuity while minimizing accommodative effort", "Eliminate astigmatism completely"], "correct": 2, "explanation": "Max-plus/min-minus gives best acuity while minimizing accommodative effort (avoids over-minus). Hint: least minus for best VA = comfortable, non-accommodating correction."}'),
  ('a9bbd7a1-3t','{"options": ["Over-minus prescription", "Over-plus prescription", "Excessive cylinder correction", "Incorrect prism prescription"], "correct": 0, "explanation": "Persistent accommodation leads to an OVER-MINUS prescription (accommodation absorbs extra minus). Hint: uncontrolled accommodation = too much minus in the final Rx."}'),
  ('f8a851e9-36','{"options": ["Accommodative deficiency", "Vergence deficiency", "Cataract", "Ocular allergy"], "correct": 1, "explanation": "Vergence deficiency, jumping print and closing one eye at near point to a binocular/vergence problem (e.g., convergence insufficiency). Hint: words jump + covering an eye at near = vergence trouble."}'),
  ('73a4c2f3-1e','{"options": ["Cycloplegia must be induced.", "Accurate monocular subjective refraction should be completed.", "Near vision testing must be finished.", "Color vision testing should be performed first."], "correct": 1, "explanation": "An accurate monocular subjective refraction must be completed before binocular balancing. Hint: balance the eyes only after each is individually refined."}'),
  ('7bb1edd0-37','{"options": ["Cylinder power should be increased.", "Cylinder axis is correct.", "Patient has hyperopia.", "Sphere should be increased."], "correct": 1, "explanation": "If the two flipped JCC positions look equal, the cylinder AXIS (or endpoint) is correct. Hint: ''no preference'' on the cross cylinder = you are at the correct setting."}'),
  ('db174a88-13','{"options": ["Provide highest possible plus power.", "Prescribe minimum plus power that allows comfortable, sustained near vision.", "Maximize distance visual acuity.", "Eliminate binocular vision testing."], "correct": 1, "explanation": "Prescribe the MINIMUM plus that gives comfortable, sustained near vision (preserve range). Hint: give the least add that works, to keep the near range wide."}'),
  ('61ddbd8f-20','{"options": ["Determines educational background", "Many systemic diseases may produce ocular manifestations affecting vision.", "Replaces need for ocular examination.", "Determines occupation."], "correct": 1, "explanation": "Many systemic diseases (diabetes, hypertension, thyroid) show ocular effects, so medical history matters. Hint: the eye mirrors the body, so systemic history guides the exam."}'),
  ('03673118-1c','{"options": ["Vertical phoria", "Lateral phoria", "Positive fusional reserve", "Amplitude of accommodation"], "correct": 1, "explanation": "A VERTICAL dissociating prism (splitting images up/down) is used to measure LATERAL (horizontal) phoria (von Graefe). Hint: dissociate vertically to measure the horizontal phoria (and vice versa)."}'),
  ('4fc01885-2i','{"options": ["Diabetes permanently weakens extraocular muscles.", "Blood sugar fluctuations can alter refractive power of the eye.", "Diabetes causes immediate cataract formation in all patients.", "Diabetes only affects peripheral vision."], "correct": 1, "explanation": "Blood-sugar swings change the lens''s refractive power, causing fluctuating prescriptions in diabetics. Hint: unstable glucose = unstable lens = shifting refraction."}'),
  ('ecc1a6a1-2b','{"options": ["Cataract", "Macular degeneration", "Uncorrected refractive error", "Optic nerve disease"], "correct": 2, "explanation": "Uncorrected refractive error, a pinhole that improves 20/80 to 20/20 confirms a refractive (optical) cause. Hint: pinhole improves = refractive; pinhole fails = pathology."}'),
  ('bcf310c4-2j','{"options": ["Refractive correction is adequate.", "Patient has severe myopia.", "Patient is malingering.", "Patient has accommodative insufficiency."], "correct": 0, "explanation": "Refractive correction is adequate, a pinhole that does not improve (and slightly worsens) 20/20 means optics are already optimized. Hint: pinhole cannot beat an already-corrected 20/20, it only cuts light."}'),
  ('4506983c-1n','{"options": ["Patients who can easily perform subjective refraction", "Only adult patients with myopia", "Non-verbal, pediatric, and geriatric patients", "Patients undergoing contact lens fitting only"], "correct": 2, "explanation": "Static retinoscopy helps most with non-verbal, pediatric, and geriatric patients (an objective method needing no responses). Hint: objective retinoscopy shines when the patient cannot answer reliably."}'),
  ('ca7df8e3-3v','{"options": ["Larger pupil allows more light but also increases optical aberrations, reducing visual acuity.", "Larger pupil improves depth of focus.", "Large pupils prevent light from reaching retina.", "Pupil size has no effect on visual acuity."], "correct": 0, "explanation": "A large (7 mm) pupil lets in more light but also more optical aberrations, so clarity can drop despite a correct Rx. Hint: big pupil = more aberrations (and less depth of focus) = softer image."}'),
  ('b9e39e6d-36','{"options": ["Observation alone", "Third-party information from caregivers", "Questionnaire only", "Electronic health record only"], "correct": 1, "explanation": "Third-party information from caregivers is most useful when the patient cannot communicate well. Hint: can''t self-report = ask the caregivers."}'),
  ('bccf4199-1z','{"options": ["Using open-ended questions", "Maintaining eye contact", "Asking leading questions", "Showing empathy"], "correct": 2, "explanation": "Avoid LEADING questions (they bias the answer). Open-ended questions, eye contact, and empathy are good. Hint: leading questions plant answers, use open-ended ones instead."}'),
  ('4a968ffd-1a','{"options": ["Improve distance vision only", "Compensate for reduced accommodative ability during near tasks", "Correct astigmatism", "Improve binocular alignment"], "correct": 1, "explanation": "A near add compensates for reduced accommodative ability during near tasks (presbyopia). Hint: the add replaces the accommodation the lens can no longer supply."}'),
  ('69b238af-2f','{"options": ["Cataract", "Amblyopia", "Glaucoma", "Keratitis"], "correct": 1, "explanation": "Amblyopia, unequal acuity (20/80 vs 20/20) in a child with healthy eyes. Hint: reduced VA with a normal eye exam in a child = amblyopia."}'),
  ('f0579fbe-33','{"options": ["Color vision", "Peripheral vision", "Depth perception", "Dark adaptation"], "correct": 2, "explanation": "Depth perception (stereopsis), amblyopes have poor binocular depth judgment (as in catching a ball). Hint: judging distance to a moving ball = stereopsis, weak in amblyopia."}'),
  ('5afd57e9-30','{"options": ["Deprivation", "Strabismic", "Organic", "Toxic"], "correct": 1, "explanation": "Strabismic amblyopia, a constant unilateral esotropia suppresses the deviating eye. Hint: constant one-eyed turn -> suppression -> strabismic amblyopia."}'),
  ('aae432d7-1z','{"options": ["Strabismic", "Deprivation", "Refractive (anisometropic)", "Organic"], "correct": 2, "explanation": "Refractive (anisometropic) amblyopia, a large hyperopic difference (+1.00 vs +6.00) blurs the +6.00 eye chronically. Hint: big unequal refractive error (no turn) = anisometropic amblyopia."}'),
  ('a9a6b3dd-2n','{"options": ["Strabismic", "Functional", "Deprivation", "Refractive"], "correct": 2, "explanation": "Deprivation amblyopia, a congenital cataract blocks form vision, the most severe type. Hint: something blocks the image (cataract/ptosis) = deprivation amblyopia."}'),
  ('b9b78f59-2k','{"options": ["Vision therapy", "Occlusion therapy", "Correcting refractive error", "Perceptual learning"], "correct": 2, "explanation": "Correcting the refractive error is the FIRST clinical goal (a clear retinal image) before patching or therapy. Hint: glasses first, then occlusion/therapy."}'),
  ('a3e3d756-2i','{"options": ["Improve stereopsis first", "Present a clear retinal image", "Train accommodation", "Reduce suppression immediately"], "correct": 1, "explanation": "Glasses are given first to present a CLEAR retinal image (the foundation for any further treatment). Hint: you cannot train an eye that still sees a blurred image, correct it first."}'),
  ('5aff0a99-1o','{"options": ["Improve color vision", "Encourage use of amblyopic eye", "Relax accommodation", "Improve peripheral vision"], "correct": 1, "explanation": "Patching the DOMINANT eye forces use of (and strengthens) the amblyopic eye. Hint: cover the good eye to make the lazy eye work."}'),
  ('23ea0e5f-1h','{"options": ["Brock string", "Vision therapy", "Occlusion", "Aperture rule trainer"], "correct": 2, "explanation": "Occlusion (patching) is a PASSIVE amblyopia treatment. Hint: patching just forces use (passive); Brock string/aperture-rule are active therapy."}'),
  ('f3a48bab-3l','{"options": ["Penalization", "Passive therapy", "Active therapy", "Surgical therapy"], "correct": 2, "explanation": "Active therapy, supervised, feedback-driven visual tasks with active patient involvement. Hint: patient actively engaged with feedback = active vision therapy."}'),
  ('26b471a9-4q','{"options": ["Monocular", "MFBF", "Bi-ocular", "Binocular"], "correct": 1, "explanation": "MFBF (Monocular Fixation in a Binocular Field), one eye works while both stay open and binocularly aware. Hint: MFBF = one eye trained, both eyes open, breaking suppression."}'),
  ('b31c96af-2l','{"options": ["Monocular", "MFBF", "Bi-ocular", "Binocular"], "correct": 3, "explanation": "The binocular stage, both eyes as a single system. Hint: unified two-eye work = binocular stage."}'),
  ('7175bf24-2y','{"options": ["Strengthening extraocular muscles", "Neuroplasticity and visual learning", "Increasing corneal transparency", "Reducing intraocular pressure"], "correct": 1, "explanation": "Neuroplasticity and visual learning drive vision-therapy gains (not muscle strengthening). Hint: VT rewires the brain (plasticity), it does not bulk up muscles."}'),
  ('af44d465-2z','{"options": ["Anti-suppression therapy", "Cataract surgery", "Color vision training", "Tonometry exercises"], "correct": 0, "explanation": "Anti-suppression therapy is added when suppression is present. Hint: suppression -> anti-suppression training."}'),
  ('f16e3e87-2n','{"options": ["Worsening binocular function", "Improved binocular vision", "Increased suppression", "Reduced accommodation"], "correct": 1, "explanation": "Improved binocular vision, stereopsis sharpening from 3600 to 100 arcsec is a big gain. Hint: fewer arc-seconds = better stereo = improved binocularity."}'),
  ('da3fd3f1-29','{"options": ["Syntonics", "Pleoptics", "CAM Vision Stimulator", "Pegboard Stimulator"], "correct": 2, "explanation": "The CAM vision stimulator uses rotating high-contrast gratings to stimulate the amblyopic eye. Hint: rotating stripe gratings = CAM stimulator."}'),
  ('00ef4c69-2r','{"options": ["Improve peripheral fusion", "Improve foveal function", "Increase pupil size", "Reduce accommodation"], "correct": 1, "explanation": "Improve foveal function, pleoptics dazzles the peripheral retina while shielding the fovea to restore central (foveal) fixation. Hint: pleoptics protects the fovea and bleaches the periphery to re-center fixation."}'),
  ('7dc45d0d-2h','{"options": ["Pleoptics", "Syntonics Phototherapy", "Penalization", "CAM Therapy"], "correct": 1, "explanation": "Syntonics (phototherapy) uses selected colored (red/orange) light to treat suppression/strabismus in these regimens. VERIFY, colored-filter therapies overlap in naming. Hint: therapeutic colored light = syntonic phototherapy."}'),
  ('e7e97766-2r','{"options": ["Optical magnification", "Brain plasticity", "Cycloplegia", "Peripheral adaptation"], "correct": 1, "explanation": "Brain plasticity underlies therapeutic video-game (dichoptic) amblyopia training. Hint: game-based training works by neuroplasticity."}'),
  ('574fa592-3k','{"options": ["Increased refractive error", "Persistence of suppression", "Improved visual acuity and binocular function", "Development of strabismus"], "correct": 2, "explanation": "Improved visual acuity and binocular function, near-equal acuity, no suppression, and 60 arcsec stereo is a successful outcome. Hint: good VA + fusion + fine stereo = success."}'),
  ('7d48616e-1y','{"options": ["Brock string", "Vision therapy", "Occlusion", "Aperture rule trainer"], "correct": 2, "explanation": "Occlusion (patching) is the PASSIVE treatment. Hint: patching = passive; the string/trainer tasks = active."}'),
  ('a2afeb4e-3q','{"options": ["Penalization", "Passive therapy", "Active therapy", "Surgical therapy"], "correct": 2, "explanation": "Active therapy, supervised, feedback-driven tasks. Hint: engaged patient + feedback = active."}'),
  ('cd278b36-3m','{"options": ["Monocular", "MFBF", "Bi-ocular", "Binocular"], "correct": 1, "explanation": "MFBF stage, one eye used with both eyes open and binocularly aware. Hint: MFBF = one-eye work in a two-eye field."}'),
  ('feff77fd-26','{"options": ["Strengthening extraocular muscles", "Neuroplasticity and visual learning", "Increasing corneal transparency", "Reducing intraocular pressure"], "correct": 1, "explanation": "Neuroplasticity and visual learning, the mechanism of VT. Hint: VT = brain rewiring, not muscle building."}'),
  ('88d3a460-r','{"options": ["The steeper the curvature, the greater the refractive power.", "The shorter the radius of curvature, the flatter the surface.", "The flatter the curvature, the lesser the bending of light.", "None of the above"], "correct": 1, "explanation": "NOT true: ''shorter radius = flatter surface'' is false (shorter radius = steeper). Hint: same trap as Q108, short radius = steep, not flat."}'),
  ('25336829-2l','{"options": ["Symmetric, homologous", "Symmetric, heterologous", "Asymmetric, homonymous", "Asymmetric, heteronymous"], "correct": 0, "explanation": "Symmetric, homologous, both cylinder axes are at 90 (mirror-symmetric) and both eyes are the same type. Hint: matching axes + same type in both eyes = symmetric and homologous."}'),
  ('143949fc-28','{"options": ["With-the-rule astigmatism", "Against-the-rule astigmatism", "Oblique astigmatism", "Physiologic astigmatism"], "correct": 0, "explanation": "With-the-rule astigmatism has the greatest power at/near the VERTICAL meridian. Hint: WTR = steep vertical meridian (like the lids squeezing the cornea)."}'),
  ('b4d2ce01-1i','{"options": ["Blur", "Near target", "Light", "None of the above"], "correct": 0, "explanation": "Blur is the primary stimulus to accommodation (retinal defocus drives it). Hint: a blurred retinal image is the trigger to accommodate."}'),
  ('9f0686e7-3y','{"options": ["Emmetropia", "Myopia", "Hyperopia", "Astigmatism"], "correct": 2, "explanation": "Hyperopia, with accommodation relaxed the rays converge to a focus BEHIND the retina. Hint: focus behind the retina (under-powered eye) = hyperopia."}'),
  ('0d2343ab-1s','{"options": ["Shallow depth of anterior chamber", "Flatter corneal curvature", "Shorter radius of curvature", "Old age"], "correct": 2, "explanation": "Shorter radius of curvature is the EXCEPT, it STEEPENS the cornea (more power) and causes MYOPIA, not hyperopia. The others (shallow AC, flat cornea, old age) trend hyperopic. Hint: short radius = steep = myopia; flat = hyperopia."}'),
  ('01c1f562-1r','{"options": ["Complete blindness of the right eye", "Normal direct and consensual light reflex if light is presented on the left eye", "Sluggish pupillary response if light is presented on the left eye", "No direct and consensual light reflex if light is presented on the affected eye"], "correct": 2, "explanation": "NOT true: the response to light on the LEFT (unaffected) eye is NORMAL, not ''sluggish'' (left afferent is intact, so both pupils react briskly). Hint: with a right optic-nerve lesion, lighting the good left eye gives normal, brisk direct and consensual responses."}'),
  ('f6789be7-1o','{"options": ["A lesion on the lateral geniculate body will not have an effect on the pupillary light reflex", "Normal direct and consensual light reflex is observed if light is presented on the opposite eye of the eye with a lesion on the optic nerve", "A normal response on direct and consensual light reflex is observed regardless where light is presented if the lesion lies on the crossed optic chiasma", "No direct and consensual light reflex is observed if light is presented on the eye with a lesion on the optic nerve"], "correct": 2, "explanation": "NOT true: a crossed-chiasm lesion does NOT leave responses ''normal regardless where light is presented'', damaged crossing fibers can blunt the reflex. (LGB lesions truly spare the pupil, since pupil fibers exit before the LGB.) VERIFY. Hint: pupil fibers leave before the LGB, so LGB lesions spare the reflex; chiasm crossing-fiber lesions need not be fully normal."}'),
  ('2df41d05-28','{"options": ["Simple myopic astigmatism", "Compound myopic astigmatism", "Simple hyperopic astigmatism", "Compound myopic astigmatism"], "correct": 1, "explanation": "Compound myopic astigmatism, BOTH focal lines lie in front of the retina. Hint: both foci in front = compound MYOPIC astigmatism."}'),
  ('c693da20-2m','{"options": ["Symmetric, homologous", "Symmetric, heterologous", "Asymmetric, homonymous", "Asymmetric, heteronymous"], "correct": 0, "explanation": "Symmetric, homologous, axes 170 and 10 are mirror images (sum 180) and both eyes are the same (WTR-type). VERIFY the symmetric/homologous labeling your key uses. Hint: mirror-image axes (sum to 180) = symmetric; same type both eyes = homologous."}'),
  ('4b5d912f-1x','{"options": ["Shallow depth of anterior chamber", "Flatter corneal curvature", "Shorter radius of curvature", "Old age"], "correct": 2, "explanation": "Shorter radius of curvature is the EXCEPT (it steepens the cornea and causes myopia, not hyperopia). Hint: same as Q115, short radius = steep = myopia."}'),
  ('f2355434-1j','{"options": ["Miosis", "Contraction of ciliary muscles", "Convergence of eyeball", "None of the above"], "correct": 3, "explanation": "None of the above, miosis, ciliary contraction, and convergence ALL occur during the near reflex, so there is no exception. Hint: the near triad IS miosis + ciliary contraction + convergence, all happen."}'),
  ('9f12b88e-22','{"options": ["With-the-rule, Mixed Astigmatism", "With-the-rule, Simple Myopic Astigmatism", "Against-the-rule, Mixed Astigmatism", "Against-the-rule, Simple Myopic Astigmatism"], "correct": 3, "explanation": "Against-the-rule, simple myopic astigmatism, -1.00 +1.00 x180 gives 0 (at 90) and -1.00 (at 180): one meridian plano, one myopic, with the minus meridian horizontal (ATR). Hint: one plano meridian = SIMPLE; minus power horizontal = ATR."}'),
  ('ea44bebe-16','{"options": ["WTR astigmatism has the greatest power along the horizontal meridian", "Symmetric astigmatism exists when the axis meridians of both eyes is equal to 180", "Heteronymous astigmatism occurs if both eyes are asymmetric, having one eye WTR and the other ATR", "None of the above"], "correct": 0, "explanation": "NOT true: WTR astigmatism has its greatest power along the VERTICAL meridian, not the horizontal. Hint: WTR = steep/powerful VERTICAL meridian."}'),
  ('deae65ac-22','{"options": ["Congenital myopia", "Axial myopia", "Induced myopia", "Pseudomyopia"], "correct": 2, "explanation": "Induced (acquired) myopia is linked to nuclear sclerosis (index myopia from the denser lens). Hint: nuclear cataract = index-induced myopia (''second sight'')."}'),
  ('73c2f48d-4f','{"options": ["True axial myopia", "Refractive myopia due to corneal steepening", "Accommodative spasm mimicking myopia", "Early lenticular sclerosis"], "correct": 2, "explanation": "Accommodative spasm (pseudomyopia), retinoscopy reads -3.00 but cycloplegia reveals +0.25 with a NORMAL axial length, so the ''myopia'' is accommodative. Hint: minus on retinoscopy but plus under cycloplegia + normal AL = pseudomyopia (spasm)."}'),
  ('d36b1a84-v','{"options": ["Myopia caused by increased refractive power of cornea", "Myopia resulting from a short axial length of eye", "Myopia due to elongation of the axial length of the eyeball", "Myopia secondary to lens opacities"], "correct": 2, "explanation": "Axial myopia = myopia from ELONGATION of the axial length of the eye. Hint: axial = long eye; refractive = too much corneal/lens power."}'),
  ('e54c7771-2v','{"options": ["High hyperopia", "Low myopia", "High myopia", "Mixed astigmatism"], "correct": 0, "explanation": "High hyperopia, a dull, slow ''with'' reflex in a dim room suggests a large hyperopic error. Hint: dim, slow, hard-to-neutralize WITH motion = high hyperopia."}'),
  ('ca7f9e61-3b','{"options": ["Inhibit elongation=", "Promote axial elongation=", "Cause lenticular thickening=", "Stabilize refraction="], "correct": 1, "explanation": "Peripheral HYPEROPIC defocus (peripheral image behind the retina) is hypothesized to PROMOTE axial ELONGATION (the eye grows toward the defocused image) — the rationale behind peripheral-plus myopia-control optics that instead impose peripheral MYOPIC defocus. Hyperopic peripheral defocus = grow; myopic peripheral defocus = slow."}'),
  ('4736a9dc-2s','{"options": ["Increased accommodation improves emmetropization", "Hyperopic defocus decreases axial elongation", "Myopic defocus at the retina slows growth", "Increased outdoor exposure reduces progression"], "correct": 2, "explanation": "Myopic defocus at the retina was believed to slow growth, the rationale once used to justify undercorrection (though undercorrection actually speeds progression). Hint: the (flawed) idea was that leftover myopic defocus would brake the eye."}'),
  ('8c084830-6s','{"options": ["Stable emmetropization; follow-up in 2 years", "Myopia onset confirmed; monitor axial length every 6 months", "Findings are typical; no further testing needed", "Astigmatism is the main concern; initiate keratometry monitoring"], "correct": 1, "explanation": "Myopia onset confirmed; monitor axial length every 6 months, a shift from +0.25 to -0.50 with AL growth (23.4 to 24.3 mm) plus heavy near work and little outdoor time. Hint: crossing into minus with rapid AL growth = new myopia, track AL closely."}'),
  ('a76f6357-1x','{"options": ["Myope", "Pre-myope", "Progressive Myopia", "High Hyperopia"], "correct": 1, "explanation": "Pre-myope, +0.75 D at age 6 is below the age-expected hyperopic reserve, a risk marker for myopia. Hint: a 6-year-old with only +0.75 has ''spent'' too much of the hyperopic buffer, pre-myopia."}'),
  ('0b28592a-1l','{"options": ["European", "Caucasian", "African", "Asian"], "correct": 3, "explanation": "Asian ethnicity carries the highest myopia risk/prevalence. Hint: East/Southeast Asia has the highest myopia rates."}'),
  ('ff998dc5-1z','{"options": ["Reverse curve/", "Treatment zone", "Central zone//", "Alignment curve/"], "correct": 0, "explanation": "In an ortho-K lens, the REVERSE CURVE (the steep zone just outside the flatter central treatment zone) creates the MID-PERIPHERAL tear-film pooling and the myopic-defocus ring that drives epithelial redistribution. Central/treatment zone flattens for distance; alignment curve centers. Reverse curve = myopic-defocus/reshaping zone."}'),
  ('aa6c914e-1v','{"options": ["Nocturnal myopia", "Pseudomyopia", "Simple myopia", "Induced myopia"], "correct": 0, "explanation": "Nocturnal myopia, myopia that worsens in dim/low light (from a larger pupil and dark focus). Hint: myopia only in the dark = nocturnal myopia."}'),
  ('6ed96b32-1l','{"options": ["It leads the patient to become more hyperopic due to changes in axial length.", "It leads to myopia due to changes in eye anatomy and optical alignment.", "It can improve myopia by increasing focusing power of the eye.", "It can completely correct hyperopia without corrective lenses."], "correct": 0, "explanation": "Exophthalmos/proptosis (often a retrobulbar mass indenting the posterior pole) shortens the axial length and shifts the eye HYPEROPIC (with induced astigmatism). VERIFY, some presentations differ. Hint: a mass pushing the globe forward and flattening the back shortens the eye = hyperopic shift."}'),
  ('86a58c85-37','{"options": ["Emmetropization", "Accommodation", "Dynamic Refraction", "Phototransduction"], "correct": 0, "explanation": "Emmetropization, the process by which refractive components and axial length balance toward clear distance vision. Hint: the eye ''tuning itself'' toward emmetropia in development = emmetropization."}'),
  ('ab00459d-45','{"options": ["Vitreous Humor", "Tear Film", "Aqueous Humor", "Cornea"], "correct": 2, "explanation": "Aqueous humor nourishes the two avascular refractive elements (cornea and lens) while adding little refractive power itself. Hint: aqueous = the feeder of cornea and lens (minor optical role)."}'),
  ('c52d3267-1h','{"options": ["‘’A. Pupil/", "‘B. Cornea/", "‘C. Iris/", "‘D. crystalline lens/"], "correct": 2, "explanation": "The IRIS controls the amount of light entering the eye by varying the PUPIL size (the pupil is the aperture; the iris is the muscular diaphragm that sizes it). Cornea/lens refract; the iris is the variable aperture. Iris = the aperture-controlling diaphragm."}'),
  ('03879174-2e','{"options": ["Anterior surface of the lens/", "Posterior surface of the lens/", "Equatorial zone of the lens/", "Both anterior and posterior equally/"], "correct": 0, "explanation": "During accommodation the ANTERIOR lens surface steepens MOST (the anterior curvature changes far more than the posterior) as the lens rounds up — driving the increase in dioptric power. Helmholtz mechanism: zonules relax, lens (esp. anterior face) bulges. Anterior surface = greatest accommodative curvature change."}'),
  ('77b00536-23','{"options": ["Increase refractive index and cause myopic shift", "Decrease refractive index and cause hyperopic shift", "Increase refractive index and cause hyperopic shift", "Decrease refractive index and cause myopic shift"], "correct": 1, "explanation": "By the stem''s logic, increased lens hydration lowers the refractive index and shifts refraction hyperopic. Note that clinically acute hyperglycemia is usually described as a MYOPIC shift, so VERIFY the key. Hint: the stem''s ''more water = lower index'' predicts hyperopia, but real diabetic swings are often myopic, watch the wording."}'),
  ('2ac790ea-2l','{"options": ["Isopter,,", "Hill of Vision,,", "Visual Field,,", "Scotoma,,"], "correct": -1, "explanation": "An ISOPTER is the boundary separating SEEN from NOT-SEEN for a given target — the contour of equal sensitivity in kinetic perimetry. The hill of vision is the whole 3-D map; the visual field is the space; a scotoma is an island of loss within the field. Isopter = the visibility boundary line. [Source extraction missed the marked option — answer is Isopter.]"}'),
  ('f1033313-2m','{"options": ["Threshold,", "Suprathresold,", "Mesopic,", "Light-Dark Adaptation,"], "correct": 0, "explanation": "THRESHOLD = the ability/level at which a stimulus is just detected at a given location under set conditions (the 50%-seen luminance in perimetry). Suprathreshold is brighter-than-threshold screening; mesopic/adaptation describe lighting states. Threshold = the just-detectable stimulus."}'),
  ('ece37209-8q','{"options": ["Myopic,.,", "Hyperopic,.,", "Emmetropic,.,", "Astigmatism,.,"], "correct": 0, "explanation": "Both eyes are minus (myopic spheres) with significant astigmatism — the overall refractive condition is MYOPIC (the spherical equivalents are minus). The dominant feature is myopia (with astigmatism). Read the spherical equivalent: minus → myopic. Cross-link: the astigmatism type is classified next (Q12)."}'),
  ('150034dc-4i','{"options": ["Paralysis of Accommodation", "Spasm of Accommodation", "Lead of Accommodation", "Convergence excess"], "correct": 1, "explanation": "The A/R (auto-refractor) gave MORE minus than the subjective refraction (instrument myopia / over-minus from machine-stimulated accommodation), and the subjective is less myopic — this pattern of excess accommodation/over-minus on the machine = SPASM of accommodation (accommodation locked in). Paralysis would give less minus/more plus; lead vs lag differ. AR more minus than subjective → accommodative spasm."}'),
  ('0b3b4090-2n','{"options": ["The apparent source of light moves upward /", "No change occurs /", "The apparent source of light moves downward /", "The light reflex disappears/"], "correct": 0, "explanation": "With a CONCAVE retinoscopy mirror, tilting the mirror DOWN makes the apparent light source move UP (the concave mirror reverses the apparent motion). This is why concave-mirror retinoscopy shows reversed reflex motion vs a plane mirror. Optics: concave mirror inverts the apparent source movement."}'),
  ('fa06f40a-1u','{"options": ["It indicates the presence of astigmatism ‘", "It shows hyperopia’", "It indicates a neutral refractive state ‘", "It confirms that the patient has myopia’"], "correct": 0, "explanation": "The SKEW (oblique break) phenomenon — the reflex and the streak move in slightly different (non-parallel) directions as you sweep off-axis — indicates ASTIGMATISM and helps refine the cylinder AXIS (no skew when on-axis). Skew = astigmatic axis is off; rotate to eliminate it. Retinoscopy astigmatism clue."}'),
  ('b8f6a152-1t','{"options": ["Two bands of equal motion,", "c. A with and against motion,", "Two bands of unequal motion ,"], "correct": 2, "explanation": "[Source-flagged: 3 options.] In an ASTIGMATIC eye, retinoscopy shows TWO principal meridians with UNEQUAL (different speed/width) motion — the two foci neutralize at different lens powers. Equal motion = spherical; a ''with-and-against'' split also signals astigmatism but the classic sign is two bands of unequal motion. Astigmatism = two unequal meridional reflexes."}'),
  ('2ddf550f-23','{"options": ["-0.75S = -1.75C X 180 ,", "-2.50S = -1.75C X 180,", "-0.75S = -1.75C X 90,"], "correct": 0, "explanation": "[Source-flagged: 3 options.] Transpose −2.50S = +1.75C × 90 to minus cyl: new sphere = −2.50 + 1.75 = −0.75; new cyl = −1.75; new axis = 90 ± 90 = 180. Result: −0.75S = −1.75C × 180. Transposition steps: add cyl to sphere, flip cyl sign, rotate axis 90°."}'),
  ('ca2508ed-3s','{"options": ["movement’", "neutral point ‘"], "correct": -1, "explanation": "[Source-flagged: options truncated.] In a widely DILATED pupil, the central vs peripheral reflex can differ because of the difference in the NEUTRAL POINT across zones (spherical aberration makes the periphery neutralize at a different power than the center) — the basis of the ''spherical aberration'' artifact in retinoscopy. Check/neutralize on the central zone. [Verify against source.]"}'),
  ('f3c348c8-27','{"options": ["a To prescribe corrective lenses;’", "b To detect underlying ocular and visual abnormalities ;’", "c To conduct only a visual function assessment;’", "d To determine a patient''s eye color;’"], "correct": 1, "explanation": "The basic clinical eye/vision assessment exists primarily to DETECT underlying ocular and visual ABNORMALITIES (screen/diagnose disease and dysfunction), not merely to sell glasses or note eye color. Refraction is one part; the goal is comprehensive detection. Purpose = find abnormalities."}'),
  ('d14ff613-2b','{"options": ["a Blood pressure check ‘’", "c Eye color assessment’’", "b Refractive system assessment ‘’", "d Sleep pattern analysis’’"], "correct": 2, "explanation": "A mandatory optometric exam must include a REFRACTIVE-SYSTEM assessment (the core of determining the optical correction). BP, eye color, and sleep analysis aren''t core mandatory components. Refraction = the essential included element."}'),
  ('fd0e0e23-1s','{"options": ["a Preliminary examination;", "c Visual function assessment;", "b Management plan ;", "d Ocular health examination;"], "correct": 2, "explanation": "The FINAL step of a comprehensive exam is the MANAGEMENT PLAN (diagnosis → plan/treatment/recommendation). Preliminary exam, visual function, and ocular health are earlier stages. Sequence: history → preliminary → refraction/function → ocular health → diagnosis → MANAGEMENT."}')
)
UPDATE question_reviews r
SET payload = r.payload || d.patch::jsonb
FROM d
WHERE r.question_id = d.qid;
